-- ChadcoreMenu: the game's quests by region, from its data files (sys/qst/*): [quest no] = { name, summary }. Generated.
return {
  sd={name='San d\'Oria',[0]={'A Sentry\'s Peril','Client: Glenne (Pikeman\'s Way,\n Southern San d\'Oria)\nSummary:\n Take ointment to the sentry\n Aaveleon. Find him in the woods of\n West Ronfaure.'},[1]={'Waters of the Cheval','Client: Miageau (Cathedral,\n Northern San d\'Oria)\nSummary:\n Draw water from the Cheval River\n in East Ronfaure.'},[2]={'Rosel the Armorer','Client: Rosel (Rosel\'s Armour Shop,\n Southern San d\'Oria)\nSummary:\n Deliver the receipt for the prince\'s\n cloak to the chateau guards.'},[3]={'The Pickpocket','Client: Altiret (Airship Docks,\n Port San d\'Oria)\nSummary:\n Retrieve the gilt glasses stolen by\n the pickpocket.'},[4]={'Father and Son','Client: Ailbeche (Parade Grounds,\n Northern San d\'Oria)\nSummary:\n A child stands crying in the Parade\n Grounds. Find his father for him.'},[5]={'The Seamstress','Client: Hanaa Punaa (Tanners\' Guild,\n Southern San d\'Oria)\nSummary:\n Collect three giant sheepskins\n for Hanaa, and she\'ll make some\n fine clothes for you.'},[6]={'The Dismayed Customer','Client: Gulemont (Rusty Anchor\n Pub, Port San d\'Oria)\nSummary:\n A patron lost a document\n somewhere in West Ronfaure.\n Find it for him.'},[7]={'The Trader in the Forest','Client: Abeaule (Phoenix Perch Inn,\n Northern San d\'Oria)\nSummary:\n Purchase some batagreens from\n Phairet. Find him in the tower on\n the southern fringes of West\n Ronfaure.'},[8]={'The Sweetest Things','Client: Raimbroy (Grocery,\n Southern San d\'Oria)\nSummary:\n Collect five pots of honey for the\n grocer.'},[9]={'The Vicasque\'s Sermon','Client: Abioleget (Cathedral,\n Northern San d\'Oria)\nSummary:\n Deliver blue peas to a friar on\n retreat. Find him in a tower in the\n southeast area of East Ronfaure.'},[10]={'A Squire\'s Test','Client: Balasiel (Watchdog Alley,\n Southern San d\'Oria)\nSummary:\n Obtain a revival tree root from\n King Ranperre\'s Tomb.'},[11]={'Grave Concerns','Client: Andecia (House on Squire\n Alley, Southern San d\'Oria)\nSummary:\n Replace the water for King\n Ranperre\'s gravestone with a fresh\n offering.'},[12]={'The Brugaire Consortium','Client: Fontoumant (Cargo Room B,\n Port San d\'Oria)\nSummary:\n Deliver parcels to their proper\n recipients.'},[13]={'Lizard Skins','Client: Hanaa Punaa (Tanners\' Guild,\n Southern San d\'Oria)\nSummary:\n Collect three lizard skins for\n Hanaa, and she will make you something\n in return.'},[14]={'Flyers for Regine','Client: Regine (Regine\'s\n Magicmart, Port San d\'Oria)\nSummary:\n Hand out fifteen flyers for the\n struggling magic shop. Pass them\n only to townsfolk, not\n adventurers.'},[15]={'Gates to Paradise','Client: Olbergieut (Cathedral\n Manuscript Room, N. San d\'Oria)\nSummary:\n Bring the "Scripture of Wind"\n to a friar on retreat. Find him at\n the Crag of Holla on the La Theine\n Plateau.'},[16]={'A Squire\'s Test II','Client: Balasiel (Watchdog Alley,\n Southern San d\'Oria)\nSummary:\n Journey to the waterfall in\n Ordelle\'s Caves, and bring\n back proof of your visit.'},[17]={'To Cure a Cough','Client: Amaura (Watchdog Alley,\n Southern San d\'Oria)\nSummary:\n Bring Amaura some thyme moss,\n and she\'ll concoct a brew with\n curative powers.'},[18]={'Tiger\'s Teeth','Client: Taumila (Sundries Shop,\n Southern San d\'Oria)\nSummary:\n Collect three black tiger fangs.'},[19]={'Undying Flames','Client: Pagisalis (Cathedral\n Reliquary, Northern San d\'Oria)\nSummary:\n Collect two lumps of beeswax\n for making candles.'},[20]={'A Purchase of Arms','Client: Helbort (Helbort\'s Blades,\n Southern San d\'Oria)\nSummary:\n Find the traveling merchant\n Alexius in Jugner Forest and\n place an order for weapons.'},[21]={'A Knight\'s Test','Client: Balasiel (Watchdog Alley,\n Southern San d\'Oria)\nSummary:\n Solve the riddle of the\n task book.'},[22]={'The Medicine Woman','Client: Abeaule (Inn,\n Northern San d\'Oria)\nSummary:\n A guest at the inn has fallen ill.\n Call on Amaura in Southern San\n d\'Oria to get some cold medicine.'},[23]={'Black Tiger Skins','Client: Hanaa Punaa (Tanners\' Guild,\n Southern San d\'Oria)\nSummary:\n Collect three black tiger hides\n for Hanaa, and she will make you\n something in return.'},[24]={'SDクエスト32','依頼者\n　'},[25]={'SDクエスト33','依頼者\n　'},[26]={'SDクエスト34','依頼者\n　'},[27]={'SDクエスト35','依頼者\n　'},[28]={'SDクエスト36','依頼者\n　'},[29]={'SDクエスト37','依頼者\n　'},[30]={'SDクエスト38','依頼者\n　'},[31]={'SDクエスト39','依頼者\n　'},[32]={'SDクエスト40','依頼者\n　'},[33]={'SDクエスト41','依頼者\n　'},[34]={'SDクエスト42','依頼者\n　'},[35]={'SDクエスト43','依頼者\n　'},[36]={'SDクエスト44','依頼者\n　'},[37]={'SDクエスト45','依頼者\n　'},[38]={'SDクエスト46','依頼者\n　'},[39]={'SDクエスト47','依頼者\n　'},[40]={'SDクエスト48','依頼者\n　'},[41]={'SDクエスト49','依頼者\n　'},[42]={'SDクエスト50','依頼者\n　'},[43]={'SDクエスト51','依頼者\n　'},[44]={'SDクエスト52','依頼者\n　'},[45]={'SDクエスト53','依頼者\n　'},[46]={'SDクエスト54','依頼者\n　'},[47]={'SDクエスト55','依頼者\n　'},[48]={'SDクエスト56','依頼者\n　'},[49]={'SDクエスト57','依頼者\n　'},[50]={'Growing Flowers','Client: Kuu Mohzolhi (Phoenix Perch\n Inn, Northern San d\'Oria)\nSummary:\n Give the tiny Mithra some\n flowers so she can plant them\n in Queen Leaute\'s garden.\n Perhaps something white?'},[51]={'The General\'s Secret','Client: Curilla (Temple Knights\'\n Quarters, Chateau d\'Oraguille)\nSummary:\n Fetch some water from the hot\n spring on the peak of Horlais.'},[52]={'The Rumor','Client: Novalmauge (Bostaunieux\n Oubliette)\nSummary:\n The jailor wants you to bring him\n the blood of a beastman. Some\n people say he is a vampire.'},[53]={'Her Majesty\'s Garden','Client: Chalvatot (Queen Leaute\'s\n Garden, Chateau d\'Oraguille)\nSummary:\n Bring some Derfland humus to use\n as fertilizer so that flowers might\n grow in the late queen\'s garden.'},[54]={'Introduction to Teamwork','Client: Vilatroire (Watchtower,\n Northern San d\'Oria)\nSummary:\n In order to form a cohesive\n party, gather at least one more\n adventurer of the same allegiance.'},[55]={'Intermediate Teamwork','Client: Vilatroire (Watchtower,\n Northern San d\'Oria)\nSummary:\n In order to form a cohesive\n party, gather at least one more\n adventurer of the same race.'},[56]={'Advanced Teamwork','Client: Vilatroire (Watchtower,\n Northern San d\'Oria)\nSummary:\n In order to form a cohesive\n party, gather at least one more\n adventurer of the same job.'},[57]={'Grimy Signposts','Client: Maugie (Eastgate,\n Southern San d\'Oria)\nSummary:\n The four signposts in Jugner Forest\n need scrubbing. Clean them before\n someone gets lost.'},[58]={'A Job for the Consortium','Client: Portaure (Cargo Room B,\n Port San d\'Oria)\nSummary:\n The Brugaire Consortium wants \n you to smuggle a package onto\n the airship and take it to\n the Tenshodo in Jeuno.\n Nighttime is the safest option.'},[59]={'Trouble at the Sluice','Client: Belgidiveau (Sluice Gates,\n Northern San d\'Oria)\nSummary:\n It seems poison was thrown into\n the water near the sluice gates.\n Find an antidote before someone\n falls ill.'},[60]={'The Merchant\'s Bidding','Client: Parvipon (Tanners\' Guild,\n Southern San d\'Oria)\nSummary:\n Fetch three rabbit hides.'},[61]={'Unexpected Treasure','Client: Morunaude (Furniture Store,\n Northern San d\'Oria)\nSummary:\n The small teacup found in a\n cupboard sold at this store\n appears to have royal origins.\n The owner would doubtlessly\n be grateful to have it back.'},[62]={'Blackmail','Client: Dauperiat (Victory Arch,\n Northern San d\'Oria)\nSummary:\n Delivering a strange envelope to\n Monarlais Halver gets you sent on\n a mission to retrieve castle\n floor plans from Orcs in Ghelsba.'},[63]={'The Setting Sun','Client: Vamorcote (Laborman\'s Way, \n Northern San d\'Oria)\nSummary:\n Retrieve the key to a document\n box holding a copy of the castle\n floor plans. The key was buried long\n ago on a small island to the south\n of Batallia Downs.'},[64]={'Distant Loyalties','Client: Femitte (Victory Square,\n Southern San d\'Oria)\nSummary:\n A goldsmith is needed to fill an\n order. Only Elvaan need apply.'},[65]={'The Rivalry','Client: Gallijaux (Wharf,\n Port San d\'Oria)\nSummary:\n Gather carp by any means\n possible so Gallijaux can win a\n fishing contest against his little\n brother, Joulet.'},[66]={'The Competition','Client: Joulet (Wharf,\n Port San d\'Oria)\nSummary:\n Gather carp by any means\n possible so Joulet can win a\n fishing contest against his elder\n brother, Gallijaux.'},[67]={'Starting a Flame','Client: Legata (Lion Springs\n Tavern, Southern San d\'Oria)\nSummary:\n Fetch four stones of flint.'},[68]={'Fear of the Dark','Client: Secodiand (Laborman\'s Way,\n Northern San d\'Oria)\nSummary:\n Fetch two bat wings.'},[69]={'Warding Vampires','Client: Maloquedil (Parade Grounds,\n Northern San d\'Oria)\nSummary:\n Fetch two cloves of Orc garlic\n to keep vampires away.'},[70]={'Sleepless Nights','Client: Paouala (House on Squire\n Alley, Southern San d\'Oria)\nSummary:\n Paouala cannot sleep, so bring her\n some Mary\'s Milk to cure her\n insomnia.'},[71]={'Lufet\'s Lake Salt','Client: Nogelle (Rusty Anchor Pub,\n Port San d\'Oria)\nSummary:\n Fetch three chunks of salt from \n Lufet\'s Lake. Beans at the Rusty\n Anchor are famous for their special\n salty taste.'},[72]={'Healing the Land','Client: Eperdur (Cathedral,\n Northern San d\'Oria)\nSummary:\n Spirits of the dead in the Gusgen\n Mines blow an evil wind upon the\n land. Take a seal of banishing to a\n shack in the deepest tunnel within.'},[73]={'Sorcery of the North','Client: Eperdur (Cathedral,\n Northern San d\'Oria)\nSummary:\n An ancient tome of magic is lost.\n Journey to Fei\'Yin and find\n another to replace it.'},[74]={'The Crimson Trial','Client: Sharzalion (Lion Springs\n Tavern, Southern San d\'Oria)\nSummary:\n Retrieve some Orcish dried food\n from a storage hole in Davoi.\n Sharzalion will let you in on\n something in return.'},[75]={'Enveloped in Darkness','Client: Curilla (Temple Knights\'\n Quarters, Chateau d\'Oraguille)\nSummary:\n Investigate reports of a ghost\n in the cathedral.'},[76]={'Peace for the Spirit','Client: Curilla (Temple Knights\'\n Quarters, Chateau d\'Oraguille)\nSummary:\n The spirit of Curilla\'s father\n Rainemard seems to be trying\n to say something.'},[77]={'Messenger from Beyond','Client: Narcheral (Cathedral,\n Northern San d\'Oria)\nSummary:\n On the westernmost dune of\n Valkurm, a dark stalker lurks.\n Defeat it and bring back\n its Tavnazia pass.'},[78]={'Prelude of Black and White','Client: Narcheral (Cathedral,\n Northern San d\'Oria)\nSummary:\n White mages of renown will\n be given a blessed item for the\n war against the undead. But first,\n they must bring Yagudo holy water\n to prove their worth.'},[79]={'Pieuje\'s Decision','Client: Narcheral (Cathedral,\n Northern San d\'Oria)\nSummary:\n Once you\'ve found a Tavnazia\n bell in the Eldieme Necropolis,\n journey to Fei\'Yin and commence\n the battle against the undead.'},[80]={'Sharpening the Sword','Client: Ailbeche (Parade Grounds,\n Northern San d\'Oria)\nSummary:\n The boy needs a whetstone\n to sharpen an old blade. Find\n one for him in Ordelle\'s\n Caves.'},[81]={'A Boy\'s Dream','Client: Ailbeche (Parade Grounds,\n Northern San d\'Oria)\nSummary:\n All fishermen dream of hooking\n the big one. Catch him and obtain\n the treasure in his belly.'},[82]={'Under Oath','Client: Trion (Prince Royal\'s Room,\n Chateau d\'Oraguille)\nSummary:\n Knights whisper of a traitor in\n their midst. An outsider is needed\n to investigate.'},[83]={'The Holy Crest','Client: Oiheaurese (Cathedral,\n Northern San d\'Oria)\nSummary:\n Excavate the wyvern egg that\n lies beneath the Maze of\n Shakhrami. Protect it from\n dragonslayers.'},[84]={'A Craftsman\'s Work','Client: Miaux (Near the Blacksmiths\'\n Guild, Northern San d\'Oria)\nSummary:\n To have her father\'s breastplate\n repaired by Ranchuriome, Miaux\n needs you to find an Altepa\n polishing stone.'},[85]={'Chasing Quotas','Client: Ceraulian (Cargo Room A,\n Port San d\'Oria)\nSummary:\n Ceraulian of the Brugaire\n Consortium needs your help to\n meet his quota.'},[86]={'Knight Stalker','Client: Rahal (Royal Knights\'\n Quarters, Chateau d\'Oraguille)\nSummary:\n Rahal wants you to gather\n information regarding the\n attacks on the Royal Knights.'},[87]={'+Eco-Warrior','Client: Norejaie (Lion Springs Tavern,\n Southern San d\'Oria)\nSummary:\n Norejaie wants you to exterminate an\n ecological threat, in Ordelle\'s Caves,\n according to Rojaireaut\'s instructions,\n and bring her evidence of\n the feat.\n'},[88]={'Methods Create Madness','Client: Balasiel (Watchdog Alley,\n Southern San d\'Oria)\nSummary:\n Balasiel requires your assistance in\n constructing a new set of polearm\n training guidelines for the San d\'Orian\n knights.'},[89]={'Souls in Shadow','Client: Novalmauge (Bostaunieux\n Oubliette)\nSummary:\n Lift the curse on the scythe that\n Novalmauge has given you and gain\n a new weapon technique.\n'},[90]={'A Taste for Meat','Client: Thierride (Rusty Anchor Pub,\n Port San d\'Oria)\nSummary:\n Fetch five slices of hare meat.'},[91]={'Exit the Gambler','Clients: Aurege and Guilberdrier\n (Carpenters\' Guild,\n Northern San d\'Oria)\nSummary:\n Varchet of the Carpenters\' Guild\n has run off again. Find the slacker\n and get him back to work.'},[92]={'Old Wounds','Client: Curilla (Temple Knights\'\n Quarters, Chateau d\'Oraguille)\nSummary:\n Curilla has agreed to help you\n polish your single-handed sword skills\n for the upcoming tourneys.'},[93]={'+Escort for Hire (San d\'Oria)','Client: Rondipur (Near the\n Blacksmiths\' Guild, Northern San d\'Oria)\nSummary:\n You are to escort Cannau to her\n desired destination within the\n Eldieme Necropolis.'},[94]={'+A Discerning Eye (San d\'Oria)','Client: Eddy (Airship Dock,\n Port San d\'Oria)\nSummary:\n You have been asked to return a\n dropped item to its rightful owner.\n The passenger should be on the next\n airship flight.'},[95]={'A Timely Visit','Client: Elmemague (Watchdog Alley,\n Southern San d\'Oria)\nSummary:\n A criminal suspect has been\n spotted on La Theine Plateau.\n You have been asked to assist\n in his capture.'},[96]={'Fit for a Prince','Client: Halver (Main Hall,\n Chateau d\'Oraguille)\nSummary:\n You are to find a suitable bride\n for Prince Trion based on the\n requirements explained to you.'},[97]={'Over the Hills and Far Away','Client: Antreneau (Rusty Anchor\n Pub, Port San d\'Oria)\nSummary:\n Antreneau\'s Uncle Louverance set out\n on a journey to cross the Uleguerand\n Range quite some time ago.\n Antreneau tells you that the other\n side of the mountains can be reached\n through a cave found on the slopes\n of Thousandfall Ridge...'},[98]={'Signed in Blood','Client: Sobane (House on Pikeman\'s\n Way, Southern San d\'Oria)\nSummary:\n Sobane has heard some disturbing\n news from her husband, the head\n royal chef. She wishes to make a\n request concerning that tale, but\n first requires you to bring a\n "cathedral tapestry" to prove your\n integrity.'},[99]={'Tea with a Tonberry?','Client: Sobane (House on Pikeman\'s\n Way, Southern San d\'Oria)\nSummary:\n According to Sobane\'s husband\n Ondieumais, the count who owns\n the Carpenters\' Landing territory is\n being threatened. Find a way to\n communicate with the Tonberries of\n Carpenters\' Landing and discover\n who is making these threats.'},[100]={'+Spice Gals','Client: Rouva (Victory Square,\n Southern San d\'Oria)\nSummary:\n Rouva needs a sprig of the rare\n Rivernewort to spruce up her\n succulent suppers.'},[101]={'SDクエスト111','依頼者\n　'},[102]={'Lure of the Wildcat (San d\'Oria)','Client: Amutiyaal (Lion Square,\n Southern San d\'Oria)\nSummary:\n The mercenary company\n "Salaheem\'s Sentinels" has asked\n you to help recruit new members.'},[103]={'Atelloune\'s Lament','Southern San d\'Oria,\n in front of the fountain)\nSummary:\nHelp distressed Atelloune straighten\n out a young Elvaan brat by bringing\n her some ladybug wings that will\n blow his mind.'},[104]={'SDクエスト115','依頼者\n　'},[105]={'SDクエスト116','依頼者\n　'},[106]={'Thick Shells','Client: Vounebariont (Auction House,\n Port San d\'Oria)\nSummary:\n Collect five beetle shells\n suitable for making medicine.'},[107]={'Forest for the Trees','Client: Ramua (Carpenters\' Guild,\n Northern San d\'Oria)\nSummary:\n The overworked Ramua asks for your\n aid in collecting timber samples for a\n guild survey that she\'s been too busy\n to conduct herself.'},[108]={'Trust: San d\'Oria','Client: Gondebaud (Lion Square,\n Southern San d\'Oria)\nSummary:\n Gondebaud of the Jeuno Institute of\n Magical Studies has introduced you to\n the Trust initiative and asked you to\n visit Excenmille in Northern San d\'Oria.'},[109]={'SDクエスト120','依頼者\n　'},[110]={'Trial-Size Trial by Ice','Client: Castilchat (Watchtower,\n Northern San d\'Oria)\nSummary:\n The Rhinostery has developed a\n new "mini" tuning fork of ice.\n Ringing it upon the protocrystal\n in Fei\'Yin will open the path\n to a one-on-one battle with\n the beast that awaits inside.\n However, only summoners are\n allowed to take up this challenge.'},[111]={'+Trial by Ice','Client: Gulmama (Watchtower,\n Northern San d\'Oria)\nSummary:\n Ring the tuning fork of ice upon\n the protocrystal in Fei\'Yin.\n A path will open to the trial\n that awaits.'}},
  bs={name='Bastok',[0]={'The Siren\'s Tear','Client: Wahid (South Auction House,\n Bastok Mines)\nSummary:\n Find the Siren\'s Tear for Wahid.\n This rare gem is known to\n occasionally appear on the\n shores of the Gustaberg River.\n Seek the bard in the Port Bastok\n restaurant and listen to his story.'},[1]={'Beauty and the Galka','Clients: Cornelia & Parraggoh\n (House, Bastok Mines)\nSummary：\n Bring a chunk of zinc ore\n to Talib of the Tenshodo in\n Parraggoh\'s stead.\n Monsters in Gustaberg are\n known to drop the ore.'},[2]={'Welcome to Bastok','Client: Powhatan (Steaming Sheep\n Restaurant, Port Bastok)\nSummary:\n Greet Powhatan\'s guest at the\n air travel agency.\n Wear a shell shield so\n he\'ll know who you are.'},[3]={'Guest of Hauteur','Client: Powhatan (Steaming Sheep\n Restaurant, Port Bastok)\nSummary:\n Greet Powhatan\'s guest at the\n air travel agency.\n Wear a maul on your hip so\n he\'ll know who you are.'},[4]={'The Quadav\'s Curse','Client: Corann (House, Port Bastok) \nSummary:\n Corann wants to shut himself away\n from the rest of the world.\n Find him an item to hide\n in--something big enough to\n hide his whole body.'},[5]={'Out of One\'s Shell','Client: Ronan (House, Port Bastok)\nSummary:\n Ronan wants you to help him get\n his son, Corann, "to come out of\n his shell."\n (Or at least his Quadav shell...)'},[6]={'Hearts of Mythril','Client: Elki (Bat\'s Lair Inn,\n Bastok Mines)\nSummary:\n Go to North Gustaberg and lay\n Elki\'s bouquet at the foot of\n the monument honoring the\n Palborough Pioneers.'},[7]={'The Eleventh\'s Hour','Client: Elki (Bat\'s Lair Inn,\n Bastok Mines)\nSummary:\n Elki wants you to find information\n regarding the identity of the\n eleventh Palborough Pioneer.\n You might be able to find some\n hints in the mines themselves.'},[8]={'Shady Business','Client: Talib (Tenshodo Warehouse,\n Port Bastok)\nSummary:\n Talib of the Tenshodo is buying\n zinc.\n Bring him four chunks of the ore\n to receive gil.'},[9]={'A Foreman\'s Best Friend','Client: Gudav (Construction Site,\n Port Bastok)\nSummary:\n Gudav wants you to investigate\n the whereabouts of his crew\'s\n foreman.'},[10]={'Breaking Stones','Client: Horatius (Trader\'s Home,\n Bastok Markets)\nSummary:\n Horatius wants you to bring him\n a rare stone that can only be\n found in Dangruf Wadi (J-5).\n It can only be found in daytime.'},[11]={'The Cold Light of Day','Client: Malene (House, Bastok\n Markets)\nSummary:\n A monster that appears near the\n lighthouse in South Gustaberg\n has stolen a package addressed\n to Malene.\n Ask the adventurer Dalzakk how\n to lure the beast out, and recover\n the item.'},[12]={'Gourmet','Client: Salimah (Trader\'s Home,\n Bastok Markets)\nSummary:\n Salimah is looking for a special\n ingredient to spice up the dish\n she\'s preparing.'},[13]={'+The Elvaan Goldsmith','Client: Michea (House, Bastok\n Markets)\nSummary:\n Help Michea, a free goldsmith,\n complete her order by bringing\n her a copper ingot.'},[14]={'A Flash in the Pan','Client: Aquillina (House, Bastok\n Markets)\nSummary:\n Sell four flint stones to Aquillina\n so she can light her oven.'},[15]={'Smoke on the Mountain','Client: Hungry Wolf (Craftsmen\'s\n Eatery, Metalworks)\nSummary:\n Hungry Wolf wants you to bring\n him a Galkan sausage, a dish that\n his co-worker, Offa, told him was\n marvelously delectable.'},[16]={'Stamp Hunt','Client: Arawn (Gold Street, Bastok\n Markets)\nSummary:\n Go stamp hunting!\n Get all the stamps for Arawn\'s\n stamp sheet from guards all over\n Bastok.'},[17]={'Forever to Hold','Client: Qiji (Docks, Port Bastok)\nSummary:\n Qiji wants you to get him\n a brass hairpin to give to\n his wife, Romilda, as a present.'},[18]={'Till Death Do Us Part','Client: Romilda (Docks, Port Bastok)\nSummary:\n Romilda wants you to get her\n a pair of cotton gloves to give\n to her husband, Qiji, as a present.'},[19]={'Fallen Comrades','Client: Pavvke (House, Bastok\n Mines)\nSummary:\n Bring Pavvke the name tags\n of the Galka who lost their lives\n in the Palborough Mines twenty\n years ago.'},[20]={'Rivals','Client: Detzo (Ore Street, Bastok\n Mines)\nSummary:\n Lend Detzo a mythril sallet\n so he can win a contest against\n his rival.'},[21]={'Mom, the Adventurer?','Client: Nbu Latteh (Gold Street,\n Bastok Markets)\nSummary:\n Bring Nbu Latteh\'s daughter a\n copper ring as a gift from her\n mother.'},[22]={'The Signpost Marks the Spot','Client: Nbu Latteh (Gold Street,\n Bastok Markets)\nSummary:\n Find the key item buried under\n one of the signposts on the\n Konschtat Highlands and bring\n it to Nbu Latteh\'s house.'},[23]={'Past Perfect','Client: Evi (Harbor Way,\n Port Bastok)\nSummary:\n Bring Evi his old mission orders,\n buried near one of the windmills\n on the Konschtat Highlands.'},[24]={'Stardust','Client: Baldric (Darksteel Forge,\n Metalworks)\nSummary:\n Baldric wants you to bring him\n a pinch of Valkurm sunsand\n for one of his experiments.\n It is said to only appear during\n dust storms.'},[25]={'Mean Machine','Client: Unlucky Rat (Cermet Refinery,\n Metalworks)\nSummary:\n One of the factory\'s machines\n needs oiling, but Unlucky Rat is\n out of machine oil.\n Help him out by bringing him\n something that can be used\n as a substitute.'},[26]={'Cid\'s Secret','Client: Cid (Cid\'s Lab, Metalworks)\nSummary:\n Do Cid a personal favor.\n Go see if there is any way you\n can help the manager of the\n Steaming Sheep Restaurant.'},[27]={'The Usual','Client: Hilda (Steaming Sheep\n Restaurant, Port Bastok)\nSummary:\n Bring a king truffle to Hilda\n so she can serve it to an old\n Steaming Sheep customer.'},[28]={'Blade of Darkness','Summary:\n Zeid, the sole master of the way\n of the dark knight in Vana\'diel,\n has been sighted in the Palborough\n Mines. If you seek him out, he may\n make you an apprentice...'},[29]={'Father Figure','Client: Michea (House, Bastok\n Markets)\nSummary:\n Bring Michea a silver ingot\n so that she may craft a present\n for her surrogate father, Dalzakk.'},[30]={'The Return of the Adventurer','Client: Gwill (House, Bastok\n Markets)\nSummary:\n Gwill needs some cinnamon\n to put the final touch on a\n present he\'s making for Dalzakk.'},[31]={'Drachenfall','Client: Black Mud (Ore Street,\n Bastok Mines)\nSummary:\n Black Mud has asked you to fetch\n him some Drachenfall water from\n North Gustaberg.'},[32]={'Vengeful Wrath','Client: Goraow (Ore Street Stairs,\n Bastok Mines)\nSummary:\n Kill some Quadav to avenge\n Goraow\'s fallen comrades, and\n bring back a Quadav helm as\n proof of your deeds.'},[33]={'Beadeaux Smog','Client: High Bear (Watermill Square,\n Metalworks)\nSummary:\n High Bear needs a sample of some\n polluted dirt from Beadeaux for\n his ecological research.\n Take the sample from a spot where\n the ground is releasing excessive\n amounts of smoke.'},[34]={'The Curse Collector','Client: Zon-Fobun (Near Sororo\'s,\n Bastok Markets)\nSummary:\n Let the magical statues in\n Beadeaux--the Afflictors and the\n Mutes--cast their curses on you\n to capture their spells on\n Zon-Fobun\'s cursepaper.'},[35]={'Fear of Flying','Client: Kurando (Docks, Port\n Bastok)\nSummary:\n Kurando claims airships are\n dangerous--that every time\n one passes over the Rolanberry\n Fields, a horrible beast appears.\n He needs you to bring back\n whatever the beast drops as\n proof to back his claims.'},[36]={'The Wisdom of Elders','Client: Benita (House, Port Bastok)\nSummary:\n The chimney in Benita\'s house is\n clogged with soot. Her\n mother-in-law, who\'s gone outside\n with Benita\'s daughter, knows the\n perfect item for clearing\n chimneys. Go consult the elderly\n woman, and find the item.'},[37]={'Groceries','Client: Tami (Near Residential Area,\n Bastok Mines)\nSummary:\n Hand Tami\'s note to her husband,\n Zelman, a miner in the Zeruhn\n Mines.'},[38]={'The Bare Bones','Client: Degenhard (Near Galkan\n Bridge, Bastok Markets)\nSummary:\n Bring Degenhard the item that he\n uses to keep himself youthful.'},[39]={'Minesweeper','Client: Gerbaum (Work Area, Bastok\n Mines)\nSummary:\n Rid the Zeruhn Mines of a few\n monsters to keep them off the\n miners\' backs.\n Bring three pinches of Zeruhn\n soot to Gerbaum as proof of\n your success.'},[40]={'The Darksmith','Client: Mighty Fist (Darksteel Forge,\n Metalworks)\nSummary:\n Mighty Fist\'s forge is running low\n on darksteel ore, and he has asked\n you bring him two chunks of it. \n The Gusgen Mines is known to yield\n darksteel, but some claim to have\n dug a few chunks from the Zeruhn\n Mines.'},[41]={'Buckets of Gold','Client: Foss (Firewater Circle,\n Bastok Markets)\nSummary:\n Foss is willing to buy rusty buckets\n off you, if you happen to catch five\n of them.'},[42]={'The Stars of Ifrit','Client: Agapito (Near Air Travel\n Agency, Port Bastok)\nSummary:\n Agapito wants you to find out the\n meaning of the following words:\n "Under a full moon, toward the\n stars of Ifrit, a bird delivers a\n letter to the ship in the sky."\n Also, try to bring back this "letter"\n to satisfy Agapito\'s curiosity.'},[43]={'Love and Ice','Client: Carmelo\n (Steaming Sheep Restaurant,\n Port Bastok)\nSummary:\n Carmelo wants to start his life anew.\n You must go throw the song sheet he\n had written for his former love into\n the Mirror Lake on the Beaucedine\n Glacier.'},[44]={'Brygid the Stylist','Client: Brygid (Gold Street, Bastok\n Markets)\nSummary:\n Brygid, the "stylist extraordinaire,"\n gave you some fashion advice: she\n wants you to come back wearing\n a robe and a bronze subligar.'},[45]={'The Gustaberg Tour','Client: Izabele (Near Cid\'s Lab,\n Metalworks)\nSummary:\n You have been asked to form a\n party with two or more people of\n level fifteen and below to test\n Izabele\'s business idea.\n Your party is to make its way to\n Drachenfall in North Gustaberg\n where Hunting Bear, Izabele\'s\n partner, is waiting.'},[46]={'Bite the Dust','Client: Yazan (Harbor Way, Port\n Bastok)\nSummary:\n Yazan\'s business is in peril--vicious\n sand bats are disrupting the trade\n route between Selbina and Bastok.\n Hunt down these bats, and bring\n Yazan a sand bat fang as proof of\n your success.'},[47]={'Blade of Death','Summary:\n You\'ve received a letter from the\n dark knight, Zeid.\n He says he has a new trial for you\n and Chaosbringer.'},[48]={'Silence of the Rams','Client: Paujean (Tenshodo\n Warehouse, Port Bastok)\nSummary:\n You are being tested by the\n Tenshodo.\n Defeat the two monstrous rams\n in the wild and bring back their\n horns--a rampaging horn and a\n lumbering horn--to Paujean.'},[49]={'Altana\'s Sorrow','Client: Virnage (Bat\'s Lair Inn,\n Bastok Mines)\nSummary:\n Virnage needs a bucket of divine paint\n to restore the statue of Altana to\n Her former glory.\n He advised you to look for it in a\n citadel on the Sauromugue Champaign.'},[50]={'A Lady\'s Heart','Client: Valah Molkot (Near\n Residential Area, Port Bastok)\nSummary:\n Valah, the Mithra girl, wants you to\n impress her with a certain gift.\n Perhaps something red?'},[51]={'Ghosts of the Past','Client: Oggbi (Steaming Sheep\n Restaurant, Port Bastok)\nSummary:\n You are to go to the Gusgen Mines\n and pass the same trial as Oggbi\'s\n former student, Cornelia.\n Use a pickaxe on a certain hole in\n the mines to lure the Wandering\n Ghost out. Defeat it and bring back\n its "miner\'s pendant."'},[52]={'The First Meeting','Client: Oggbi (Steaming Sheep\n Restaurant, Port Bastok)\nSummary:\n You have been asked to head to\n Fei\'Yin and help Dalzakk, one of\n Oggbi\'s students, with his task.'},[53]={'True Strength','Client: Ayame (Cannonry,\n Metalworks)\nSummary:\n You must defeat a powerful Yagudo\n in Castle Oztroja.\n The Yagudo in question can be lured\n out with a bottle of Yagudo drink.'},[54]={'The Doorman','Client: Phara (Near\n Residential Area, Bastok Mines)\nSummary:\n Phara needs some sword grip material\n to repair her son\'s sword.\n The material can be found in a tent\n in Davoi.\n Once repaired, Phara wants to give\n the sword to her grandson.'},[55]={'The Talekeeper\'s Truth','Client: Deidogg (Ore Street,\n Bastok Mines)\nSummary:\n Deidogg wants to prove that the\n Talekeeper Raogrimm was no hero.\n First, he wants you to defeat the\n Quadav nest guardian in the\n Palborough Mines that Raogrimm\n claimed to have killed, and take\n from it the mottled Quadav egg the\n Talekeeper failed to bring back.'},[56]={'The Talekeeper\'s Gift','Client: Deidogg (Ore Street,\n Bastok Mines)\nSummary:\n Raogrimm\'s gift to the San d\'Orians\n was stolen by a band of Goblin\n thieves from the Behemoth\'s Dominion.\n The Musketeers are in search of the\n item, but Deidogg wants you to\n take it for yourself.'},[57]={'Dark Legacy','Client: Raibaht (Cid\'s Lab,\n Metalworks)\nSummary:\n You have been asked to find and\n bring back a book pertaining to\n the Galka\'s darksteel formula.'},[58]={'Dark Puppet','Client: Cid (Cid\'s Lab,\n Metalworks)\nSummary:\n Zeid\'s letter to Cid reports him\n finding one of the weapons forged\n by Gerwitz, the legendary darksteel\n smith...but it has taken the form\n of an evil weapon.\n You must meet Zeid and help him\n with his task.'},[59]={'Blade of Evil','Client: Zeid\nSummary:\n One of Gerwitz\'s weapons is running\n amok.\n You must go to the place where the\n Crystal Lines converge, use the blood\n of a powerful Quadav to lure it out,\n and then defeat the evil weapon\n that appears.'},[60]={'Ayame and Kaede','Client: Ensetsu (House, Port Bastok)\nSummary:\n Ensetsu wishes to reclaim an item\n he has sold to the Tenshodo, but\n they will not exchange it for anything\n other than a "strangely shaped coral"\n from the Korroloka Tunnel.\n You must go and retrieve it for him.'},[61]={'A Test of True Love','Client: Carmelo (Steaming Sheep\n Restaurant, Port Bastok)\nSummary:\n To help save Dariah from her strange\n illness, you must gather the pages of\n the "Chanson de Liberte." The missing\n parts--"Un Moment," "L\'Ephemere," and\n "L\'Ancienne"--lie scattered about in\n various locations around Vana\'diel.'},[62]={'Lovers in the Dusk','Client: Carmelo (Steaming Sheep\n Restaurant, Port Bastok)\nSummary:\n Carmelo would like you to take the\n completed "Chanson de Liberte" to a\n place in the Sanctuary of Zi\'Tah where\n "clear spring water bubbles up around\n a ring of white-flowered trees" and\n bury it there at dusk.'},[63]={'Wish Upon a Star','Client: Enu (Firewater Circle,\n Bastok Markets)\nSummary:\n Fallen stars are said to grant any\n wish. Enu wants you to bring one\n back from a southern jungle. She\n thinks it might be hidden inside\n a tree.'},[64]={'+Eco-Warrior','Client: Raifa (Steaming Sheep\n Restaurant, Port Bastok)\nSummary:\n Raifa wants you to exterminate an\n ecological threat, in Gusgen Mines,\n according to Degga\'s wishes, and\n bring back evidence of the feat.'},[65]={'The Weight of Your Limits','Client: Iron Eater (In front\n of the President\'s Office, Metalworks)\nSummary:\n Use the axe given to you by\n Iron Eater to test your might.\n When you feel that you have reached\n your limits, bring the weapon back\n to the President\'s Office.'},[66]={'Shoot First, Ask Questions Later','Client: Cid (Cid\'s Lab,\n Metalworks)\nSummary:\n Cid would like you to assist him\n in testing a new firearm. Return to\n the lab when the weapon no longer\n functions properly.'},[67]={'Inheritance','Client: Gumbah (House,\n Bastok Mines)\nSummary:\n Gumbah has received a letter from\n the Dark Knight, Zeid. This\n correspondence states that to prevent\n Werei\'s technique from fading into\n oblivion, we are to train with\n a certain sword the great warrior\n left behind.'},[68]={'The Walls of Your Mind','Client: Oggbi (Steaming Sheep\n Restaurant, Port Bastok)\nSummary:\n Use the cesti granted to you by\n Master Oggbi to break the barriers\n that cloud your spirit. When you\n feel the weapon can assist you no\n further, return to the master for\n further instructions.'},[69]={'+Escort for Hire (Bastok)','Client: Trilok (Steaming Sheep\n Restaurant, Port Bastok)\nSummary:\n You are to escort Olavia to her\n desired destination within the\n Crawlers\' Nest.'},[70]={'+A Discerning Eye (Bastok)','Client: Grin (Airship Dock,\n Port Bastok)\nSummary:\n You have been asked to return a\n dropped item to its rightful owner.\n The passenger should be on the next\n airship flight.'},[71]={'Faded Promises','Client: Ayame (Cannonry,\n Metalworks)\nSummary:\n You are to seek out the person\n sending threatening letters to\n Senator Alois and eliminate him.\n First, you must find a diary hidden\n somewhere in the Palborough Mines\n and take it to Kagetora of the\n Tenshodo.'},[72]={'+Brygid the Stylist Returns','Client: Brygid (Gold Street, Bastok\n Markets)\nSummary:\n Brygid, the "stylist extraordinaire,"\n has given you more fashion advice,\n so it\'s time to go shopping.'},[73]={'Out of the Depths','Client: Ayame (Cannonry,\n Metalworks)\nSummary:\n A Goblin lair known as Movalpolos\n has suddenly appeared in North\n Gustaberg.\n Ayame wishes you to investigate\n this lair with the cooperation\n of a visiting scholar waiting in\n Port Bastok.'},[74]={'A Question of Faith','Client: Ayame (Cannonry,\n Metalworks)\nSummary:\n A holy tome was among the items\n you retrieved from Movalpolos.\n A friar known as Virnage is asking\n for the help of an adventurer to\n investigate this matter further.'},[75]={'Return to the Depths','Client: Ayame (Cannonry,\n Metalworks)\nSummary:\n You are to find the one who\n speaks both the common and the\n Moblin language, and learn more\n about the city of Movalpolos.'},[76]={'Teak Me to the Stars','Client: Raibaht (Cid\'s Lab,\n Metalworks)\nSummary:\n Cid is secretly developing a new\n airship, but is low on Garhada teak\n needed to build its sleek interior.'},[77]={'Hyper Active','Client: Raibaht (Cid\'s Lab,\n Metalworks)\nSummary:\n The adventurer hired to bring Cid a\n hyper altimeter has been arrested\n and ordered to kill a monster named\n Orna in Delkfutt\'s Tower. Find the\n man and obtain the equipment.'},[78]={'The Naming Game','Client: Raibaht (Cid\'s Lab,\n Metalworks)\nSummary:\n Cid\'s dream of completing a "semi-\n perpetual motion engine" can only\n be realized if he obtains a chunk of\n legendary ordrynite.'},[79]={'+All by Myself','Client: Marin (Kulatz Bridge,\n Bastok Markets)\nSummary:\n Marin wants you to watch over her\n little brother Ken, and make sure\n nothing happens to him during his\n military academy exam. Hopefully,\n this does not count as cheating...'},[80]={'Chips','Client: Cid (Cid\'s Lab,\n Metalworks)\nSummary:\n You\'ve learned from the Tenshodo\n that Chief Cid is collecting rare\n colored chips found in the ruins of\n Pso\'Xja. Bring him a set of three\n (one carmine chip, one gray chip,\n and one cyan chip) to receive your\n reward.'},[81]={'Bait and Switch','Client: Salim (Near the\n Gunpowder Room, Metalworks)\nSummary:\n Lately, a strange friar\n has been snooping around\n the Temple of the Goddess.\n Salim wants you to get rid of him.'},[82]={'Lure of the Wildcat (Bastok)','Client: Alib-Mufalib (Beligen Square,\n Port Bastok)\nSummary:\n The mercenary company\n "Salaheem\'s Sentinels" has asked\n you to help recruit new members.'},[83]={'Achieving True Power','Client: Shamarhaan (Firewater Circle,\n Bastok Markets)\nSummary:\n If you desire even greater strength,\n find a "puppetmaster\'s testimony"\n and bring it to Shamarhaan.'},[84]={'Too Many Chefs','Client: Ferghus (Craftsmen\'s Eatery,\n Metalworks)\nSummary:\n The new apprentice cook is being\n blamed for everything that goes\n wrong in the eatery, and today\n doesn\'t seem to be any different...'},[85]={'A Proper Burial','Client: Offa (House, Bastok Markets)\nSummary:\n The time capsule containing letters\n written by Offa and his friends\n during the war has been plundered\n by Goblins. He sure would like to\n know what his childhood dreams\n were...'},[86]={'Fully Mental Alchemist','Client: Titus (Alchemists\' Guild,\n Bastok Mines)\nSummary:\n An eccentric alchemical innovator has\n beseeched your aid in completing his\n revolutionary research. Procure twenty\n grains of gold dust from Grauberg and\n deliver them back to his laboratory\n for your reward.'},[87]={'Synergistic Pursuits','Client: Hildolf (Synergy Institute,\n Metalworks)\nSummary:\n To obtain a crucible and take your\n first step into the wondrous world of\n synergy, you\'ll need to track down an\n earth crystal, a flint stone, an onz of\n mythril sand, and a brass tank.'},[88]={'The Wondrous Whatchamacallit','Client: Selliste (Alchemists\' Guild,\n Bastok Mines)\nSummary:\n A scatterbrained inventress is hard at\n work on a miraculous device that will\n revolutionize the art of synergy in\n some manner or another. Use your\n synergy prowess to fashion her some\n astral matter, and you will be\n handsomely rewarded.'},[89]={'Synergistic Support','Client: Hildolf (Synergy Institute,\n Metalworks)\nSummary:\n Ever interested in seeing his students\n expand their horizons, Bastok\'s chief\n synergy researcher has given you a\n valuable lesson in synthesizing your\n own fewell. He\'s even offered you a\n selection from his own stock to boot!'},[90]={'Trust: Bastok','Client: Clarion Star (Beligen Square,\n Port Bastok)\nSummary:\n Clarion Star of the Jeuno Institute of\n Magical Studies has introduced you to\n the Trust initiative and asked you to\n visit Naji in the Metalworks.'},[91]={'BSクエスト93','依頼者\n　'},[92]={'BSクエスト94','依頼者\n　'},[93]={'BSクエスト95','依頼者\n　'},[94]={'BSクエスト96','依頼者\n　'},[95]={'BSクエスト97','依頼者\n　'},[96]={'BSクエスト99','依頼者\n　'},[97]={'BSクエスト99','依頼者\n　'},[98]={'Trial-Size Trial by Earth','Client: Ferrol (Near drawbridge,\n Port Bastok)\nSummary:\n The Rhinostery has developed a\n new "mini" tuning fork of earth.\n Ringing it upon the protocrystal\n in the Quicksand Caves will open\n the path to a one-on-one battle\n with the beast that awaits inside.\n However, only summoners are\n allowed to take up this challenge.'},[99]={'+Trial by Earth','Client: Juroro (Near drawbridge,\n Port Bastok)\nSummary:\n Ring the tuning fork of earth upon\n the protocrystal in the Quicksand\n Caves. A path will open to the \n trial that awaits.'}},
  ws={name='Windurst',[0]={'In a Pickle','Client: Chamama\n (Rarab Tail Hostelry, Windurst Waters)\nSummary:\n The weighting stone used to make\n the Rarab Tail Hostelry\'s specialty\n dish, "Rarab Tail Pickles," was\n broken.\n Chamama wants you to find her a \n replacement stone that is just the\n right size, shape, and weight.\n'},[1]={'A Pose by Any Other Name','Client: Angelica\n (Hostelry Room, Windurst Waters)\nSummary:\n Angelica wants you to model for her\n next painting, but your taste in\n clothes doesn\'t match her current\n mood. Go find the clothes she likes\n and come back wearing them...\n before she changes her mind.\n'},[2]={'Acting in Good Faith','Client: Gantineux\n (Hostelry Room, Windurst Waters)\nSummary:\n Gantineux wants you to help him\n in his study of white magic. Go to\n the Eldieme Necropolis and offer\n up "spirit incense" at the dimly\n flickering candle to try and\n appease the spirits of the dead.\n'},[3]={'Say It with Flowers','Client: Moari-Kaaori\n (House, Windurst Waters)\nSummary:\n Help the poor love-struck youth by\n going to the Rhinostery and buying\n him the perfect flower he needs to\n win over his sweetheart.\n'},[4]={'Hat in Hand','Client: Baren-Moren\n (Hat Shop, Windurst Waters)\nSummary:\n Advertise Baren-Moren\'s latest\n creation by chatting with the local\n inhabitants of Windurst Waters.\n He\'ll pay you according to the\n number of townsfolk you speak to.\n But, you are not to leave Windurst\n Waters before completing the task.\n'},[5]={'A Feather in One\'s Cap','Client: Baren-Moren\n (Hat Shop, Windurst Waters)\nSummary:\n Baren-Moren has been requested by\n a certain lady to make an extra-\n luxurious hat. He wants your help\n in collecting the giant bird feathers\n he needs to finish off his master-\n piece.\n'},[6]={'Making Headlines','Client: Naiko-Paneiko\n (Tarutaru Times, Windurst Waters)\nSummary:\n The editor wants you to gather\n news articles from the reporters\n dispatched to each of the four\n districts of Windurst. In addition,\n he wants you to confirm the\n validity of the scoop reported by\n the reporter in Windurst Woods.\n'},[7]={'Scooped!','Client: Naiko-Paneiko\n (Tarutaru Times, Windurst Waters)\nSummary:\n The latest edition of the "Magic\n Paradise Weekly," which features\n the exclusive report on "Where the\n Cat Burglar Hides her Kitty," has \n been stolen. The editor asks that\n you help retrieve it.\n'},[8]={'Glyph Hanger','Client: Hariga-Origa\n (Optistery, Windurst Waters)\nSummary:\n While transcribing an ancient\n manuscript, Hariga-Origa chanced\n upon a glyph that he cannot read.\n He wants you to track down Ipupu,\n a specialist in paleography, and\n hand her a note that contains the\n unknown letter.\n'},[9]={'Early Bird Catches the Bookworm','Client: Tosuka-Porika\n (Optistery, Windurst Waters)\nSummary:\n The Library of Magic wants you to\n help retrieve its overdue library\n books. In this case, a Hume by the\n name of Orn has checked out the\n book "Art for Everyone," but has\n failed to return it by the due date.\n'},[10]={'Chasing Tales','Client: Tosuka-Porika\n (Optistery, Windurst Waters)\nSummary:\n The Library of Magic wants you to\n help retrieve its overdue library\n books. In this case, Hae Jakkya, the\n Mithra who runs the auction house\n in Windurst Woods, has checked out\n the book "A Song of Love," but has\n failed to return it by the due date.\n'},[11]={'A Smudge on One\'s Record','Client: Hariga-Origa\n (Optistery, Windurst Waters)\nSummary:\n While transcribing an ancient\n manuscript, Hariga-Origa finds a\n smudge that makes the writing\n unreadable. He wants you to help\n find an item that will clear the\n nasty blot away.\n'},[12]={'Food for Thought','Client: Kerutoto\n (Rhinostery, Windurst Waters)\nSummary:\n You\'ve been asked to buy food for\n the two busy researchers and one\n freshly-awoken meditator.\n You\'ll have to ask each of them\n what they want...if you can\n understand them, that is.\n'},[13]={'Overnight Delivery','Client: Kenapa-Keppa\n (Rhinostery, Windurst Waters)\nSummary:\n You couldn\'t quite make out what\n Kenapa-Keppa was trying to say,\n but you guess he wants you to\n go pick up something from Mhaura.\n This doesn\'t look like your ordinary\n delivery job...?\n'},[14]={'Water Way to Go!','Client: Ohbiru-Dohbiru\n (Rhinostery, Windurst Waters)\nSummary:\n Ohbiru-Dohbiru is running out of\n the Giddeus water needed to raise\n Fluoro-flora. He wants you to take\n a Rhinostery canteen to the springs\n at the back of Giddeus in order to\n refill his supply.\n'},[15]={'Blue Ribbon Blues','Client: Kerutoto\n (Rhinostery, Windurst Waters)\nSummary:\n The purple ribbon you received from\n the goods shop in Windurst Woods\n seems to have a spooky curse on it.\n Kerutoto suggests you search out\n the final resting place of its\n original owner in order to return it.\n'},[16]={'Toraimarai Turmoil','Client: Ohbiru-Dohbiru\n (Rhinostery, Windurst Waters)\nSummary:\n Become a certified Rhinostery\n adventurer in order to enter the\n Toraimarai Canal and cull the\n Starmites that are causing havoc\n there. Bring back the shells of\n three Starmites to receive your\n reward.\n'},[17]={'Teacher\'s Pet','Client: Moreno-Toeno\n (Aurastery, Windurst Waters)\nSummary:\n Moreno-Toeno would like you to\n collect one bird feather and one\n two-leaf mandragora bud to be\n used as teaching materials in the\n next magic experiment at the\n School of Magic.\n'},[18]={'Reap What You Sow','Client: Mashuu-Ajuu\n (Aurastery, Windurst Waters)\nSummary:\n Mashuu-Ajuu wants help with his\n horticultural homework assignment.\n He asks that you use "Herb Seeds"\n to grow something that will impress\n his classmates, such as a "Sobbing\n Fungus."\n'},[19]={'Let Sleeping Dogs Lie','Client: Paku-Nakku\n (Aurastery, Windurst Waters)\nSummary:\n Paku-Nakku keeps falling asleep in\n class. It seems as though something\n happened during the class excursion\n to the Orastery. Find out the cause\n of his sleepiness and wake him up,\n before he fails the grade.\n'},[20]={'Making the Grade','Client: Fuepepe\n (Aurastery, Windurst Waters)\nSummary:\n The students\' answer sheets from\n their recent written exam have\n been stolen. The School of Magic\n urgently requests that you track\n down the answer sheets and return\n them.\n'},[21]={'A Crisis in the Making','Client: Ranpi-Monpi\n (Culinarians\' Guild, Windurst Waters)\nSummary:\n When preparing the food offering as\n a sign of Windurst\'s friendship with\n Giddeus, Ranpi-Monpi accidentally\n mixed in a liquid that the Yagudo\n hate. Quickly recover the tainted\n offering from the altar at Giddeus\n before ruffling some Yagudo feathers.\n'},[22]={'Hoist the Jelly, Roger','Client: Maysoon\n (Culinarians\' Guild, Windurst Waters)\nSummary:\n Maysoon says she\'ll give you one\n of her super soup pots if you\n bring her some royal jelly.\n'},[23]={'Wondering Minstrel','Client: Jatan-Paratan\n (Timbre Timbers, Windurst Waters)\nSummary:\n The flutist Jatan-Paratan, who plays\n at the tavern, has lost his swing and\n now blows. It sounds as though a\n Hume bard who visited him lately is\n to blame, or maybe it\'s just a case\n of "bard luck"...?\n'},[24]={'Heaven Cent','Client: Ropunono\n (Optistery roof, Windurst Waters)\nSummary:\n The lenses of the Optistery\'s\n telescopes need replacing. It\n would help out the stargazers \n astronomically if you could\n focus on gathering the items\n they need to repair them.\n'},[25]={'The Postman Always K.O.\'s Twice','Client: Ambrosius\n (Auction House, Windurst Walls)\nSummary:\n The auction house\'s postman was\n knocked out by a monster (again).\n Ambrosius, who runs the auction\n house, wants help in recovering\n all the mail that was lost.\n'},[26]={'To Bee or Not to Bee?','Client: Raamimi\n (Rock podium, Windurst Walls)\nSummary:\n Zayhi-Bauhi, the old man who\n constantly gives public speeches\n by the bridge to Heavens Tower,\n has come down with a sore throat.\n Follow Raamimi\'s advice on how to\n soothe this little pain in the neck.\n'},[27]={'Curses, Foiled Again!','Client: Shantotto\n (Manor, Windurst Walls)\nSummary: \n Shantotto is being bothered by an\n unseen Peeping Tom.\n To get her revenge, she wants you\n to gather her two bone chips and\n some bomb ash.\n'},[28]={'Curses, Foiled...Again!?','Client: Shantotto\n (Manor, Windurst Walls)\nSummary:\n The dancing spell Shantotto cast\n on her bothersome Peeping Tom\n turned out to be a deadly curse.\n To remove the curse, she\'ll need a\n revival tree root, two bomb arms, \n and some hair from the victim.\n Hurry, before it\'s too late!\n'},[29]={'Curses, Foiled A-Golem!?','Client: Shantotto\n (Manor, Windurst Walls)\nSummary:\n Shantotto wants you to go ask the\n Rhinostery\'s Rukususu about how\n her new magic is performing.\n Rukususu\'s party is said to be at\n the tower ruins on the Beaucedine\n Glacier.\n'},[30]={'Mandragora-Mad','Client: Yoran-Oran\n (Manor, Windurst Walls)\nSummary:\n Yoran-Oran wants you to bring him\n unusual items that mandragoras\n drop, to help in his research on\n the derivations of the species.\n'},[31]={'Star Struck','Client: Koru-Moru\n (Manor, Windurst Walls)\nSummary:\n Koru-Moru wants you to find him\n a rough black stone, for some\n spaced-out reason.\n'},[32]={'Blast from the Past','Client: Koru-Moru\n (Manor, Windurst Walls)\nSummary:\n Koru-Moru now wants you to bring\n him a mysterious item called a\n "Burnite Shell"...whatever that is.\n'},[33]={'Nothing Matters','Client: Koru-Moru\n (Manor, Windurst Walls)\nSummary:\n Professor Koru-Moru is currently\n engrossed in an experiment to\n create "something" out of "nothing."\n To get closer to the truth of\n alchemy, he wants you to track\n down an old "Thesis on Alchemy"\n for him.\n'},[34]={'Something Fishy','Client: Tokaka\n (Fishermen\'s Guild, Port Windurst)\nSummary:\n Tokaka can tell the flow patterns\n and temperature of the ocean\n currents by looking at certain fish.\n Bring her any Bastore sardines that\n you catch so she can help keep the\n fishermen informed as to where to\n drop their lines.\n'},[35]={'To Catch a Falling Star','Client: Sigismund\n (Orastery Roof, Port Windurst)\nSummary:\n Sigismund wants you to bring him\n a "Starfall Tear" so he can take it\n back to his country as a souvenir\n of Windurst.\n'},[36]={'All at Sea','Client: Paytah\n (By the harbor, Port Windurst)\nSummary:\n The wind blew away the sailor\'s cap\n that Paytah was minding for his\n father. You fished it out of the sea,\n but now it is torn and tattered.\n If you could only find someone who\n can repair Paytah\'s father\'s cap...\n'},[37]={'Truth, Justice, and the Onion Way!','Client: Kohlo-Lakolo\n (Warehouses, Port Windurst)\nSummary:\n If you want to join the Star Onion\n Brigade, you had better bring\n Kohlo-Lakolo some kind of "tail."\n'},[38]={'Know One\'s Onions','Client: Kohlo-Lakolo\n (Warehouses, Port Windurst)\nSummary:\n There are reports that the Cat\n Burglar has been loitering around\n the Ghosty House in Windurst Walls.\n This looks like a job for the Star\n Onion Brigade! Gather four wild\n onions so Kohlo-Lakolo and his gang\n can create the perfect cat trap!\n'},[39]={'Inspector\'s Gadget!','Client: Kohlo-Lakolo\n (Warehouses, Port Windurst)\nSummary:\n The Mana Orb the Star Onion Brigade\n "confiscated" from the Cat Burglar\n has gone missing. In order to track\n down the culprit, the gang will need\n the seven gadgets found in the\n Junior Investigator\'s Toolkit!\n Pichichi will tell you what to bring.\n'},[40]={'Onion Rings','Client: Kohlo-Lakolo\n (Warehouses, Port Windurst)\nSummary:\n Now that the Star Onion Brigade\n has the old Optistery ring, they can\n unlock the door to the spooky old\n abandoned Ghosty House. Yikes!\n Once inside, will they be able to\n uncover the Cat Burglar\'s plot and\n foil her evil scheme? Go, go, Onions!\n'},[41]={'Crying Over Onions','Client: Kohlo-Lakolo\n (Warehouses, Port Windurst)\nSummary:\n Honoi-Gomoi, a merchant who lives\n in Windurst Waters, has ordered the\n Star Onion Brigade to return the\n Mana Orb to him. Help the gang out\n of this fix before they\'re framed as\n a bunch of thieves!\n'},[42]={'Wild Card','Client: Honoi-Gomoi\n (Merchant\'s house, Windurst Waters)\nSummary:\n You have been asked to take apart \n the Joker Cardian and steal its\n Mana Orb. But...\n Where, o where has the Joker gone?\n O where, o where can he be?\n'},[43]={'The Promise','Client: Kohlo-Lakolo\n (Warehouses, Port Windurst)\nSummary:\n To help the Joker Cardian escape\n far away from Windurst, the Star\n Onion Brigade wants you to have\n Pichichi\'s mother, Chamama, make\n him an "Invisible Man Sticker."\n'},[44]={'Making Amends','Client: Hakkuru-Rinkuru\n (Orastery, Port Windurst)\nSummary:\n Hakkuru-Rinkuru has snapped\n Minister Ajido-Marujido\'s favorite\n wand in two!\n He wants you to find some "animal\n glue" so he can temporarily stick\n the wand together until he can\n obtain a replacement.\n'},[45]={'Making Amens!','Client: Kuroido-Moido\n (Orastery, Port Windurst)\nSummary:\n Hakkuru-Rinkuru\'s switching of Ajido-\n Marujido\'s broken wand has been\n discovered. It seems that the original\n wand had some special significance\n to the minister. Hurry and retrieve\n the original wand from the furnace in\n Garlaige Citadel before it\'s too late!\n'},[46]={'Wonder Wands','Client: Hakkuru-Rinkuru\n (Orastery, Port Windurst)\nSummary:\nThe black, white, and red mage\nbrigades of the War Warlocks are\narguing over how the Orastery\'s\nbudget should be spent. The captains\nof the three brigades each want you\nto obtain a sample of the wands they\nwant so they can decide which to buy.\n'},[47]={'Catch It If You Can!','Client: Ohruru\n (Orastery, Port Windurst)\nSummary:\n If you ever receive a rare or\n remarkable status ailment,\n rush to show it to Ohruru.\n'},[48]={'Creepy Crawlies','Client: Illu Bohjaa\n (Dhalmel Farm, Windurst Woods)\nSummary:\n The dhalmel farmer wants you to\n cull the crawler pests that eat up\n all the dhalmel food. Bring her three\n silk threads or three crawler calculi\n as proof of your efforts in order to\n gain a reward.\n'},[49]={'Paying Lip Service','Client: Tapoh Lihzeh\n (Apothecary, Windurst Woods)\nSummary:\n The apothecary has requested your\n assistance in gathering ingredients\n for her most popular preparation.\n She\'ll pay you for bringing her three\n beehive chips or two Remi shells.\n'},[50]={'The Amazin\' Scorpio','Client: Soni-Muni\n (Bomingo Round, Windurst Woods)\nSummary:\n Soni-Muni wants something that will\n rekindle the passion for adventure\n in his mate Gottah. Something to do\n with the legend of the great grappler\n Scorpio might do the trick.\n'},[51]={'Twinstone Bonding','Client: Gioh Ajihri\n (Mithra Groves, Windurst Woods)\nSummary:\n Twenty years ago, there was a great\n battle between the Mithra and the\n Yagudo in the Meriphataud Mountains.\n Gioh wants you to collect the\n twinstone earrings that belonged to\n the Mithra warriors who fell there.\n'},[52]={'Chocobilious','Client: Kuoh Rhel\n (Chocobo Stables, Windurst Woods)\nSummary:\n One of the chocobos in the stables\n has taken ill. Kuoh Rhel has asked\n the Mithran apothecary to make her\n "secret cure-all medicament" for the\n sick bird, but when you go to pick\n it up, the apothecary says she is\n lacking one of the ingredients...\n'},[53]={'In a Stew','Client: Kuoh Rhel\n (Chocobo Stables, Windurst Woods)\nSummary:\n Kuoh tried to feed the sick Chocobo\n some "secret cure-all medicament,"\n but it wouldn\'t swallow it. She wants\n to try and hide the taste by mixing\n it in some of the bird\'s favorite\n food, if you can help obtain some...\n'},[54]={'Mihgo\'s Amigo','Client: Nanaa Mihgo\n (Cat Burglar\'s lair, Windurst Woods)\nSummary:\n If you want to befriend the infamous\n Cat Burglar, then you\'ll have to give\n her something she likes.\n'},[55]={'Rock Racketeer','Client: Nanaa Mihgo\n (Cat Burglar\'s lair, Windurst Woods)\nSummary:\n The Cat Burglar wants you to see if\n a sharp gray rock she "found" is of\n any value, by having it valued at\n the Goldsmiths\' Guild in Bastok.\n If the rock is of any value, she\n wants you to sell it for her.\n'},[56]={'The All-New C-2000','Client: Kopuro-Popuro\n (Manustery, Windurst Woods)\nSummary:\n You have been talked into aiding\n the training of a new type of\n Cardian. Bring a rabbit hide, a two-\n leaf mandragora bud, and an insect\n wing, so the Cardian can learn the\n odors of monsters he may encounter.\n'},[57]={'A Greeting Cardian','Client: Kororo\n (Manustery, Windurst Woods)\nSummary:\n The Spare Cardian you jokingly\n taught a silly salutation to has\n grown up...and is unable to forget\n that greeting. Now that he\'s a full-\n grown Cardian, you better find him\n and undo what you taught him...\n otherwise, he\'ll remain a walking joke.\n'},[58]={'Legendary Plan B','Client: Kopuro-Popuro\n (Manustery, Windurst Woods)\nSummary:\n In order to pull itself out of debt,\n the Manustery has decided to carry\n out "Legendary Plan B." They want\n you to gather a revival tree root,\n a wolf hide, and a luminicloth, that\n nocturnal monsters drop, so they\n can make charms to sell to trekkers.\n'},[59]={'The All-New C-3000','Client: Kopuro-Popuro\n (Manustery, Windurst Woods)\nSummary:\n Kopuro-Popuro has created a new type\n of Cardian that has been instructed\n to return from patrols with the\n spoils of battle. To teach the\n Cardian what it should bring back,\n you have been asked to find a beetle\n shell and a hecteyes eye.\n'},[60]={'Can Cardians Cry?','Client: Apururu\n (Manustery, Windurst Woods)\nSummary:\n Apururu beseeches that you find the\n Queen of Diamonds Cardian, who was\n sent on an expedition to faraway\n lands. Seeing that the Cardian could\n not make it back on her own, it\'s\n likely that she\'s literally gone\n to pieces somewhere.\n'},[61]={'The Fanged One','Client: Perih Vashai\n (Vashai\'s residence, Windurst Woods)\nSummary:\n In order to become a truly great\n hunter, one must be accepted by\n mother nature. In order for that to\n happen, one must gain the fang of a\n tiger, the fanged king. But it does\n not sound like any old fang will do...\n'},[62]={'Flower Child','Client: Ojha Rhawash\n (Residential Area, Windurst Walls)\nSummary:\n The little Mithra cub seems to want\n a certain flower.\n Help the budding flower girl achieve\n the bloom of her youth.\n Perhaps with something purple?'},[63]={'The Three Magi','Client: Chumimi\n (Star tree farm, Heavens Tower)\nSummary:\n The star tree saplings at the farm in\n the basement of Heavens Tower aren\'t\n growing very well. Doctor Shantotto\n and co. have ordered an investigation\n to try and solve the problem. Help\n them by bringing back a glowstone\n from the crevasse of Xarcabard.\n'},[64]={'Recollections','Client: Chumimi\n (Star tree farm, Heavens Tower)\nSummary:\n Some strange occurrence from twenty\n years ago is now casting a shadow on\n the growth of the star tree saplings.\n Two of the ex-ministers may have an\n idea of the cause. After receiving\n instructions from them, head to\n Jeuno and then on to the Northlands.\n'},[65]={'The Root of the Problem','Client: Chumimi\n (Star tree farm, Heavens Tower)\nSummary:\n The cause of the star trees\' poor\n growth seems to lie in the Toraimarai\n Canal. First, bring some silk cloth\n to Professor Koru-Moru so he can\n improve his magic doll. Then take\n the magic doll into the Toraimarai\n Canal to carry out an inspection.\n'},[66]={'The Tenshodo Showdown','Client: Nanaa Mihgo\n (Cat Burglar\'s lair, Windurst Woods)\nSummary:\n The Tenshodo is gathering expert\n thieves to its fold.\n Carry out your orders by handing\n the Tenshodo envelopes to the\n appropriate people and having\n them sign the documents within.\n'},[67]={'As Thick as Thieves','Client: Nanaa Mihgo\n (Cat Burglar\'s lair, Windurst Woods)\nSummary:\n Follow the "gang whereabouts note"\n to find the two remaining members\n of Atarefaunet\'s band of thieves.\n Hand each one of them a "counter-\n feit envelope" and have them sign\n the forged documents inside.\n'},[68]={'Hitting the Marquisate','Client: Nanaa Mihgo\n (Cat Burglar\'s lair, Windurst Woods)\nSummary:\n Visit two of the eight active\n thieves gathered by the Tenshodo,\n and confirm the signatures of the\n people who originally wrote the\n documents in the "letter from\n the Tenshodo."\n'},[69]={'Sin Hunting','Client: Perih Vashai\n (Vashai\'s residence, Windurst Woods)\nSummary:\n Track down Semih Lafihna, who has\n gone to check out matters at the\n Ranguemont Pass, and hand her a\n twinstone earring.\n'},[70]={'Fire and Brimstone','Client: Perih Vashai\n (Vashai\'s residence, Windurst Woods)\nSummary:\n Go to Mhaura and meet Koh\n Lenbalalako.\n It is said that she knows the\n whereabouts of the sinner\'s\n daughter.\n'},[71]={'Unbridled Passion','Client: Perih Vashai\n (Vashai\'s residence, Windurst Woods)\nSummary:\n Semih Lafihna has set out to find\n the truth. Track her down and help\n her in any way possible.\n'},[72]={'I Can Hear a Rainbow','Client: ???\n (House of the Hero, Windurst Walls)\nSummary:\n A strange voice from within\n Carbuncle\'s Ruby is asking you to\n gather the seven colors of light...\n'},[73]={'The Puppet Master','Client: Carbuncle\n (House of the Hero, Windurst Walls)\nSummary:\n According to the words of\n Carbuncle, the thief that is\n stealing the avatars\' energy\n from adventurers is currently in\n Bastok.\n You must travel to Bastok\n to confront the situation.\n'},[74]={'Class Reunion','Client: Carbuncle\n (House of the Hero, Windurst Walls)\nSummary:\n Using the gemstone you received\n from Carbuncle, you must jog the\n memory of Professor Koru-Moru\n and get his help in reuniting the\n advanced class from several\n generations back.\n'},[75]={'Carbuncle Debacle','Client: Carbuncle\n (House of the Hero, Windurst Walls)\nSummary:\n Carbuncle needs your help. The\n Mana Orb held by the energy\n thief has grown so powerful it\n is threatening to enslave all\n the Carbuncles in the world.\n You must act now to save\n them!\n'},[76]={'+The Moonlit Path','Client: Leepe-Hoppe\n (Rhinostery, Windurst Waters)\nSummary:\n Leepe-Hoppe wants you to take on\n Carbuncle\'s request to gather the\n six "whispers," then pay a visit to\n the Full Moon Fountain...\n'},[77]={'From Saplings Grow','Client: Perih Vashai\n (Vashai\'s residence, Windurst Woods)\nSummary:\n You are to undertake training to still\n the doubt within you. Use the bow you\n have been given until it no longer\n responds to your inner turmoil.\n'},[78]={'Orastery Woes','Client: Kuroido-Moido\n (Orastery, Port Windurst)\nSummary:\n The Operations Division of the\n Orastery has asked you to assist\n them in their plan to deliver the\n ministry from misery. Use the\n magical club that you have\n been given to record combat\n information for the Orastery.\n'},[79]={'Blood and Glory','Client: Shantotto\n (Manor, Windurst Walls)\nSummary:\n Doctor Shantotto has recruited you\n into her staff-wielding team for the\n coming contest. Practice your skills\n with the staff you have been given\n until you\'ve reduced it to splinters.\n What lies ahead? Glory and honor?\n Or blood and broken bones...?\n'},[80]={'Tuning In','Client: Leepe-Hoppe\n (Rhinostery, Windurst Waters)\nSummary:\n A Mithran Tracker has demanded the\n construction of a new type of tuning\n fork so she can converse with the\n sleeping gods.\n Help Leepe-Hoppe gather the\n necessary materials.'},[81]={'Tuning Out','Client: Leepe-Hoppe\n (Rhinostery, Windurst Waters)\nSummary:\n The Mithran Tracker has taken the\n new tuning fork and left for a fabled\n protocrystal said to exist in the\n Northlands. She has failed to return.\n Assist Ildy-Goldy in gathering\n information about the tracker\'s\n whereabouts.'},[82]={'One Good Deed?','Client: Chipmy-Popmy\n (Fishermen\'s Guild, Port Windurst)\nSummary:\n A mysterious character living on\n Purgonorgo Isle in Bibiki Bay insists\n that the island belongs to him.\n Chipmy-Popmy wants you to\n participate in the next "debate" over\n ownership, set to take place in the\n center of the island.'},[83]={'Windurst Quest #22','Client:\n　'},[84]={'Windurst Quest #54','Client:\n　'},[85]={'Windurst Quest #55','Client:\n　'},[86]={'Windurst Quest #56','Client:\n　'},[87]={'Windurst Quest #57','Client:\n　'},[88]={'Windurst Quest #58','Client:\n　'},[89]={'Windurst Quest #59','Client:\n　'},[90]={'+Eco-Warrior','Client: Lumomo (Timbre Timbers Tavern,\n Windurst Waters)\nSummary:\n Lumomo wants you to exterminate an\n ecological threat, in the Maze of \n Shakhrami, according to Ahko\n Mhalijikhari\'s instructions, and bring\n her evidence of the feat.'},[91]={'+Escort for Hire (Windurst)','Client: Dehn Harzhapan\n (Warehouses, Port Windurst)\nSummary:\n You are to escort Wanzo-Unzozo to\n his desired destination within the\n Garlaige Citadel.'},[92]={'+A Discerning Eye (Windurst)','Client: Pygmalion (Airship Dock,\n Port Windurst)\nSummary:\n You have been asked to return a\n dropped item to its rightful owner.\n The passenger should be on the next\n airship flight.'},[93]={'+Waking Dreams','Client: Kerutoto\n (Rhinostery, Windurst Waters)\nSummary:\n Diabolos has informed Kerutoto\n that he is waiting for you at\n the Shrouded Maw in Pso\'Xja,\n buried deep in the northern lands.\n You must respond to his\n summons so that Kerutoto\n can meditate free of trouble.'},[94]={'Lure of the Wildcat (Windurst)','Client: Ibwam (Bomingo Round,\n Windurst Woods)\nSummary:\n The mercenary company\n "Salaheem\'s Sentinels" has asked\n you to help recruit new members.'},[95]={'Babban Ny Mheillea','Client: Khoto Rokkorah\n (Huntsman\'s Court, Windurst Waters)\nSummary:\n Khoto Rokkorah is bemused by the\n plot of a story written in the time\n of the Great War. The tale begins\n to twist when a new companion\n joins Babban in the Rolanberry\n Fields...'},[96]={'Trust: Windurst','Client: Wetata\n (Bomingo Round, Windurst Woods)\nSummary:\n Wetata of the Jeuno Institute of\n Magical Studies has introduced you to\n the Trust initiative and asked you to\n visit Kupipi in Heavens Tower.'},[97]={'Windurst Quest #97','Client:\n　'},[98]={'Windurst Quest #99','Client:\n　'},[99]={'Windurst Quest #99','Client:\n　'}},
  jn={name='Jeuno',[0]={'Crest of Davoi','Client: Baudin (House, Upper Jeuno)\nSummary:\n Baudin asks for a piece of coeurl\n meat. He offers a crest of Davoi in\n return.'},[1]={'Save My Sister','Client: Baudin (House, Upper Jeuno)\nSummary:\n Help rid Baudin\'s sister of the\n demon that has possessed her.'},[2]={'A Clock Most Delicate','Client: Galmut (House, Upper Jeuno)\nSummary:\n Galmut is running out of oil for\n the clock tower. The Tenshodo\n might have some in stock.'},[3]={'Save the Clock Tower','Client: Derrick (Chamber of Commerce\n and Industry, Lower Jeuno)\nSummary:\n The famous clock tower of Jeuno is\n scheduled for demolition. Gather\n enough signatures to save it.'},[4]={'Chocobo\'s Wounds','Client: Brutus (Chocobo Stables,\n Upper Jeuno)\nSummary:\n Help nurse the chocobo back to\n health. It seems to have suffered\n both mentally and physically.\n Gausebit wildgrass may do the trick.'},[5]={'Save My Son','Client: Dietmund (Merchant\'s House,\n Lower Jeuno)\nSummary:\n To cure Dietmund\'s son of his\n affliction, go to Qufim Island. Once\n there, find the flower that only\n blooms at night, and bring back its\n roots.'},[6]={'A Candlelight Vigil','Client: Ilumida (House, Upper Jeuno)\nSummary:\n Ilumida wants to light a candle\n in memory of her husband. Bring\n her one from the Temple of the\n Goddess.'},[7]={'The Wonder Magic Set','Client: Panta-Putta (Merchant\'s\n House, Lower Jeuno)\nSummary:\n You are to bring Panta the popular\n Wonder Magic Set. Don\'t say a word\n to his family, or else.'},[8]={'The Kind Cardian','Client: Panta-Putta (Infirmary\n Monberaux, Upper Jeuno)\nSummary:\n Panta wants you to take the Two\n of Swords to the Manustery in\n Windurst to restore the Cardian\'s\n magical power.'},[9]={'Your Crystal Ball','Client: Kurou-Morou (Fortunetellers,\n Lower Jeuno)\nSummary:\n Create your own crystal ball to\n have your fortune told.'},[10]={'Collect Tarut Cards','Client: Chululu (Fortunetellers,\n Lower Jeuno)\nSummary:\n You must gather one of each kind\n of Tarut card--the Hermit, the King,\n Death, and the Fool--before your\n fortune can be told. Trade with your\n fellow adventurers to collect the\n full set.'},[11]={'+All in the Cards','Client: Chululu (Fortunetellers,\n Lower Jeuno)\nSummary:\n Collect the complete set of Tarut\n cards by trading with your fellow\n adventurers, that you might help\n spread the joy and wisdom of\n fortune-telling across the realm.'},[12]={'The Old Monument','Client: Lewenhart (Song Runes,\n Buburimu Peninsula)\nSummary:\n Copy the lyrics from the ancient\n monument to a sheet of parchment.'},[13]={'A Minstrel in Despair','Client: Mertaire (Merry Minstrel\n Meadhouse, Lower Jeuno)\nSummary:\n Show the desperate bard Mertaire\n the words to the song.'},[14]={'Rubbish Day','Client: Chululu (Fortunetellers,\n Lower Jeuno)\nSummary:\n Chululu needs you to dispose of\n what she forgot to put out on\n rubbish day.'},[15]={'Never to Return','Client: Kurou-Morou (Fortunetellers,\n Lower Jeuno)\nSummary:\n Kurou-Morou has thrown his\n precious hairpin into the rubbish,\n so he needs a new one made.'},[16]={'Community Service','Client: Zauko (Lower Jeuno)\nSummary:\n Zauko needs someone to help light\n the streetlamps.'},[17]={'Cook\'s Pride','Client: Naruru (Merchant\'s House,\n Lower Jeuno)\nSummary:\n Naruru can\'t find her favorite\n cooking pot. Get her a new one\n from the Windurst Culinarians\' Guild.'},[18]={'Tenshodo Membership','Client: Ghebi Damomohe (Neptune\'s\n Spire, Lower Jeuno)\nSummary:\n To join the Tenshodo, you need either\n a membership form or an invitation\n from a current member.'},[19]={'The Lost Cardian','Client: Panta-Putta (Merchant\'s\n House, Lower Jeuno)\nSummary:\n The Two of Swords has gone\n missing. Nobody knows where he\n has gone off to.'},[20]={'Path of the Beastmaster','Client: Brutus (Chocobo Stables,\n Upper Jeuno)\nSummary:\n You have taken your first step.\n The path of the beastmaster lies\n before you.'},[21]={'Path of the Bard','Client: Lewenhart (Song Runes,\n Valkurm Dunes)\nSummary:\n You have taken your first step.\n The path of the bard lies before\n you.'},[22]={'The Clockmaster','Client: Galmut (House, Upper Jeuno)\nSummary:\n Help the dejected Galmut by saving\n his clock tower.'},[23]={'Candle-making','Client: Rouliette (Temple of the\n Goddess, Upper Jeuno)\nSummary:\n Bring a lanolin cube to Rouliette\n so she can make you a candle.'},[24]={'Child\'s Play','Client: Karl (Port Jeuno)\nSummary:\n Karl will trade you a Wonder\n Magic Set for a white rock.'},[25]={'Northward','Client: Radeivepart (Peace\n Monument, Ru\'Lude Gardens)\nSummary:\n Prove you are worthy to receive\n the map of Castle Zvahl by bringing\n a flame degen back to Radeivepart.'},[26]={'The Antique Collector','Client: Imasuke (Gate to Qufim,\n Port Jeuno)\nSummary:\n Present Imasuke with a kaiser\n sword to receive a map of\n Delkfutt\'s Tower.'},[27]={'Deal with Tenshodo','Client: Garnev (Tenshodo,\n Lower Jeuno)\nSummary:\n Garnev will trade you some clock\n tower oil for a gold Orcmask.'},[28]={'The Gobbiebag Part I','Client: Bluffnix (Muckvix\'s\n Junk Shop, Lower Jeuno)\nSummary:\n Bluffnix promises to enlarge your\n pack if you bring him the following:\n some dhalmel leather, a steel\n ingot, a square of linen cloth,\n and a peridot.'},[29]={'The Gobbiebag Part II','Client: Bluffnix (Muckvix\'s\n Junk Shop, Lower Jeuno)\nSummary:\n Bluffnix promises to enlarge your\n pack further if you bring him the\n following items: some ram leather,\n a mythril ingot, a square of wool\n cloth, and a turquoise.'},[30]={'The Gobbiebag Part III','Client: Bluffnix (Muckvix\'s\n Junk Shop, Lower Jeuno)\nSummary:\n Bluffnix promises to enlarge your\n pack even more if you bring him\n the following: some tiger leather,\n a gold ingot, a square of velvet\n cloth, and a painite.'},[31]={'The Gobbiebag Part IV','Client: Bluffnix (Muckvix\'s\n Junk Shop, Lower Jeuno)\nSummary:\n Bluffnix will make your pack as big\n as a gobbiebag if you bring him the\n following: a cermet chunk, a\n darksteel ingot, a square of silk\n cloth, and a goshenite.'},[32]={'The Gobbiebag Part V','Client: Bluffnix (Muckvix\'s\n Junk Shop, Lower Jeuno)\nSummary:\n Bluffnix will make your pack bigger\n than a gobbiebag if you bring him\n the following: a square of bugard\n leather, a paktong ingot, a square\n of Moblinweave, and a rhodonite.'},[33]={'The Gobbiebag Part VI','Client: Bluffnix (Muckvix\'s\n Junk Shop, Lower Jeuno)\nSummary:\n Bluffnix will make your pack even\n bigger if you bring him the\n following: a square of balloon\n cloth, a shakudo ingot, a high\n quality eft skin, and an iolite.'},[34]={'The Gobbiebag Part VII','Client: Bluffnix (Muckvix\'s\n Junk Shop, Lower Jeuno)\nSummary:\n Bluffnix will make your pack even\n bigger if you bring him the\n following: a square of lynx\n leather, an adaman ingot, a\n square of rainbow cloth, and\n a deathstone.'},[35]={'The Gobbiebag Part VIII','Client: Bluffnix (Muckvix\'s\n Junk Shop, Lower Jeuno)\nSummary:\n Bluffnix will make your pack even\n bigger if you bring him the\n following: a square of smilodon\n leather, an electrum ingot, a \n square of cilice, and an angelstone.'},[36]={'The Gobbiebag Part IX','Client: Bluffnix (Muckvix\'s\n Junk Shop, Lower Jeuno)\nSummary:\n Bluffnix will make your pack even\n bigger if you bring him the\n following: an orichalcum ingot, a\n square of peiste leather, a square\n of oil-soaked cloth, and an\n oxblood orb.'},[37]={'The Gobbiebag Part X','Client: Bluffnix (Muckvix\'s\n Junk Shop, Lower Jeuno)\nSummary:\n Bluffnix will make your pack even\n bigger if you bring him the\n following: a molybdenum ingot, a\n square of griffon leather, a square of\n foulard, and an angel skin orb.'},[38]={'Mysteries of Beadeaux I','Client: Sattal-Mansal (Tenshodo,\n Lower Jeuno)\nSummary:\n Bring back a Quadav charm and\n Sattal-Mansal will trade a\n coruscant rosary for it. Only\n then can you enter the depths of\n Beadeaux.'},[39]={'Mysteries of Beadeaux II','Client: Sattal-Mansal (Tenshodo,\n Lower Jeuno)\nSummary:\n Bring back a Quadav augury shell\n and Sattal-Mansal will trade a\n black matinee necklace for it.\n Only then can you enter the\n depths of Beadeaux.'},[40]={'Mystery of Fire','Client: Llamrei (Dining Hall,\n Ru\'Lude Gardens)\nSummary:\n Llamrei will award you with a key\n the archduke discovered if you\n bring the required items.'},[41]={'Mystery of Water','Client: Llamrei (Dining Hall,\n Ru\'Lude Gardens)\nSummary:\n Llamrei will award you with a key\n the archduke discovered if you\n bring the required items.'},[42]={'Mystery of Earth','Client: Llamrei (Dining Hall,\n Ru\'Lude Gardens)\nSummary:\n Llamrei will award you with a key\n the archduke discovered if you\n bring the required items.'},[43]={'Mystery of Wind','Client: Llamrei (Dining Hall,\n Ru\'Lude Gardens)\nSummary:\n Llamrei will award you with a key\n the archduke discovered if you\n bring the required items.'},[44]={'Mystery of Ice','Client: Llamrei (Dining Hall,\n Ru\'Lude Gardens)\nSummary:\n Llamrei will award you with a key\n the archduke discovered if you\n bring the required items.'},[45]={'Mystery of Lightning','Client: Llamrei (Dining Hall,\n Ru\'Lude Gardens)\nSummary:\n Llamrei will award you with a key\n the archduke discovered if you\n bring the required items.'},[46]={'Mystery of Light','Client: Llamrei (Dining Hall,\n Ru\'Lude Gardens)\nSummary:\n Llamrei will award you with a key\n the archduke discovered if you\n bring the required items.'},[47]={'Mystery of Darkness','Client: Llamrei (Dining Hall,\n Ru\'Lude Gardens)\nSummary:\n Llamrei will award you with a key\n the archduke discovered if you\n bring the required items.'},[48]={'Fistful of Fury','Client: Vola (Tenshodo,\n Lower Jeuno)\nSummary:\n To receive your brown belt, find\n a nue fang, a morbolger vine, and a\n dodo skin. Only then will you be\n worthy.'},[49]={'The Goblin Tailor','Client: Guttrix (Goblins\' Goblet,\n Lower Jeuno)\nSummary:\n Each week, a different magical\n pattern appears inside a treasure\n chest somewhere. Give it to Guttrix\n and he\'ll reward you.'},[50]={'Pretty Little Things','Client: Zona Shodhun (Residential\n Gate, Port Jeuno) \nSummary:\n Zona likes pretty flowers and\n pebbles. Find some for her.\n Perhaps something yellow?'},[51]={'Borghertz\'s Warring Hands','Client: Guslam (Durable Shields,\n Upper Jeuno)\nSummary:\n Gauntlets wrought by Borghertz,\n the legendary craftsman, lie hidden\n somewhere in Vana\'diel.'},[52]={'Borghertz\'s Striking Hands','Client: Guslam (Durable Shields,\n Upper Jeuno)\nSummary:\n Gauntlets wrought by Borghertz,\n the legendary craftsman, lie hidden\n somewhere in Vana\'diel.'},[53]={'Borghertz\'s Healing Hands','Client: Guslam (Durable Shields,\n Upper Jeuno)\nSummary:\n Gauntlets wrought by Borghertz,\n the legendary craftsman, lie hidden\n somewhere in Vana\'diel.'},[54]={'Borghertz\'s Sorcerous Hands','Client: Guslam (Durable Shields,\n Upper Jeuno)\nSummary:\n Gauntlets wrought by Borghertz,\n the legendary craftsman, lie hidden\n somewhere in Vana\'diel.'},[55]={'Borghertz\'s Vermillion Hands','Client: Guslam (Durable Shields,\n Upper Jeuno)\nSummary:\n Gauntlets wrought by Borghertz,\n the legendary craftsman, lie hidden\n somewhere in Vana\'diel.'},[56]={'Borghertz\'s Sneaky Hands','Client: Guslam (Durable Shields,\n Upper Jeuno)\nSummary:\n Gauntlets wrought by Borghertz,\n the legendary craftsman, lie hidden\n somewhere in Vana\'diel.'},[57]={'Borghertz\'s Stalwart Hands','Client: Guslam (Durable Shields,\n Upper Jeuno)\nSummary:\n Gauntlets wrought by Borghertz,\n the legendary craftsman, lie hidden\n somewhere in Vana\'diel.'},[58]={'Borghertz\'s Shadowy Hands','Client: Guslam (Durable Shields,\n Upper Jeuno)\nSummary:\n Gauntlets wrought by Borghertz,\n the legendary craftsman, lie hidden\n somewhere in Vana\'diel.'},[59]={'Borghertz\'s Wild Hands','Client: Guslam (Durable Shields,\n Upper Jeuno)\nSummary:\n Gauntlets wrought by Borghertz,\n the legendary craftsman, lie hidden\n somewhere in Vana\'diel.'},[60]={'Borghertz\'s Harmonious Hands','Client: Guslam (Durable Shields,\n Upper Jeuno)\nSummary:\n Gauntlets wrought by Borghertz,\n the legendary craftsman, lie hidden\n somewhere in Vana\'diel.'},[61]={'Borghertz\'s Chasing Hands','Client: Guslam (Durable Shields,\n Upper Jeuno)\nSummary:\n Gauntlets wrought by Borghertz,\n the legendary craftsman, lie hidden\n somewhere in Vana\'diel.'},[62]={'Borghertz\'s Loyal Hands','Client: Guslam (Durable Shields,\n Upper Jeuno)\nSummary:\n Gauntlets wrought by Borghertz,\n the legendary craftsman, lie hidden\n somewhere in Vana\'diel.'},[63]={'Borghertz\'s Lurking Hands','Client: Guslam (Durable Shields,\n Upper Jeuno)\nSummary:\n Gauntlets wrought by Borghertz,\n the legendary craftsman, lie hidden\n somewhere in Vana\'diel.'},[64]={'Borghertz\'s Dragon Hands','Client: Guslam (Durable Shields,\n Upper Jeuno)\nSummary:\n Gauntlets wrought by Borghertz,\n the legendary craftsman, lie hidden\n somewhere in Vana\'diel.'},[65]={'Borghertz\'s Calling Hands','Client: Guslam (Durable Shields,\n Upper Jeuno)\nSummary:\n Gauntlets wrought by Borghertz,\n the legendary craftsman, lie hidden\n somewhere in Vana\'diel.'},[66]={'Axe the Competition','Client: Brutus (Chocobo Stables,\n Upper Jeuno)\nSummary:\n The Tenshodo wants Brutus\'s opinion\n on which axe they should carry in\n their stores. Brutus has asked you to\n test one of the axes until its blade\n has gone dull.'},[67]={'Wings of Gold','Client: Brutus (Chocobo Stables,\n Upper Jeuno)\nSummary:\n The guiding bell is hidden somewhere\n inside Delkfutt\'s Tower. Brutus\n wants you to bring it back for his\n deceased chocobo.'},[68]={'Scattered Into Shadow','Client: Brutus (Chocobo Stables,\n Upper Jeuno)\nSummary:\n Many animals conscripted during the\n war did not return. Brutus wants\n you to put their souls to rest.'},[69]={'A New Dawn','Client: Dietmund (Merchant\'s House,\n Lower Jeuno)\nSummary:\n Something is amiss in the Eldieme\n Necropolis. Observe the fiends and\n find a solution.'},[70]={'Painful Memory','Client: Mertaire (Merry Minstrel\n Meadhouse, Lower Jeuno)\nSummary:\n Take Mertaire\'s bracelet to\n Ranguemont Pass and immerse it in\n the Waters of Oblivion.'},[71]={'The Requiem','Client: Bki Tbujhja (Merry Minstrel\n Meadhouse, Lower Jeuno)\nSummary:\n A certain post is rotated at the\n meadhouse. Now, it\'s your turn.'},[72]={'The Circle of Time ','Client: Imasuke (Qufim Tunnel,\n Port Jeuno)\nSummary:\n Solve the riddle of the ring, and\n find the truth behind it.'},[73]={'Searching for the Right Words','Client: Ilumida (House, Upper Jeuno)\nSummary:\n A "moondrop" from the Boyahda Tree\n is required to open the chest\n Ilumida\'s late husband left for her.'},[74]={'Beat Around the Bushin','Client: Atori-Tutori\n (Tenshodo, Lower Jeuno)\nSummary:\n If you want information on the\n black belt, you need to first\n bring back what Atori-Tutori wants.'},[75]={'A Reputation in Ruins','Client: Migliorozz (Temple of\n the Goddess, Upper Jeuno)\nSummary:\n The Tenshodo has opened the ruins\n of Pso\'Xja to adventurers.\n Migliorozz has asked you to perform\n a task involving the gate that lies\n in the deepest part of the southwest\n tower of the ruins.'},[76]={'+Ducal Hospitality','Client: Taillegeas (Dining Hall,\n Ru\'Lude Gardens)\nSummary:\n Taillegeas has asked you to collect\n several items desired by guests of\n the duchy.'},[77]={'Hook, Line, and Sinker','Client: Omer (Market Bridge,\n Lower Jeuno)\nSummary:\n Help Omer retrieve his prized fishing\n rod that was stolen from him by an\n Elvaan girl.\n Apparently the rod was lost when she\n fished up a monster out on Qufim\n Island...'},[78]={'In the Mood for Love','Client: Odasel (Gems by Kshama,\n Lower Jeuno)\nSummary:\n Odasel wants to find out which of the\n three beauties in the gem store has\n feelings for him. According to a\n passing Elvaan girl, a jewel known as\n the "Chameleon Diamond" could help\n solve his dilemma...'},[79]={'A Chocobo\'s Tale','Client: Nevela (Artisan Bridge,\n Upper Jeuno)\nSummary:\n Nevela wants to hear the story\n surrounding the birth of a chocobo\n in the Upper Jeuno stables.\n The chocobo\'s mother is said to have\n been from the stables in Bastok...'},[80]={'Empty Memories','Client: Harith (Grand Duke Palace,\n Ru\'Lude Gardens)\nSummary:\n The mysterious "society" that\n Harith works for is supposedly\n performing research on a strange\n life form known as the Empty.'},[81]={'Unlisted Qualities','Client: Luto Mewrilah\n (Artisan Bridge, Upper Jeuno)\nSummary:\n Luto wants you to find out if the\n person you chose from her list is\n holding a certain mirror.'},[82]={'Girl in the Looking Glass','Client: Laurana (Artisan Bridge,\n Upper Jeuno)\nSummary:\n Laurana\'s daughter has gone\n missing. She is a young girl with\n blonde hair, and was wearing a\n brown dress and a brown cap.'},[83]={'Mirror, Mirror','Client: Luto Mewrilah\n (Artisan Bridge, Upper Jeuno)\nSummary:\n Luto has recently discovered that\n another mirror bearing strange\n properties exists in the world.\n It is supposedly somewhere in\n San d\'Oria and she wants you to\n go look for it.'},[84]={'Past Reflections','Client: Luto Mewrilah\n (Artisan Bridge, Upper Jeuno)\nSummary:\n Luto wants you to search the\n Optistery library in Windurst for\n a book that can help her repair\n the broken mirror.'},[85]={'Blighted Gloom','Client: Luto Mewrilah\n (Artisan Bridge, Upper Jeuno)\nSummary:\n Luto has asked you to locate a\n special metal that can be used to\n repair the broken mirror.\n According to her research, this\n substance can only be found inside\n an extremely rare species of slime.'},[86]={'Blessed Radiance','Client: Luto Mewrilah\n (Artisan Bridge, Upper Jeuno)\nSummary:\n Palometa still lies in cursed\n slumber. You must find a way\n to save her!'},[87]={'Mirror Images','Client: Luto Mewrilah\n (Artisan Bridge, Upper Jeuno)\nSummary:\n Save Palometa from her mysterious\n captor.'},[88]={'Chameleon Capers','Client: Luto Mewrilah\n (Artisan Bridge, Upper Jeuno)\nSummary:\n A friend of Luto has used a magical\n costume kit to change into a child,\n but now he can\'t return to his original\n form.\n Luto wants you to help find a way\n to change him back.'},[89]={'Regaining Trust','Client: Luto Mewrilah\n (Artisan Bridge, Upper Jeuno)\nSummary:\n Your adventuring fellow is\n in the hospital after being\n attacked by a monster in Qufim.\n You should go make sure\n your friend is not too badly hurt.'},[90]={'Storms of Fate','Client: Esha\'ntarl\n (Audience Chamber, Ru\'Lude Gardens)\nSummary:\n Bahamut returned to the heavens\n following the defeat of the Keeper\n of the Apocalypse, but recently\n he was witnessed descending upon\n Cape Riverne with an army of\n wyrms. Go to Bahamut and find out\n his intentions.'},[91]={'Mixed Signals','Client: Luto Mewrilah\n (Artisan Bridge, Upper Jeuno)\nSummary:\n Your adventuring fellow is acting\n strangely. Talk to Luto to see what\n you can find out.'},[92]={'Shadows of the Departed','Client: Esha\'ntarl\n (Audience Chamber, Ru\'Lude Gardens)\nSummary:\n Strange readings have been recorded\n from the Emptiness surrounding the\n mothercrystals.\n Travel to the crags of Holla, Dem,\n and Mea and investigate the\n coordinates where this phenomenon\n is occurring.'},[93]={'Apocalypse Nigh','Client: Esha\'ntarl\n (Audience Chamber, Ru\'Lude Gardens)\nSummary:\n The next incarnation of the Keeper\n of the Apocalypse is attempting to\n cross over into Vana\'diel. Sing the \n Lay of the Immortals before the fifth\n mothercrystal and put an end to this\n threat once and for all!'},[94]={'Lure of the Wildcat (Jeuno)','Client: Ajithaam (Artisan Bridge,\n Upper Jeuno)\nSummary:\n The mercenary company\n "Salaheem\'s Sentinels" has asked\n you to help recruit new members.'},[95]={'The Road to Aht Urhgan','Client: Faursel (Tenshodo,\n Lower Jeuno)\nSummary:\n If you want to ride the mercenary\n transport ship from Mhaura, you\n must bring the required items to\n the Tenshodo.'},[96]={'Chocobo on the Loose!','Client: Brutus (Chocobo Stables,\n Upper Jeuno)\nSummary:\n A chocobo has run away from the\n stables in Upper Jeuno, and Brutus\n wants you to help bring it back.'},[97]={'Lakeside Minuet','Client: Laila (Artisan Bridge,\n Upper Jeuno)\nSummary:\n Laila has asked that you bring her\n a stardust pebble before she\'ll\n consider allowing you to join\n Troupe Brilioth.'},[98]={'The Unfinished Waltz','Client: Laila (Artisan Bridge,\n Upper Jeuno)\nSummary:\n Troupe Brilioth is aiming for a\n dance style that will captivate\n and enchant. Work out how to take\n your dancing to the next level,\n then come back and show Laila.'},[99]={'The Road to Divadom','Client: Laila (Artisan Bridge,\n Upper Jeuno)\nSummary:\n As a child, Laila had an\n inspirational encounter with a\n piper at Lake Mechieume in Jugner\n Forest. In order to become a\n great dancer like Laila, you\n should seek a skilled musician\n to play a tune for you.'},[100]={'Comeback Queen','Client: Laila (Artisan Bridge,\n Upper Jeuno)\nSummary:\n Deliver Wyatt\'s proposal to the\n owner of the music shop in Bastok\n Markets so he can pass it on to\n Valeriano.'},[101]={'A Furious Finale','Client: Laila (Artisan Bridge,\n Upper Jeuno)\nSummary:\n Obtain a "dancer\'s testimony" and\n bring it to Laila.'},[102]={'The Miraculous Dale','Client: Rakuru-Rakoru\n (Holy Owen\'s Square, Lower Jeuno)\nSummary:\n Rakuru-Rakoru from the Orastery\n wants you to collect research\n data by defeating all the monsters\n recorded in the Data Analyzer\n and Logger EX (Dale).'},[103]={'Clash of the Comrades','Client: Luto Mewrilah\n (Artisan Bridge, Upper Jeuno)\nSummary:\n As a test of strength, you have\n agreed to meet your fellow in single\n combat at the Qu\'Bia Arena.\n Who will emerge victorious in\n this face-off between friends?'},[104]={'Unlocking a Myth (Warrior)','Client: Zalsuhm (Muckvix\'s\n Junk Shop, Lower Jeuno)\nSummary:\n Self-styled leading researcher of\n mystical artifacts, Zalsuhm, claims\n that the weapon you acquired deep\n within Nyzul Isle conceals immense\n power. Wielding the now unlocked\n weapon will cause a magical evolution\n to take place...eventually.'},[105]={'Unlocking a Myth (Monk)','Client: Zalsuhm (Muckvix\'s\n Junk Shop, Lower Jeuno)\nSummary:\n Self-styled leading researcher of\n mystical artifacts, Zalsuhm, claims\n that the weapon you acquired deep\n within Nyzul Isle conceals immense\n power. Wielding the now unlocked\n weapon will cause a magical evolution\n to take place...eventually.'},[106]={'Unlocking a Myth (White Mage)','Client: Zalsuhm (Muckvix\'s\n Junk Shop, Lower Jeuno)\nSummary:\n Self-styled leading researcher of\n mystical artifacts, Zalsuhm, claims\n that the weapon you acquired deep\n within Nyzul Isle conceals immense\n power. Wielding the now unlocked\n weapon will cause a magical evolution\n to take place...eventually.'},[107]={'Unlocking a Myth (Black Mage)','Client: Zalsuhm (Muckvix\'s\n Junk Shop, Lower Jeuno)\nSummary:\n Self-styled leading researcher of\n mystical artifacts, Zalsuhm, claims\n that the weapon you acquired deep\n within Nyzul Isle conceals immense\n power. Wielding the now unlocked\n weapon will cause a magical evolution\n to take place...eventually.'},[108]={'Unlocking a Myth (Red Mage)','Client: Zalsuhm (Muckvix\'s\n Junk Shop, Lower Jeuno)\nSummary:\n Self-styled leading researcher of\n mystical artifacts, Zalsuhm, claims\n that the weapon you acquired deep\n within Nyzul Isle conceals immense\n power. Wielding the now unlocked\n weapon will cause a magical evolution\n to take place...eventually.'},[109]={'Unlocking a Myth (Thief)','Client: Zalsuhm (Muckvix\'s\n Junk Shop, Lower Jeuno)\nSummary:\n Self-styled leading researcher of\n mystical artifacts, Zalsuhm, claims\n that the weapon you acquired deep\n within Nyzul Isle conceals immense\n power. Wielding the now unlocked\n weapon will cause a magical evolution\n to take place...eventually.'},[110]={'Unlocking a Myth (Paladin)','Client: Zalsuhm (Muckvix\'s\n Junk Shop, Lower Jeuno)\nSummary:\n Self-styled leading researcher of\n mystical artifacts, Zalsuhm, claims\n that the weapon you acquired deep\n within Nyzul Isle conceals immense\n power. Wielding the now unlocked\n weapon will cause a magical evolution\n to take place...eventually.'},[111]={'Unlocking a Myth (Dark Knight)','Client: Zalsuhm (Muckvix\'s\n Junk Shop, Lower Jeuno)\nSummary:\n Self-styled leading researcher of\n mystical artifacts, Zalsuhm, claims\n that the weapon you acquired deep\n within Nyzul Isle conceals immense\n power. Wielding the now unlocked\n weapon will cause a magical evolution\n to take place...eventually.'},[112]={'Unlocking a Myth (Beastmaster)','Client: Zalsuhm (Muckvix\'s\n Junk Shop, Lower Jeuno)\nSummary:\n Self-styled leading researcher of\n mystical artifacts, Zalsuhm, claims\n that the weapon you acquired deep\n within Nyzul Isle conceals immense\n power. Wielding the now unlocked\n weapon will cause a magical evolution\n to take place...eventually.'},[113]={'Unlocking a Myth (Bard)','Client: Zalsuhm (Muckvix\'s\n Junk Shop, Lower Jeuno)\nSummary:\n Self-styled leading researcher of\n mystical artifacts, Zalsuhm, claims\n that the weapon you acquired deep\n within Nyzul Isle conceals immense\n power. Wielding the now unlocked\n weapon will cause a magical evolution\n to take place...eventually.'},[114]={'Unlocking a Myth (Ranger)','Client: Zalsuhm (Muckvix\'s\n Junk Shop, Lower Jeuno)\nSummary:\n Self-styled leading researcher of\n mystical artifacts, Zalsuhm, claims\n that the weapon you acquired deep\n within Nyzul Isle conceals immense\n power. Wielding the now unlocked\n weapon will cause a magical evolution\n to take place...eventually.'},[115]={'Unlocking a Myth (Samurai)','Client: Zalsuhm (Muckvix\'s\n Junk Shop, Lower Jeuno)\nSummary:\n Self-styled leading researcher of\n mystical artifacts, Zalsuhm, claims\n that the weapon you acquired deep\n within Nyzul Isle conceals immense\n power. Wielding the now unlocked\n weapon will cause a magical evolution\n to take place...eventually.'},[116]={'Unlocking a Myth (Ninja)','Client: Zalsuhm (Muckvix\'s\n Junk Shop, Lower Jeuno)\nSummary:\n Self-styled leading researcher of\n mystical artifacts, Zalsuhm, claims\n that the weapon you acquired deep\n within Nyzul Isle conceals immense\n power. Wielding the now unlocked\n weapon will cause a magical evolution\n to take place...eventually.'},[117]={'Unlocking a Myth (Dragoon)','Client: Zalsuhm (Muckvix\'s\n Junk Shop, Lower Jeuno)\nSummary:\n Self-styled leading researcher of\n mystical artifacts, Zalsuhm, claims\n that the weapon you acquired deep\n within Nyzul Isle conceals immense\n power. Wielding the now unlocked\n weapon will cause a magical evolution\n to take place...eventually.'},[118]={'Unlocking a Myth (Summoner)','Client: Zalsuhm (Muckvix\'s\n Junk Shop, Lower Jeuno)\nSummary:\n Self-styled leading researcher of\n mystical artifacts, Zalsuhm, claims\n that the weapon you acquired deep\n within Nyzul Isle conceals immense\n power. Wielding the now unlocked\n weapon will cause a magical evolution\n to take place...eventually.'},[119]={'Unlocking a Myth (Blue Mage)','Client: Zalsuhm (Muckvix\'s\n Junk Shop, Lower Jeuno)\nSummary:\n Self-styled leading researcher of\n mystical artifacts, Zalsuhm, claims\n that the weapon you acquired deep\n within Nyzul Isle conceals immense\n power. Wielding the now unlocked\n weapon will cause a magical evolution\n to take place...eventually.'},[120]={'Unlocking a Myth (Corsair)','Client: Zalsuhm (Muckvix\'s\n Junk Shop, Lower Jeuno)\nSummary:\n Self-styled leading researcher of\n mystical artifacts, Zalsuhm, claims\n that the weapon you acquired deep\n within Nyzul Isle conceals immense\n power. Wielding the now unlocked\n weapon will cause a magical evolution\n to take place...eventually.'},[121]={'Unlocking a Myth (Puppetmaster)','Client: Zalsuhm (Muckvix\'s\n Junk Shop, Lower Jeuno)\nSummary:\n Self-styled leading researcher of\n mystical artifacts, Zalsuhm, claims\n that the weapon you acquired deep\n within Nyzul Isle conceals immense\n power. Wielding the now unlocked\n weapon will cause a magical evolution\n to take place...eventually.'},[122]={'Unlocking a Myth (Dancer)','Client: Zalsuhm (Muckvix\'s\n Junk Shop, Lower Jeuno)\nSummary:\n Self-styled leading researcher of\n mystical artifacts, Zalsuhm, claims\n that the weapon you acquired deep\n within Nyzul Isle conceals immense\n power. Wielding the now unlocked\n weapon will cause a magical evolution\n to take place...eventually.'},[123]={'Unlocking a Myth (Scholar)','Client: Zalsuhm (Muckvix\'s\n Junk Shop, Lower Jeuno)\nSummary:\n Self-styled leading researcher of\n mystical artifacts, Zalsuhm, claims\n that the weapon you acquired deep\n within Nyzul Isle conceals immense\n power. Wielding the now unlocked\n weapon will cause a magical evolution\n to take place...eventually.'},[124]={'JNQuest','Client: \n'},[125]={'JNQuest','Client: \n'},[126]={'JNQuest','Client: \n'},[127]={'JNQuest','Client: \n'},[128]={'In Defiant Challenge','Client: Maat (Grand Duke Palace,\n Ru\'Lude Gardens)\nSummary:\n Apparently, your innate limits can\n be breached by acquiring the\n necessary items.'},[129]={'Atop the Highest Mountains','Client: Maat (Grand Duke Palace,\n Ru\'Lude Gardens)\nSummary:\n Collect three stones of frigicite\n from fiend-infested caverns in the\n north. Bring them to Maat to further\n expand your innate limits.'},[130]={'Whence Blows the Wind','Client: Maat (Grand Duke Palace,\n Ru\'Lude Gardens)\nSummary:\n Your innate limits can be pushed\n further by collecting the crests of\n the Orcs, the Quadav, and the\n Yagudo.'},[131]={'Riding on the Clouds','Client: Maat (Grand Duke Palace,\n Ru\'Lude Gardens)\nSummary:\n Use Maat\'s hints to search out four\n people who will trade you a strange\n stone for a Kindred\'s seal. Only then\n will you know your true limits.'},[132]={'Shattering Stars','Client: Maat (Grand Duke Palace,\n Ru\'Lude Gardens)\nSummary:\n Maat has issued a final challenge\n to test your limits. Return with the\n item he has requested and the trial\n will begin.'},[133]={'Beyond the Sun','Client: Maat (Grand Duke Palace,\n Ru\'Lude Gardens)\nSummary:\n After clearing all of Maat\'s final\n challenges, you will finally learn\n his secret...'},[134]={'New Worlds Await','Client: Nomad Moogle (Grand Duke\n Palace, Ru\'Lude Gardens)\nSummary:\n Has the enigmatic nomad moogle truly\n ascertained ancient secrets that will\n allow you to exceed long-standing\n limits?\n Acquire five Kindred\'s seals and\n three merit points and see for\n yourself!'},[135]={'Expanding Horizons','Client: Nomad Moogle (Grand Duke\n Palace, Ru\'Lude Gardens)\nSummary:\n The nomad moogle claims to have\n perfected another procedure that will\n send your powers burgeoning to even\n greater heights. Acquire five Kindred\'s\n crests and four merit points if you\n fancy yourself ready for the\n undertaking.'},[136]={'Beyond the Stars','Client: Nomad Moogle (Grand Duke\n Palace, Ru\'Lude Gardens)\nSummary:\n The nomad moogle claims to have\n perfected another procedure that will\n send your powers burgeoning to even\n greater heights. Acquire ten Kindred\'s\n crests and five merit points if you\n fancy yourself ready for the\n undertaking.'},[137]={'Dormant Powers Dislodged','Client: Nomad Moogle (Grand Duke\n Palace, Ru\'Lude Gardens)\nSummary:\n The nomad moogle has invited a\n Tarutaru of questionable affiliation\n to supervise his latest physical\n enhancement project.\n Acquire the items requested as well\n as ten merit points if you have the\n stomach to proceed.'},[138]={'Prelude to Puissance','Client: Nomad Moogle (Grand Duke\n Palace, Ru\'Lude Gardens)\nSummary:\n Atori-Tutori has a present for you,\n but first you must procure the\n seasoning stone he seeks...'},[139]={'Beyond Infinity','Client: Nomad Moogle (Grand Duke\n Palace, Ru\'Lude Gardens)\nSummary:\n Atori-Tutori has deigned to present\n you with your final challenge--a\n sparring match with the smug Taru\n himself. Acquire a soul gem and\n soul gem clasp and meet your\n opponent for the ultimate showdown.'},[140]={'A Trial in Tandem','Client: Luto Mewrilah\n (Artisan Bridge, Upper Jeuno)\nSummary:\n You have been entrusted with lifting\n the spirits of your comrade, who has\n been mired in a crisis of confidence\n since suffering defeat at the Qu\'Bia\n Arena. Head to the Ru\'Lude Gardens,\n where the Magian Mooglehood will\n offer their assistance.'},[141]={'A Trial in Tandem, Redux','Client: Luto Mewrilah\n (Artisan Bridge, Upper Jeuno)\nSummary:\n Another invitation has arrived from\n the Magian Mooglehood. Strike forth\n with your comrade in pursuit of yet\n loftier heights of power!'},[142]={'Yet Another Trial in Tandem','Client: Luto Mewrilah\n (Artisan Bridge, Upper Jeuno)\nSummary:\n Your comrade\'s zeal for self-\n improvement knows no limits, and the\n Magian Mooglehood stands ever ready\n to assist in this endeavor. Make your\n way to Ru\'Lude Gardens, where a new\n challenge awaits!'},[143]={'A Quaternary Trial in Tandem','Client: Luto Mewrilah\n (Artisan Bridge, Upper Jeuno)\nSummary:\n The Magian Mooglehood has requested\n the help of you and your companion\n once again, just in time to quench\n that thirst for knowledge and power!\n Venture to the Ru\'Lude Gardens to\n receive a taste of what\'s to come!'},[144]={'A Trial in Tandem Revisited','Client: Luto Mewrilah\n (Artisan Bridge, Upper Jeuno)\nSummary:\n Appease the Magian Mooglehood by\n slaying some brutes and appease your\n new client by collecting twenty\n Kindred\'s crests on the way to\n bettering yourself and your partner!'},[145]={'（仮）','依頼者\n　'},[146]={'Martial Mastery','Client: Atori-Tutori (Grand Duke\n Palace, Ru\'Lude Gardens)\nSummary:\n Amass fifteen merit points to fulfill\n your contract with Atori-Tutori and\n open the path to heretofore unseen\n powers...'},[147]={'VW Op. #115: Valkurm Duster','Client: Mawl\'gofaur\n (Audience Chamber, Ru\'Lude Gardens)\nSummary:\n A yet-unstable planar rift has been\n sighted in the Valkurm Dunes.\n Engage and eliminate any Voidwalkers\n that may emerge from this\n dimensional disturbance.'},[148]={'VW Op. #118: Buburimu Squall','Client: Mawl\'gofaur\n (Audience Chamber, Ru\'Lude Gardens)\nSummary:\n A yet-unstable planar rift has been\n sighted on Buburimu Peninsula.\n Engage and eliminate any Voidwalkers\n that may emerge from this\n dimensional disturbance.'},[149]={'Researchers from the West','Client: Anastase\n (Main Promenade, Ru\'Lude Gardens)\nSummary:\n A research expedition from the Sacred\n City of Adoulin is seeking\n collaborators. They require information\n about geomagnetic founts in various\n areas to assist in the testing of\n their mystical devices.'},[150]={'Middle Lands Investigation','Client: Anastase\n (Main Promenade, Ru\'Lude Gardens)\nSummary:\n Help find geomagnetic founts in the\n areas divined by eccentric\n clairvoyant, Quwi Orihbhe.'},[151]={'Further Founts','Client: Anastase\n (Main Promenade, Ru\'Lude Gardens)\nSummary:\n More geomagnetic founts have been\n discovered throughout the Middle\n Lands. Record any relevant data\n and report back to Anastase.'},[152]={'+Beam Me Up...No, Not There!','Client: Anastase\n (Main Promenade, Ru\'Lude Gardens)\nSummary:\n Some fount data has destabilized,\n causing travelers to be warped to\n unexpected locations. Use the\n waypoint to travel to these locations\n and re-record the data. Beware--you\n may not end up where you wanted to\n be.'},[153]={'+Now Recording...','Client: Darcia (Chamber of Commerce\n and Industry, Lower Jeuno)\nSummary:\n Not all tests are tests of steel. In\n order to get permission to visit\n Adoulin, you must record data located\n in a certain part of the Middle\n Lands. The Adventurers\' Mutual Aid\n Network will provide your reward.'},[154]={'Teleports by Twilight','Client: Nantoto (Merry Minstrel\n Meadhouse, Lower Jeuno)\nSummary:\n For adventurers of appropriate\n aptitude who have made a name for\n themselves through Records of\n Eminence: make a pilgrimage to six\n telepoints throughout Vana\'diel.'},[155]={'Shifty Shades of Prey','Client: Nantoto (Merry Minstrel\n Meadhouse, Lower Jeuno)\nSummary:\n For adventurers of even more\n appropriate aptitude whose feats in\n Records of Eminence are\n widely renowned: travel to the\n Eldieme Necropolis and shine some\n light on a few shadows.'},[156]={'To Kill Mocking Birds','Client: Nantoto (Merry Minstrel\n Meadhouse, Lower Jeuno)\nSummary:\n For adventurers of incredible aptitude\n whose feats in Records of Eminence\n are household topics of discussion:\n make some Yagudo High Priests in\n Castle Oztroja pray to their maker!'},[157]={'Full Speed Ahead!','Client: Mapitoto (Chocobo\n Stables, Upper Jeuno)\nSummary:\n Hop on board Mapitoto\'s slightly\n ornery raptor and head to Batallia\n Downs. Seek out Syrillia once you\n have arrived.'},[158]={'The Flying Machine of Eld','Client: Jeridade (Chocobo\n Stables, Upper Jeuno)\nSummary:\n Jeridade has a dream: to\n create a flying machine for the\n ages. If you have any leads,\n be sure to bring them to\n Mapitoto.'}},
  ot={name='Other Areas',[0]={'Rycharde the Chef','Client: Rycharde\n (Sailors\' Stay, Mhaura)\nSummary:\n Rycharde needs your help\n to find some dhalmel meat.'},[1]={'Way of the Cook','Client: Rycharde\n (Sailors\' Stay, Mhaura)\nSummary:\n Rycharde needs your help\n finding some ingredients.\n He needs a beehive chip\n and some dhalmel meat.'},[2]={'Unending Chase','Client: Rycharde\n (Sailors\' Stay, Mhaura)\nSummary:\n Rycharde wants you to get him\n an ingredient called a puffball.'},[3]={'His Name Is Valgeir','Client: Rycharde\n (Sailors\' Stay, Mhaura)\nSummary:\n Rycharde wants you to\n deliver a dish to Valgeir\n in Selbina, and report on\n how he liked it.'},[4]={'Expertise','Client: Take\n (Sailors\' Stay, Mhaura)\nSummary:\n Take wants you to bring\n back one of Valgeir\'s\n dishes from Selbina.'},[5]={'The Clue','Client: Rycharde\n (Sailors\' Stay, Mhaura)\nSummary:\n Rycharde seeks an ingredient\n known as crawler\'s eggs.'},[6]={'The Basics','Client: Rycharde\n (Sailors\' Stay, Mhaura)\nSummary:\n Rycharde wants you to\n deliver a dish to Valgeir\n in Selbina, and report on\n how he liked it.'},[7]={'Orlando\'s Antiques','Client: Orlando\n (Orlando\'s Antiques, Mhaura)\nSummary:\n Find where the Goblins bury\n their junk.\n Bring back eight of the same\n type of junk and Orlando will\n reward you well.'},[8]={'The Sand Charm','Client: Celestina (Goldsmiths\' \n Guild Salesroom, Mhaura)\nSummary:\n Retrieve the sand charm\n Celestina\'s father carried.\n Your one clue: a sailor\n saw a pirate wearing it.'},[9]={'A Potter\'s Preference','Client: Nereus\n (Sailors\' Stay, Mhaura)\nSummary:\n Nereus seeks a dish of\n Gusgen clay from the\n depths of the Gusgen Mines.'},[10]={'The Old Lady','Client: Vera\n (Outside Warehouse, Mhaura)\nSummary:\n Fulfill her request if you want\n the promised rewards.'},[11]={'Fisherman\'s Heart','Client: Katsunaga\n (Port Area, Mhaura)\nSummary:\n Bring Katsunaga a gugru\n tuna and he\'ll tell you\n all he knows about your\n fishing history.'},[12]={'OTクエスト12','説明\nこりゃでーれーてーへんなくえすとじゃけー'},[13]={'OTクエスト13','説明\nこりゃでーれーてーへんなくえすとじゃけー'},[14]={'Trial-Size Trial by Lightning','Client: Lacia (In front of\n the Sailors\' Stay, Mhaura)\nSummary:\n The Rhinostery has developed a\n new "mini" tuning fork of lightning.\n Ringing it upon the protocrystal\n in the Boyahda Tree will open\n the path to a one-on-one battle\n with the beast that awaits inside.\n However, only summoners are\n allowed to take up this challenge.'},[15]={'+Trial by Lightning','Client: Ripapa (In front of\n the Sailors\' Stay, Mhaura)\nSummary:\n Ring the tuning fork of lightning\n upon the protocrystal in the\n Boyahda Tree. A path will open to\n the trial that awaits.'},[16]={'OTクエスト14','説明\nこりゃでーれーてーへんなくえすとじゃけー'},[17]={'OTクエスト15','説明\nこりゃでーれーてーへんなくえすとじゃけー'},[18]={'Donate to Recycling','Client: Romeo (Atop Fishermen\'s\n Guild Salesroom, Selbina)\nSummary:\n Donate five pieces of\n onion equipment to help\n new recruits everywhere.\n Donors may receive an award.'},[19]={'Under the Sea','Client: Oswald\n (Shepherd\'s Muster, Selbina)\nSummary:\n Oswald needs help retrieving\n his ring from the\n jaws of the ocean.'},[20]={'Only the Best','Client: Melyon\n (Weavers\' Guild Salesroom, Selbina)\nSummary:\n Melyon will pay premium prices\n for any of the following:\n five heads of La Theine cabbage,\n three ears of millioncorn,\n one clump of Boyahda moss.\n'},[21]={'An Explorer\'s Footsteps','Client: Abelard\n (Mayor\'s Residence, Selbina)\nSummary:\n The mayor wants you to find\n stone monuments left by a certain\n adventurer and copy their writings\n to clay.'},[22]={'Cargo','Client: Vuntar\n (Foot of Central Stairs, Selbina)\nSummary:\n Vuntar will pay premium price\n for rolanberries, but for only\n those that are thoroughly aged \n and can serve as food for long\n voyages.'},[23]={'The Gift','Client: Oswald\n (Shepherd\'s Muster, Selbina)\nSummary:\n Oswald wants to order something\n nutritious to cheer his girlfriend\n up a bit. Get him the special\n ingredient, a danceshroom.'},[24]={'The Real Gift','Client: Oswald\n (Shepherd\'s Muster, Selbina)\nSummary:\n With his girlfriend still\n in the doldrums, Oswald\n wants to give her a pearl\n necklace. Find him a shall\n shell so he can make one.'},[25]={'The Rescue','Client: Thunder Hawk\n (Mayor\'s Residence, Selbina)\nSummary:\n Rescue two merchants from\n captivity. They should be\n somewhere in the Quadav\n camp in Beadeaux.'},[26]={'Elder Memories','Client: Isacio\n (Waterfront, Selbina)\nSummary:\n You must prove yourself worthy\n before you can learn Isacio\'s\n fighting techniques.'},[27]={'+Test My Mettle','Client: Devean (Behind\n Shepherd\'s Muster, Selbina)\nSummary:\n Find the pair of power sandals\n hidden in a jar somewhere\n in Davoi. Bring them back\n before time runs out\n for a cash prize.'},[28]={'Inside the Belly','Client: Zaldon (Fishermen\'s\n Guild Salesroom, Selbina)\nSummary:\n Some fish in Vana\'diel\n like to eat shiny objects.\n If you catch one, let Zaldon\n cut it open for you.'},[29]={'It\'s Raining Mannequins','Client: Fyi Chalmwoh (Goldsmiths\' \n Guild Salesroom, Mhaura)\nSummary:\n Fyi Chalmwoh wants to build a\n mannequin that rivals those of\n times past. It\'s your job to gather\n information on how to make one.'},[30]={'Recycling Rods','Client: Keshab-Menjab\n (Outside Orlando\'s Antiques,\n Mhaura)\nSummary:\n You\'ve been asked to help\n bring in cleanly snapped rods for\n recycling. The recycled rods are\n supposedly sold somewhere around\n Bibiki Bay.'},[31]={'Picture Perfect','Client: Diederik\n (Port, Selbina)\nSummary:\n Diederik has lost a painting ordered\n by a valued customer. He wants you\n to help him earn time or get a new\n painting before anyone notices.'},[32]={'+Waking the Beast','Client: Carbuncle\n (La Theine Plateau)\nSummary:\n Carbuncle wants you to visit all the\n protocrystals and gather the\n elemental energy of the sleeping\n gods. Will their imminent awakening\n mean fortune or doom for Vana\'diel?\n Only Carbuncle\'s ancient friend at the\n Full Moon Fountain may know...'},[33]={'Survival of the Wisest','Client: Prof. Schultz\n (Xarcabard)\nSummary:\n What will be the first and final\n assignment given to you by Gunther\n Schultz II, the legendary reformer of\n military strategy? Your rite of passage\n begins by obtaining a scholar\'s\n testimony...'},[34]={'Monstrosity','Client: Suspicious Hume\n (Pashhow Marshlands)\nSummary:\n You can expand the horizons of your\n soul, and it all begins by bringing\n either a rabbit hide, lizard tail,\n or two-leaf mandragora bud to one of\n the oddly accented and suspicious\n personages in Northern San d\'Oria,\n Port Bastok, or Port Windurst.'},[35]={'Kupofried\'s H2H Moogle Magic','Client: Kupofried\n (Walk of Echoes)\nSummary:\n Certain arcane powers known as\n "weapon skills" in adventurer\n vernacular can supposedly be harbored\n in one\'s body through the use of\n moogle magic.'},[36]={'Kupofried\'s Dagger Moogle Magic','Client: Kupofried\n (Walk of Echoes)\nSummary:\n Certain arcane powers known as\n "weapon skills" in adventurer\n vernacular can supposedly be harbored\n in one\'s body through the use of\n moogle magic.'},[37]={'Kupofried\'s Sword Moogle Magic','Client: Kupofried\n (Walk of Echoes)\nSummary:\n Certain arcane powers known as\n "weapon skills" in adventurer\n vernacular can supposedly be harbored\n in one\'s body through the use of\n moogle magic.'},[38]={'Kupofried\'s Great Sword Moogle Magic','Client: Kupofried\n (Walk of Echoes)\nSummary:\n Certain arcane powers known as\n "weapon skills" in adventurer\n vernacular can supposedly be harbored\n in one\'s body through the use of\n moogle magic.'},[39]={'Kupofried\'s Axe Moogle Magic','Client: Kupofried\n (Walk of Echoes)\nSummary:\n Certain arcane powers known as\n "weapon skills" in adventurer\n vernacular can supposedly be harbored\n in one\'s body through the use of\n moogle magic.'},[40]={'Kupofried\'s Great Axe Moogle Magic','Client: Kupofried\n (Walk of Echoes)\nSummary:\n Certain arcane powers known as\n "weapon skills" in adventurer\n vernacular can supposedly be harbored\n in one\'s body through the use of\n moogle magic.'},[41]={'Kupofried\'s Scythe Moogle Magic','Client: Kupofried\n (Walk of Echoes)\nSummary:\n Certain arcane powers known as\n "weapon skills" in adventurer\n vernacular can supposedly be harbored\n in one\'s body through the use of\n moogle magic.'},[42]={'Kupofried\'s Polearm Moogle Magic','Client: Kupofried\n (Walk of Echoes)\nSummary:\n Certain arcane powers known as\n "weapon skills" in adventurer\n vernacular can supposedly be harbored\n in one\'s body through the use of\n moogle magic.'},[43]={'Kupofried\'s Katana Moogle Magic','Client: Kupofried\n (Walk of Echoes)\nSummary:\n Certain arcane powers known as\n "weapon skills" in adventurer\n vernacular can supposedly be harbored\n in one\'s body through the use of\n moogle magic.'},[44]={'Kupofried\'s Great Katana Moogle Magic','Client: Kupofried\n (Walk of Echoes)\nSummary:\n Certain arcane powers known as\n "weapon skills" in adventurer\n vernacular can supposedly be harbored\n in one\'s body through the use of\n moogle magic.'},[45]={'Kupofried\'s Club Moogle Magic','Client: Kupofried\n (Walk of Echoes)\nSummary:\n Certain arcane powers known as\n "weapon skills" in adventurer\n vernacular can supposedly be harbored\n in one\'s body through the use of\n moogle magic.'},[46]={'Kupofried\'s Staff Moogle Magic','Client: Kupofried\n (Walk of Echoes)\nSummary:\n Certain arcane powers known as\n "weapon skills" in adventurer\n vernacular can supposedly be harbored\n in one\'s body through the use of\n moogle magic.'},[47]={'Kupofried\'s Archery Moogle Magic','Client: Kupofried\n (Walk of Echoes)\nSummary:\n Certain arcane powers known as\n "weapon skills" in adventurer\n vernacular can supposedly be harbored\n in one\'s body through the use of\n moogle magic.'},[48]={'Kupofried\'s Marksmanship Moogle Magic','Client: Kupofried\n (Walk of Echoes)\nSummary:\n Certain arcane powers known as\n "weapon skills" in adventurer\n vernacular can supposedly be harbored\n in one\'s body through the use of\n moogle magic.'},[49]={'OTクエスト49','説明\nOh!\nWhat a strange mission!!'},[50]={'OTクエスト50','説明\nOh!\nWhat a strange mission!!'},[51]={'OTクエスト51','説明\nOh!\nWhat a strange mission!!'},[52]={'OTクエスト52','説明\nOh!\nWhat a strange mission!!'},[53]={'OTクエスト53','説明\nOh!\nWhat a strange mission!!'},[54]={'OTクエスト54','説明\nOh!\nWhat a strange mission!!'},[55]={'OTクエスト55','説明\nOh!\nWhat a strange mission!!'},[56]={'OTクエスト56','説明\nOh!\nWhat a strange mission!!'},[57]={'OTクエスト57','説明\nOh!\nWhat a strange mission!!'},[58]={'OTクエスト58','説明\nOh!\nWhat a strange mission!!'},[59]={'OTクエスト59','説明\nOh!\nWhat a strange mission!!'},[60]={'OTクエスト60','説明\nOh!\nWhat a strange mission!!'},[61]={'OTクエスト61','説明\nOh!\nWhat a strange mission!!'},[62]={'OTクエスト62','説明\nOh!\nWhat a strange mission!!'},[63]={'OTクエスト63','説明\nOh!\nWhat a strange mission!!'},[64]={'A Hard Day\'s Knight','Client: Quelveuiat (Altar of the Dawn,\n Tavnazia)\nSummary:\n Your initiation into the Tavnazian\n order of knights requires you to\n assess the situation from the\n lookout platform in the south of\n Lufaise Meadows.'},[65]={'X Marks the Spot','Client: Despachiaire (Elders\' Quarters,\n Tavnazia)\nSummary:\n Despachiaire has asked you to\n investigate the Mithran Tracker\n who has come looking for\n Cardinal Mildaurion.'},[66]={'A Bitter Past','Client: Frescheque\n (Third floor, Tavnazian Safehold)\nSummary:\n Try to find some information on\n the fate of a little girl who was\n kidnapped in a forest near the\n safehold. Her father says that she\n was wearing a tiny wristlet that is\n similar to her mother\'s.'},[67]={'The Call of the Sea','Client: Anteurephiaux\n (First Floor, Tavnazian Safehold)\nSummary:\n You\'ve been asked to travel to the\n Tavnazian coastline and find a rare\n shell carried by a monster--\n preferably a "spirally" one that\n makes sound when you blow into it.'},[68]={'Paradise, Salvation, and Maps','Client: Nivorajean\n (Second floor, Tavnazian Safehold)\nSummary:\n To complete a map of the\n Sacrarium, Nivorajean needs\n you to find a piece of the\n old floorplans.'},[69]={'Go! Go! Gobmuffin!','Client: Epinolle\n (Third floor, Tavnazian Safehold)\nSummary:\n Epinolle wants you to find and\n bring back a Goblin that has left\n for Cape Riverne to make a map\n of the area.'},[70]={'+The Big One','Client: Travonce\n (Tributary, Tavnazian Safehold)\nSummary:\n Travonce\'s final wish before he\n dies is to reel in "the big one."\n However, your services are required\n to protect him from the monsters\n that lurk below the calm waters of\n Lufaise Meadows.'},[71]={'Fly High','Client: Ferchinne\n (Tributary, Tavnazian Safehold)\nSummary:\n "A noble bird that walks on four\n legs. A proud beast that has the\n wings of an eagle." No, this is not\n a riddle; it is a description of the\n beast from which you must retrieve\n two tailfeathers.'},[72]={'Unforgiven','Client: Elysia\n (Second Floor, Tavnazian Safehold)\nSummary:\n Find and bring back the hairpin\n that Elysia dropped while doing\n her shopping.'},[73]={'+Secrets of Ovens Lost','Client: Jonette\n (Tributary, Tavnazian Safehold)\nSummary:\n Jonette\'s dream is to revitalize the\n safehold\'s children by serving them\n an array of traditional Tavnazian\n dishes. However, she needs a\n cookbook to fulfill that dream.'},[74]={'Petals for Parelbriaux','Client: Ondieulix\n (Main Entrance, Tavnazian Safehold)\nSummary:\n You have been asked to find a\n rare plant that is often used in\n medicines. It supposedly grows\n somewhere on the Lufaise Meadows.'},[75]={'Elderly Pursuits','Client: Despachiaire (Elders\' Quarters,\n Tavnazia)\nSummary:\n Despachiaire has asked you to\n investigate the origin of his late\n wife\'s amulet.'},[76]={'In the Name of Science','Client: Yurim (First Floor,\n Tavnazia)\nSummary:\n Yurim wants to show you the\n fruits of her research, but lacks\n the materials to begin the final\n stage of the experiment.\n\n You know what you have to do!'},[77]={'Behind the Smile','Client: Enaremand\n (Third floor, Tavnazian Safehold)\nSummary:\n One last material is required to\n complete Enaremand\'s final masterpiece.\n Perhaps the mannequin craftswoman\n in Mhaura has some clues to where\n you may be able to find it.'},[78]={'Knocking on Forbidden Doors','Client: Enaremand\n (Third floor, Tavnazian Safehold)\nSummary:\n Enaremand\'s final masterpiece is\n complete, but not as complete\n as he would like. The troubled\n mannequin craftsman has now asked\n you to help him find a necromancer\n in order to breathe life into\n his creation...'},[79]={'Confessions of a Bellmaker','Client: ??? (Stone Monument,\n Riverne - Site #A01)\nSummary:\n A mysterious figure has requested\n your help repairing an old bell\n damaged in the recent earthquakes.'},[80]={'In Search of the Truth','Client: Tressia\n (Patrol HQ, Tavnazian Safehold)\nSummary:\n Search for information regarding\n what happened on the day\n Wazozo\'s treasure was stolen.'},[81]={'+Uninvited Guests','Client: Justinius\n (Patrol HQ, Tavnazian Safehold)\nSummary:\n You have been asked to expel the\n black-robed intruders lurking around\n Monarch Linn.'},[82]={'Tango with a Tracker','Client: Despachiaire (Elders\' Quarters,\n Tavnazia)\nSummary:\n A letter from Shikaree X addressed\n to you has arrived in the safehold.\n It appears she wants to gauge your\n battle prowess in Boneyard Gully.'},[83]={'Requiem of Sin','Client: Despachiaire (Elders\' Quarters,\n Tavnazia)\nSummary:\n A letter from Shikaree Y addressed\n to you has arrived in the safehold.\n It appears you have been challenged\n to a duel in Boneyard Gully.'},[84]={'VW Op. #026: Tavnazian Terrors','Client: Owain\n (Main Entrance, Tavnazian Safehold)\nSummary:\n Reports suggest that planar rifts have\n materialized in Lufaise Meadows, the\n Misareaux Coast, the Uleguerand Range,\n and Attohwa Chasm. Engage and\n exterminate any interdimensional\n threats you may face.'},[85]={'VW Op. #004: Bibiki Bombardment','Client: Owain\n (Main Entrance, Tavnazian Safehold)\nSummary:\n Word has it that planar rifts have\n arisen in Bibiki Bay, and that the\n dauntless Prishe has set out to put a\n stop to them. Get there first and\n exterminate all the interdimensional\n beasties you find!'},[86]={'OTクエスト86','説明\nOh!\nWhat a strange mission!!'},[87]={'OTクエスト87','説明\nOh!\nWhat a strange mission!!'},[88]={'OTクエスト88','説明\nOh!\nWhat a strange mission!!'},[89]={'OTクエスト89','説明\nOh!\nWhat a strange mission!!'},[90]={'OTクエスト90','説明\nOh!\nWhat a strange mission!!'},[91]={'OTクエスト91','説明\nOh!\nWhat a strange mission!!'},[92]={'OTクエスト92','説明\nOh!\nWhat a strange mission!!'},[93]={'OTクエスト93','説明\nOh!\nWhat a strange mission!!'},[94]={'OTクエスト94','説明\nOh!\nWhat a strange mission!!'},[95]={'OTクエスト95','説明\nOh!\nWhat a strange mission!!'},[96]={'Bombs Away!','Client: Buffalostalker Dodzbraz\n (Uleguerand Range)\nSummary:\n Dodzbraz is an Orc that despises\n snolls.\n If you bring him two "cluster cores,"\n Dodzbraz will give you something\n useful to use against them.'},[97]={'Mithran Delicacies','Client: Anguenet\n (Carpenters\' Landing)\nSummary:\n If you give a "muddy siredon" to the\n Tonberry that stands beside\n Anguenet, he will make you one of\n the Mithra\'s favorite foods.'},[98]={'Missionary Moblin','Client: Koblakiq\n (Oldton Movalpolos)\nSummary:\n Koblakiq has stopped receiving\n letters from her brother Zeelozok\n after he went to speak with the\n Orcish overlord in Davoi.\n Koblakiq wants you to go there\n and search for him.'},[99]={'For the Birds','Client: Koblakiq\n (Oldton Movalpolos)\nSummary:\n A letter has arrived from Zeelozok\n asking for an "arnica root" to be\n brought to Castle Oztroja.\n Koblakiq has entrusted this task\n to you...'},[100]={'Better the Demon You Know','Client: Koblakiq\n (Oldton Movalpolos)\nSummary:\n Zeelozok has set out on a journey\n to destroy the Kindred\'s Divinity\n of Darkness. Koblakiq wants you\n to find her a "Demon pen" so she\n can learn more about their demon\n adversaries.'},[101]={'OTクエスト99','説明\nOh!\nWhat a strange mission!!'},[102]={'Give a Moogle a Break','Client: Moogle\n (Mog House)\nSummary:\n Your moogle wants to take\n a power bow and a beetle ring\n to his family for the holidays.\n He sure would be happy\n if you found them for him.'},[103]={'The Moogle\'s Picnic!','Client: Moogle\n (Mog House)\nSummary:\n Your moogle wants to take a\n shrimp lure and some Selbina butter\n back home. He sure would be happy\n if you found them for him.'},[104]={'Moogles in the Wild','Client: Moogle\n (Mog House)\nSummary:\n Your moogle wants to take a\n raptor mantle and a wool hat to\n his friends in the Outlands.\n He sure would be happy if you found\n them for him.'},[105]={'+An Understanding Overlord?','Client:\n Loo Kohor (Monastic Cavern)\nSummary:\n Yagudo messenger Loo Kohor needs\n to deliver an important message.\n However, he cannot proceed, as he\n is attacked every time he sets foot\n in the Monastic Cavern. Your job is\n to take the missive and place it\n where the Overlord is sure to find it.'},[106]={'+An Affable Adamantking?','Client:\n Raptorlegs Gedwad (Qulun Dome)\nSummary:\n Gedwad has orders to sneak into\n the Qulun Dome and gather info on\n the Quadav\'s defenses. However, he\n is stuck at the entrance. Your job\n is to take Gedwad\'s seeker bats and\n place them somewhere they can spy\n on the Adamantking.'},[107]={'+A Moral Manifest?','Client:\n Hooknox (Altar Room)\nSummary:\n Hooknox\'s plan to steal treasure\n from the Yagudo vault falls through\n when her disguise becomes too\n itchy. Your job is to take the key\n Hooknox swiped and use it to\n collect the riches...without being\n discovered by the Yagudo guards.'},[108]={'+A Generous General?','Client:\n Gu\'Zho Thunderblade\n (Oldton Movalpolos)\nSummary:\n Gu\'Zho has traveled to Movalpolos\n to become a mercenary. However,\n he cannot find the box to submit\n his application. Your job is to take\n Gu\'Zho\'s letter to the box and lead\n the Goblin serjeant back to where\n Thunderblade will be waiting.'},[109]={'Records of Eminence','\nSummary:\n You have officially taken your first\n step down the road to fame with the\n Adventurers\' Mutual Aid Network\'s new\n system: Records of Eminence.\n Now go clear some objectives and\n show Vana\'diel your true worth!'},[110]={'Unity Concord','\nSummary:\n Fight for the glory of your Unity\n leader under this new system\n established by the Adventurers\'\n Mutual Aid Network!'},[111]={'Full Fields','Client: Green Thumb Moogle\n (Mog Garden)\nSummary:\n Peek inside the basket that rests at\n the end of the Mog Garden furrow.'},[112]={'Green Groves','Client: Green Thumb Moogle\n (Mog Garden)\nSummary:\n Look around the grove of trees in the\n Mog Garden.'},[113]={'Mining Missive','Client: Green Thumb Moogle\n (Mog Garden)\nSummary:\n Examine the large boulder in the\n Mog Garden.'},[114]={'Pond Probing','Client: Green Thumb Moogle\n (Mog Garden)\nSummary:\n Test the waters of the Mog Garden\n pond.'},[115]={'Coastal Chaos','Client: Green Thumb Moogle\n (Mog Garden)\nSummary:\n Haul in the net cast off the coast of\n the Mog Garden.'},[116]={'Seed Sowing','Client: Green Thumb Moogle\n (Mog Garden)\nSummary:\n Take a look at the basket near the\n Mog Garden furrow and sow a seed.'},[117]={'Flotsam Finding','Client: Green Thumb Moogle\n (Mog Garden)\nSummary:\n Check what drifted in on the tide by\n examining a spot on the Mog Garden\'s\n coastline.'},[118]={'Courtesy Crustacean','Client: Green Thumb Moogle\n (Mog Garden)\nSummary:\n The Green Thumb Moogle\'s friend,\n Monsieur Kupont, is coming to pay him\n a visit, and the vacationing visitor\n appreciates rare and beautiful shells.\n There simply has to be some original\n marine life in the Mog Garden...'},[119]={'Trinket for the Tyrant','Client: Green Thumb Moogle\n (Mog Garden)\nSummary:\n Now Monsieur Kupont\'s villainous\n friend Kupivolo is joining the fray in\n the Adoulin Islands. Placate this\n pernicious patron by acquiring some\n article of note within the\n Mog Garden.'},[120]={'Hypnotic Hospitality','Client: Green Thumb Moogle\n (Mog Garden)\nSummary:\n A mob of merry moogles has\n manifested in your Mog Garden.\n Stockpile the subsequent sundries so\n your grand guests can be properly\n pampered: a moat carp creel from the\n pond as well as a branch of gnatbane\n and a date from the furrows.'},[121]={'Titillating Tomes','Client: Green Thumb Moogle\n (Mog Garden)\nSummary:\n The Great Kupellion has come to your\n Mog Garden to help cure the MHMU\n scholars\' wibbly wobbly woozies.\n He will need drill calamary from the\n coastal fishing net, a calico comet\n from the pond, and a philosopher\'s\n stone from a mineral vein.'},[122]={'Release the Fleece','Client: Green Thumb Moogle\n (Mog Garden)\nSummary:\n Susuroon swears fearsome beasts are\n menacing the garden, and employed\n Chacharoon--a supposedly world-class\n bodyguard--to deal with the threat.\n For now, let the bodyguard\'s lamb\n roam free in the Mog Garden to lure\n these monsters in.'},[123]={'Feeding Frenzy','Client: Green Thumb Moogle\n (Mog Garden)\nSummary:\n The fearsome beasts in question\n are apparently a rare breed of crab\n that plagued the garden before. While\n Atelloune\'s research on them may\n yield helpful clues, all you can do is\n motivate the lamb by feeding it\n La Theine cabbage.'},[124]={'Cry Not, Caretaker','Client: Green Thumb Moogle\n (Mog Garden)\nSummary:\n Crabs have ambushed and killed\n Chacharoon\'s beloved lamb. He has\n decided not to waste the animal\'s\n life, and thus needs a spool of cotton\n thread to craft an item to bolster his\n defenses and honor his fallen friend.'},[125]={'Chacharoon\'s Cheer','Client: Susuroon\n (Mog Garden)\nSummary:\n Susuroon needs your help getting\n Chacharoon interested in the jingly.\n The young Qiqirn idolizes adventurer\n types, so try handing him a gold\n beastcoin to convince him of your\n worth.'},[126]={'Trial of the Chacharoon','Client: Susuroon\n (Mog Garden)\nSummary:\n Chacharoon\'s life savings have been\n pilfered by some uncouth savage, and\n Susuroon can\'t face the young one\n himself. Head toward the newly\n cultivated area via the path located\n near the boat to find him.'},[127]={'Doctor Chacharoon','Client: Chacharoon\n (Mog Garden)\nSummary:\n Chacharoon has asked you to help\n rescue a sickly adamantoise hatchling\n that has washed up on the shore.\n According to Chacharoon\'s diagnosis,\n the turtle needs hot soup to recover.\n Gather 12 crayfish for the soup and\n trade them to the Green Thumb Moogle.'},[128]={'Rowing Together','Client: Green Thumb Moogle\n (Mog Garden)\nSummary:\n While preparing to accommodate four\n creatures in the Mog Garden\'s rearing\n grounds, Chacharoon has suddenly\n found himself inundated with work.\n Concerned for his health, the Green\n Thumb Moogle has sent you to the\n Goblins\' shop in Lower Jeuno to help\n him gather supplies.'},[129]={'Glittering Gals','Client: Green Thumb Moogle\n (Mog Garden)\nSummary:\n A mysterious troupe of wistful women\n has come to your Mog Garden. They\n seem to be interested in riding\n crabs. Assist them in their endeavor\n by cultivating seeds in your garden.'},[130]={'Sally Forth!','Client: Green Thumb Moogle\n (Mog Garden)\nSummary:\n The engimatic troupe is now interested\n in sheep. Help the Green Thumb moogle\n out by bringing him Grow-M-Good.'}},
  fr={name='Outlands',[0]={'FR Quest 0','Client：\n　'},[1]={'+The Firebloom Tree','Client: Soun Abralah (Ryuhkowa\'s\n Mercenary Merchandise, Kazham)\nSummary:\n Journey to the Yuhtunga Jungle and\n retrieve a piece of firebloom wood\n from the most fire-resistant side of\n the Firebloom Tree. To check the\n most fire-resistant side, you must\n take a vine from each side of the\n tree to Ifrit\'s Cauldron for testing.'},[2]={'+Greetings to the Guardian','Client: Hari Pakhroib (Pakhroib\'s\n Residence, Kazham)\nSummary:\n Take your offering to the guardian\n of Kazham to the altar on the crater\n of Mount Yuhtunga.'},[3]={'+A Question of Taste','Client: Jakoh Wahcondalo\n (Wahcondalo\'s Residence, Kazham)\nSummary:\n It all started with a letter sent to\n Kazham\'s chieftainness by the young\n Windurstian artist, Angelica. Now,\n no one can stop the budding painter.'},[4]={'Everyone\'s Grudging','Client: Jakoh Wahcondalo\n (Wahcondalo\'s Residence, Kazham)\nSummary:\n You have been cursed by the\n Tonberries\' rancor flames, and\n Kazham\'s chieftainness has ordered\n you out of the village.'},[5]={'FR Quest 5','Client：\n　'},[6]={'You Call That a Knife?','Client: Mhebi Juhbily (Near Mihgo\'s\n Residence, Kazham)\nSummary:\n Mhebi wants to set her Tonberry\n free, but first, someone has to do\n something about his rusty knife.'},[7]={'Missionary Man','Client: Rauteinot (Near the village\n gate, Kazham)\nSummary:\n First, find a slab of Elshimo marble\n in the Yuhtunga Jungle to help the\n young missionary realize his vision.'},[8]={'Gullible\'s Travels','Client: Magriffon (Celodehki\'s\n Bed & Breakfast, Kazham)\nSummary:\n Magriffon has given all his worldly\n possessions to save a pack of poor\n Opo-opos from starvation. Now he\n needs someone to save him from\n getting kicked out of the bed &\n breakfast before he has completed\n his "top-secret" mission.'},[9]={'Even More Gullible\'s Travels','Client: Magriffon (Celodehki\'s\n Bed & Breakfast, Kazham)\nSummary:\n Magriffon has spent all of his (your?)\n money to save a maiden in distress.\n Now he needs someone to save him\n (again) from getting kicked out of\n the bed & breakfast before he has\n completed his "top-secret" mission.'},[10]={'Personal Hygiene','Client: Gatih Mijurabi (M & P\'s\n Market, Kazham)\nSummary:\n The Mithra of Kazham are having a\n hard time holding in their lunches,\n thanks to the hideous odor you\n obtained after getting too close to\n the blue Rafflesia pollen. The only\n way to get clean is by taking a\n long dip in a hot spring located\n deep beneath the sea.'},[11]={'The Opo-opo and I','Client: Vuih Stecoppah (Docks,\n Kazham)\nSummary:\n The Opo-opo in Kazham love your\n new "fragrance." Bring them what\n they want--in the correct order--\n and they will make you their king!'},[12]={'Cloak and Dagger','Client: Jakoh Wahcondalo\n (Wahcondalo\'s Residence, Kazham)\nSummary:\n The Chieftainess has come up with\n a deadly new dagger technique, but\n needs you to help her devise a way\n of dodging it. However, you must\n first complete your training.'},[13]={'+A Discerning Eye (Kazham)','Client: Swift (Airship Dock, Kazham)\nSummary:\n You have been asked to return a\n dropped item to its rightful owner.\n The passenger should be on the next\n airship flight.'},[14]={'FRクエスト16','依頼者：\n　'},[15]={'FRクエスト17','依頼者：\n　'},[16]={'FRクエスト18','依頼者：\n　'},[17]={'FRクエスト19','依頼者：\n　'},[18]={'FRクエスト20','依頼者：\n　'},[19]={'FRクエスト21','依頼者：\n　'},[20]={'FRクエスト22','依頼者：\n　'},[21]={'FRクエスト23','依頼者：\n　'},[22]={'FRクエスト24','依頼者：\n　'},[23]={'FRクエスト25','依頼者：\n　'},[24]={'FRクエスト26','依頼者：\n　'},[25]={'FRクエスト27','依頼者：\n　'},[26]={'FRクエスト28','依頼者：\n　'},[27]={'FRクエスト29','依頼者：\n　'},[28]={'FRクエスト30','依頼者：\n　'},[29]={'Trial-Size Trial by Fire','Client: Dodmos (Near Wahcondalo\'s\n Residence, Kazham)\nSummary:\n The Rhinostery has developed a\n new "mini" tuning fork of fire.\n Ringing it upon the protocrystal\n in Ifrit\'s Cauldron will open\n the path to a one-on-one battle\n with the beast that awaits inside.\n However, only summoners are\n allowed to take up this challenge.'},[30]={'+Trial by Fire','Client: Ronta-Onta (Near\n Wahcondalo\'s Residence, Kazham)\nSummary:\n Ring the tuning fork of fire upon\n the protocrystal in Ifrit\'s Cauldron.\n A path will open to the trial that\n awaits.'},[31]={'FRクエスト31','依頼者：\n　'},[32]={'FRクエスト32','依頼者：\n　'},[33]={'FRクエスト33','依頼者：\n　'},[34]={'FRクエスト34','依頼者：\n　'},[35]={'FRクエスト35','依頼者：\n　'},[36]={'FRクエスト36','依頼者：\n　'},[37]={'FRクエスト37','依頼者：\n　'},[38]={'FRクエスト38','依頼者：\n　'},[39]={'FRクエスト39','依頼者：\n　'},[40]={'FRクエスト40','依頼者：\n　'},[41]={'FRクエスト41','依頼者：\n　'},[42]={'FRクエスト42','依頼者：\n　'},[43]={'FRクエスト43','依頼者：\n　'},[44]={'FRクエスト44','依頼者：\n　'},[45]={'FRクエスト45','依頼者：\n　'},[46]={'FRクエスト46','依頼者：\n　'},[47]={'FRクエスト47','依頼者：\n　'},[48]={'FRクエスト48','依頼者：\n　'},[49]={'FRクエスト49','依頼者：\n　'},[50]={'FRクエスト50','依頼者：\n　'},[51]={'FRクエスト51','依頼者：\n　'},[52]={'FRクエスト52','依頼者：\n　'},[53]={'FRクエスト53','依頼者：\n　'},[54]={'FRクエスト54','依頼者：\n　'},[55]={'FRクエスト55','依頼者：\n　'},[56]={'FRクエスト56','依頼者：\n　'},[57]={'FRクエスト57','依頼者：\n　'},[58]={'FRクエスト58','依頼者：\n　'},[59]={'FRクエスト59','依頼者：\n　'},[60]={'FRクエスト60','依頼者：\n　'},[61]={'FRクエスト61','依頼者：\n　'},[62]={'FRクエスト62','依頼者：\n　'},[63]={'FRクエスト63','依頼者：\n　'},[64]={'FRクエスト64','依頼者：\n　'},[65]={'FRクエスト65','依頼者：\n　'},[66]={'FRクエスト66','依頼者：\n　'},[67]={'FRクエスト67','依頼者：\n　'},[68]={'FRクエスト68','依頼者：\n　'},[69]={'FRクエスト69','依頼者：\n　'},[70]={'FRクエスト70','依頼者：\n　'},[71]={'FRクエスト71','依頼者：\n　'},[72]={'FRクエスト72','依頼者：\n　'},[73]={'FRクエスト73','依頼者：\n　'},[74]={'FRクエスト74','依頼者：\n　'},[75]={'FRクエスト75','依頼者：\n　'},[76]={'FRクエスト76','依頼者：\n　'},[77]={'FRクエスト77','依頼者：\n　'},[78]={'FRクエスト78','依頼者：\n　'},[79]={'FRクエスト79','依頼者：\n　'},[80]={'FRクエスト80','依頼者：\n　'},[81]={'FRクエスト81','依頼者：\n　'},[82]={'FRクエスト82','依頼者：\n　'},[83]={'FRクエスト83','依頼者：\n　'},[84]={'FRクエスト84','依頼者：\n　'},[85]={'FRクエスト85','依頼者：\n　'},[86]={'FRクエスト86','依頼者：\n　'},[87]={'FRクエスト87','依頼者：\n　'},[88]={'FRクエスト88','依頼者：\n　'},[89]={'FRクエスト89','依頼者：\n　'},[90]={'FRクエスト90','依頼者：\n　'},[91]={'FRクエスト91','依頼者：\n　'},[92]={'FRクエスト92','依頼者：\n　'},[93]={'FRクエスト93','依頼者：\n　'},[94]={'FRクエスト94','依頼者：\n　'},[95]={'FRクエスト95','依頼者：\n　'},[96]={'FRクエスト96','依頼者：\n　'},[97]={'FRクエスト97','依頼者：\n　'},[98]={'FRクエスト99','依頼者：\n　'},[99]={'FRクエスト106','依頼者：\n　'},[100]={'FRクエスト107','依頼者：\n　'},[101]={'FRクエスト108','依頼者：\n　'},[102]={'FRクエスト109','依頼者：\n　'},[103]={'FRクエスト110','依頼者：\n　'},[104]={'FRクエスト111','依頼者：\n　'},[105]={'FRクエスト112','依頼者：\n　'},[106]={'FRクエスト113','依頼者：\n　'},[107]={'FRクエスト114','依頼者：\n　'},[108]={'FRクエスト115','依頼者：\n　'},[109]={'FRクエスト116','依頼者：\n　'},[110]={'FRクエスト117','依頼者：\n　'},[111]={'FRクエスト118','依頼者：\n　'},[112]={'FRクエスト119','依頼者：\n　'},[113]={'FRクエスト120','依頼者：\n　'},[114]={'FRクエスト121','依頼者：\n　'},[115]={'FRクエスト122','依頼者：\n　'},[116]={'FRクエスト123','依頼者：\n　'},[117]={'FRクエスト124','依頼者：\n　'},[118]={'FRクエスト125','依頼者：\n　'},[119]={'FRクエスト126','依頼者：\n　'},[120]={'FRクエスト127','依頼者：\n　'},[121]={'The Sahagin\'s Key','Client：\n　'},[122]={'Forge Your Destiny','Client: Jaucribaix (Near the Captain\'s\n Quarters, Norg)\nSummary:\n A lump of bomb steel and a sacred\n branch are required to make a new\n katana. You will have to ask\n Jaucribaix\'s pupils to find out where\n you can get these items.'},[123]={'Black Market','Client: Muzaffar (Storage area, Norg)\nSummary:\n Bring sets of either four northern\n furs, four pieces of eastern pottery,\n or four southern mummies for a\n hefty reward.'},[124]={'Mama Mia','Client：Mamaulabion (Near the\n Auction House, Norg)\nSummary:\n Mamaulabion would like you to\n bring him any "thuper-dee-duper,\n overflowing with thpethial power\n itemth" you happen to come across\n in your travels. However, he was\n not able to provide you with any\n details on their whereabouts.'},[125]={'Stop Your Whining','Client: Washu (Buccaneer\'s Quarters,\n Norg)\nSummary:\n Fill up an empty barrel with Opo-opo\n brew found fermenting in trees in\n the Yhoator Jungle, and bring it\n back to Norg ASAP.'},[126]={'Everyone\'s Grudge','Client: Magephaud (Next to the\n central staircase, Norg)\nSummary:\n Bring back three gold beastcoins if\n you want to learn how to rid\n yourself of the Tonberries\' rancor.'},[127]={'Secret of the Damp Scroll','Client: Shivivi (Near the Captain\'s\n Quarters, Norg)\nSummary:\n Take the damp scroll you have to\n Horlais Peak and dip it into the hot\n springs there. Only then will you be\n able to read it.'},[128]={'The Sahagin\'s Stash','Client: Laisrean (Storage area,\n Norg)\nSummary:\n Bring back something from the\n Sahagins\' storage area in the Sea\n Serpent Grotto. Anything will do.'},[129]={'It\'s Not Your Vault','Client: Keal (Quay, Norg)\nSummary:\n Bring back a sealed iron box from\n the Sahagin-infested Norg vault.'},[130]={'Like a Shining Subligar','Client: Heiji (2nd floor, Norg)\nSummary:\n Ten rusty subligaria are needed for\n the training of young ninjas. Heiji\n will accept them one at a time.'},[131]={'Like Shining Leggings','Client: Heizo (2nd floor, Norg)\nSummary:\n Ten pairs of rusty leggings are\n needed for the training of young\n ninjas. Heizo will accept them one\n at a time.'},[132]={'The Sacred Katana','Client: Jaucribaix (Near the Captain\'s\n Quarters, Norg)\nSummary:\n Your mumeito and a handful of\n crystal scales are needed to forge\n a katana that will be used in a\n Norg ritual.'},[133]={'Yomi Okuri','Client: Gilgamesh (Captain\'s Quarters,\n Norg)\nSummary:\n Twenty years ago, a small nation\n was destroyed by the flames of war,\n and many died without reason.\n Your assistance is required in\n holding a ritual to send these\n troubled souls to their proper\n resting place in the afterlife.'},[134]={'A Thief in Norg!?','Client: Gilgamesh (Captain\'s Quarters,\n Norg)\nSummary:\n At the close of the Great War,\n Gilgamesh\'s father trapped a terrible\n spirit within a helm. That helm has\n been stolen, and it is your job to\n hunt down the thief and get it back.'},[135]={'20 in Pirate Years','Client: Ryoma (Quay, Norg)\nSummary:\n Norg has begun investigating an\n ancient scroll that was rediscovered\n as of late. Speak with Tenshodo\n member Kagetora in Bastok for\n more details.'},[136]={'I\'ll Take the Big Box','Client: Ryoma (Quay, Norg)\nSummary:\n The trick box that you brought back\n to Norg has been identified as a\n fake. Your assistance is required in\n finding the real box. Start your\n search by pressing Ensetsu in Bastok\n for more information.'},[137]={'True Will','Client: Ryoma (Quay, Norg)\nSummary:\n The Sahagin have stolen Mitsunari\'s\n treasure and hid it somewhere in the\n jungle on Elshimo Island.  It is\n your job to find it.'},[138]={'The Potential Within','Client: Jaucribaix (Near the Captain\'s\n Quarters, Norg)\nSummary:\n Use the katana given to you by\n Jaucribaix to find your true potential.\n When the blade has lost its power,\n then you will know you have been\n accepted.'},[139]={'Bugi Soden','Client: Ryoma (Quay, Norg)\nSummary:\n Wield the katana given to you by\n Ryoma until it has been drained of\n its power. Only then will you be\n ready to inherit the knowledge of the\n ancient ninja masters.'},[140]={'An Undying Pledge','Client:\n Stray Cloud\n (Quay, Norg)\nSummary:\n Find Stray Cloud\'s friend Gubokka\n in the Sea Serpent Grotto.'},[141]={'FRクエスト150','依頼者：\n　'},[142]={'Trial-Size Trial by Water','Client: Verctissa (Near\n the Quay, Norg)\nSummary:\n The Rhinostery has developed a\n new "mini" tuning fork of water.\n Ringing it upon the protocrystal\n in the Den of Rancor will open\n the path to a one-on-one battle\n with the beast that awaits inside.\n However, only summoners are\n allowed to take up this challenge.'},[143]={'+Trial by Water','Client: Edal-Tahdal (Near\n the Quay, Norg)\nSummary:\n Ring the tuning fork of water upon\n the protocrystal in the Den of\n Rancor. A path will open to the\n trial that awaits.'},[144]={'FRクエスト151','依頼者：\n　'},[145]={'FRクエスト152','依頼者：\n　'},[146]={'FRクエスト153','依頼者：\n　'},[147]={'FRクエスト154','依頼者：\n　'},[148]={'FRクエスト155','依頼者：\n　'},[149]={'FRクエスト156','依頼者：\n　'},[150]={'FRクエスト157','依頼者：\n　'},[151]={'FRクエスト158','依頼者：\n　'},[152]={'FRクエスト159','依頼者：\n　'},[153]={'Wrath of the Opo-opos','Summary:\n The Opo-opos are not happy that\n you stole their "red treasure."\n Perhaps a polished stone of the\n same color would satisfy them?'},[154]={'Wandering Souls','Summary:\n Is there any way to soothe\n the spirits that wander about\n Cape Teriggan?\n Perhaps a rain lily...?'},[155]={'Soul Searching','Summary:\n Dispel the troubled souls of\n those who perished while on\n their pilgrimages.'},[156]={'Divine Might','Client: Yve\'noile (Entry Hall,\n The Shrine of Ru\'Avitau)\nSummary:\n Use the Ark Pentasphere at the\n La\'Loff Amphitheater to confront\n and defeat all five Crystal Warriors\n simultaneously.'},[157]={'Divine Might','Client: Yve\'noile (Entry Hall,\n The Shrine of Ru\'Avitau)\nSummary:\n The dissipated essence of the\n Crystal Warriors has once again\n coalesced into physical form.\n Your battle is not yet over!'},[158]={'Open Sesame','Client: Lokpix (Eastern Altepa Desert)\nSummary:\n There\'s supposedly a way to open\n that troublesome door in the\n Quicksand Caves by yourself. If you\n wish to know the secret, bring back\n a tremorstone and a meteorite.\n Should you lack a meteorite, either\n a soil gem or twelve soil geodes\n will suffice.'},[159]={'FRクエスト166','依頼者：\n　'},[160]={'FRクエスト167','依頼者：\n　'},[161]={'FRクエスト168','依頼者：\n　'},[162]={'FRクエスト169','依頼者：\n　'},[163]={'FRクエスト170','依頼者：\n　'},[164]={'FRクエスト171','依頼者：\n　'},[165]={'FRクエスト172','依頼者：\n　'},[166]={'FRクエスト173','依頼者：\n　'},[167]={'FRクエスト174','依頼者：\n　'},[168]={'FRクエスト175','依頼者：\n　'},[169]={'FRクエスト176','依頼者：\n　'},[170]={'FRクエスト177','依頼者：\n　'},[171]={'FRクエスト178','依頼者：\n　'},[172]={'FRクエスト179','依頼者：\n　'},[173]={'FRクエスト180','依頼者：\n　'},[174]={'FRクエスト181','依頼者：\n　'},[175]={'FRクエスト182','依頼者：\n　'},[176]={'FRクエスト183','依頼者：\n　'},[177]={'FRクエスト184','依頼者：\n　'},[178]={'FRクエスト185','依頼者：\n　'},[179]={'FRクエスト186','依頼者：\n　'},[180]={'FRクエスト187','依頼者：\n　'},[181]={'FRクエスト188','依頼者：\n　'},[182]={'FRクエスト189','依頼者：\n　'},[183]={'FRクエスト190','依頼者：\n　'},[184]={'FRクエスト191','依頼者：\n　'},[185]={'Don\'t Forget the Antidote','Client: Edigey (Sand dune,\n Rabao)\nSummary:\n Edigey wants you to bring him\n some sand scorpion poison so he\n can make an antidote, an\n essential item for the desert\n caravans.\n'},[186]={'The Missing Piece','Client: Alfesar (Near the oasis,\n Rabao)\nSummary:\n The friar Alfesar has asked you to\n find the remaining part of a stone\n tablet that was found in the\n Quicksand Caves that lie beneath\n the Altepa Desert.\n'},[187]={'The Kuftal Tour','Client: Datta (Near the oasis,\n Rabao)\nSummary:\n You have been asked to participate\n in a tour planned by Datta.\n Travel to the cliff inside the\n entrance to the Kuftal Tunnel with\n a party of two or more people of\n level forty or less, then meet\n with Datta\'s partner, Hawk Nose.\n'},[188]={'The Immortal Lu Shang','Client: Irmilant (Near the oasis,\n Rabao)\nSummary:\n Irmilant has said he will repair your\n broken Lu Shang\'s fishing rod.\n Along with the broken fishing rod,\n you must bring him a piece of\n ancient lumber and two light\n crystals.\n'},[189]={'Indomitable Spirit','Client: Irmilant (Near the oasis,\n Rabao)\nSummary:\n Irmilant has asked you to bring the\n two base materials required to craft\n a legendary fishing rod. These\n materials seem to have found their\n way into the bellies of sea creatures\n that still elude the finest fishermen.\n'},[190]={'Fish Favors the Bold','Client: Irmilant (Near the oasis,\n Rabao)\nSummary:\n The exalted fisherman has posed to\n you a challenge. Collect legendary fish\n from the four corners of Vana\'diel.'},[191]={'Chasing Dreams','Client: Zoriboh (Near the oasis,\n Rabao)\nSummary:\n A young cargo hauler named\n Sanctia has suddenly left Rabao,\n and Zoriboh wants you to find her.\n According to Zoriboh, she has\n probably headed for Norg to board\n a ship bound for the Tavnazian\n Marquisate...'},[192]={'The Search for Goldmane','Client: Zoriboh (Near the oasis,\n Rabao)\nSummary:\n How is little Sanctia doing?\n Zoriboh wants you to take her a\n present from her father and see\n that she is keeping out of trouble.'},[193]={'Thanks for All the Fish','Client: Jourdenaux (Near the oasis,\n Rabao)\nSummary:\n Lu Shang\'s fishing rod has a hidden\n power deep inside, which Jordenaux has\n offered to draw forth if he deems you\n worthy--by collecting 60 types of fish\n and fulfilling all Records of Eminence\n objectives in the "Fishing (Tenacity)"\n category.'},[194]={'FRクエスト204','依頼者：\n　'},[195]={'FRクエスト205','依頼者：\n　'},[196]={'FRクエスト206','依頼者：\n　'},[197]={'FRクエスト207','依頼者：\n　'},[198]={'FRクエスト208','依頼者：\n　'},[199]={'FRクエスト209','依頼者：\n　'},[200]={'FRクエスト210','依頼者：\n　'},[201]={'Trial-Size Trial by Wind','Client: Rahi Fohlatti (Near the oasis,\n Rabao)\nSummary:\n The Rhinostery has developed a\n new "mini" tuning fork of wind.\n Ringing it upon the protocrystal\n in Cape Teriggan will open the\n path to a one-on-one battle\n with the beast that awaits inside.\n However, only summoners are\n allowed to take up this challenge.'},[202]={'+Trial by Wind','Client: Agado-Pugado (Near the oasis,\n Rabao)\nSummary:\n Ring the tuning fork of wind upon\n the protocrystal in Cape Teriggan.\n A path will open to the trial that\n awaits.'},[203]={'FRクエスト211','依頼者：\n　'},[204]={'FRクエスト212','依頼者：\n　'},[205]={'FRクエスト213','依頼者：\n　'},[206]={'FRクエスト214','依頼者：\n　'},[207]={'FRクエスト215','依頼者：\n　'},[208]={'FRクエスト216','依頼者：\n　'},[209]={'FRクエスト217','依頼者：\n　'},[210]={'FRクエスト218','依頼者：\n　'},[211]={'FRクエスト219','依頼者：\n　'},[212]={'FRクエスト220','依頼者：\n　'},[213]={'Voidwatch Ops: Border Crossing','Client: Kieran (Storage Area, Norg)\nSummary:\n The Voidwatch has begun conducting\n secret operations outside of\n Jeuno and the three nations.\n Receive briefings from agents in\n Kazham and Rabao, then join the\n fight against the Voidwalkers!'},[214]={'VW Op. #054: Elshimo List','Client: Hildegard (Village Gate,\n Kazham)\nSummary:\n Planar rifts have been reported\n in the Yuhtunga Jungle, Ifrit\'s\n Cauldron, and the Temple of\n Uggalepih. Engage the Voidwalkers\n at each location and obliterate\n them!'},[215]={'VW Op. #101: Detour to Zepwell','Client: Gushing Spring (Oasis, Rabao)\nSummary:\n Planar rifts have been reported\n in the Western Altepa Desert,\n the Kuftal Tunnel, and the Quicksand\n Caves. Engage the Voidwalkers at\n each location and obliterate them!'},[216]={'VW Op. #115: Li\'Telor Variant','Client: Kieran (Storage Area, Norg)\nSummary:\n Planar rifts have been reported\n in the Sanctuary of Zi\'tah,\n the Boyahda Tree, and Ro\'Maeve.\n Engage the Voidwalkers at each\n location and obliterate them!'},[217]={'Skyward Ho, Voidwatcher!','Client: Kieran (Storage Area, Norg)\nSummary:\n Planar rifts have been reported\n in Ru\'Aun Gardens, Ve\'Lugannon\n Palace, and the Shrine of\n Ru\'Avitau. Engage the Voidwalkers\n at each location and obliterate\n them!'}},
  at={name='Aht Urhgan',[0]={'Keeping Notes','Client: Ahkk Jharcham (Port\n Al Zahbi, Aht Urhgan Whitegate)\nSummary:\n Ahkk Jharcham wants you to bring\n her a sheet of parchment and a jar\n of black ink so she can write down\n her secret.'},[1]={'Arts and Crafts','Client: Hadahda (Stoneserpent\n Square, Aht Urhgan Whitegate)\nSummary:\n Hadahda wants you to collect\n pieces of paper with letters\n written on them. You are to\n bring him one each of M, U,\n and T, and two each of A and D.'},[2]={'Olduum','Client: Dkhaaya (Balrahn Way,\n Aht Urhgan Whitegate)\nSummary:\n Dkhaaya wants you to bring him an\n artifact of the Olduum civilization.'},[3]={'Got It All','Client: Tehf Kimasnahya (Balrahn\n Way, Aht Urhgan Whitegate)\nSummary:\n Tehf Kimasnahya wants you to\n get a vial of luminous water\n from Ekhu Pesshyadha.'},[4]={'Get the Picture','Client: Balakaf (Port Ephramad,\n Aht Urhgan Whitegate)\nSummary:\n Take pictures with Balakaf\'s\n "image recorder" at the places\n he specifies.'},[5]={'An Empty Vessel','Client: Waoud (Heretic\'s Alley,\n Aht Urhgan Whitegate)\nSummary:\n There is a rare treasure in the\n "Middle Lands" that Waoud needs\n someone to obtain for him...'},[6]={'Luck of the Draw','Client: Ratihb (Shararat Teahouse,\n Aht Urhgan Whitegate)\nSummary:\n Ratihb wants you to check on\n his son Wasuhd, who has gone\n in search of his older brother.'},[7]={'No Strings Attached','Client: Iruki-Waraki (Way of the\n Devout, Aht Urhgan Whitegate)\nSummary:\n If you want to learn how to\n become a puppetmaster, you must\n bring an automaton to Iruki-Waraki.'},[8]={'+Finding Faults','Client: Hishahma (Way of the\n Devout, Aht Urhgan Whitegate)\nSummary:\n Journey to the lands where\n dangerous monsters reside and\n investigate their weak points.\n According to previous research,\n each type of monster should\n possess two weak points.'},[9]={'Give Peace a Chance','Client: Mishhar (Serpentking Square,\n Aht Urhgan Whitegate)\nSummary:\n Mishhar wants you to find out what\n Isween is doing out in the Wajaom\n Woodlands at night.'},[10]={'+The Art of War','Client: Hishahma (Way of the\n Devout, Aht Urhgan Whitegate)\nSummary:\n Hishahma\'s special forces are\n struggling in their battle against\n certain monsters. You must find\n an effective strategy to defeat\n the enemy.'},[11]={'ATクエスト00','依頼者：\n　'},[12]={'A Taste of Honey','Client: Qutiba (Shararat Teahouse,\n Aht Urhgan Whitegate)\nSummary:\n Qutiba wants you to bring her\n three pots of white honey so she\n can make the famous Near Eastern\n confectionery "irmik helvasi."'},[13]={'Such Sweet Sorrow','Client: Dabhuh (Gladiator\'s Alley,\n Aht Urhgan Whitegate)\nSummary:\n Dabhuh wants you to bring him\n a Merrow scale.'},[14]={'Fear of the Dark II','Client: Suldiran (Galeserpent Square,\n Al Zahbi)\nSummary:\n Bring Suldiran two imp wings.'},[15]={'Cook-a-roon?','Client: Ququroon (North of the\n Weapon Shop, Nashmau)\nSummary:\n Ququroon wants to practice cooking\n so he can open a restaurant one day.\n Help him out by bringing him the\n ingredients he requires.'},[16]={'The Die Is Cast','Client: Ratihb (Shararat Teahouse,\n Aht Urhgan Whitegate)\nSummary:\n Yadhiwa cheated Balajaha out of\n a large sum of money. Help him\n get back the gold he lost to her\n crafty devices.'},[17]={'Two Horn the Savage','Client: Milazahn (Balrahn Way,\n Aht Urhgan Whitegate)\nSummary:\n The ferocious "Two Horn the\n Savage" has been wreaking havoc\n around the Empire, but nobody\n knows the creature\'s identity or\n its whereabouts. You are to lead\n an investigation into the facts\n surrounding this frightening beast.'},[18]={'Totoroon\'s Treasure Hunt','Client: Totoroon (Port, Nashmau)\nSummary:\n Totoroon has found a\n "soooper-doooper" treasure.\n He will tell you where it is hidden\n in exchange for something sweet.'},[19]={'What Friends Are For','Client: Tsetseroon (Junk Seller,\n Nashmau)\nSummary:\n Tsetseroon needs a cobalt jellyfish\n and a chunk of tin ore to make his\n special stew.'},[20]={'Rock Bottom','Client: Zurtermor (Mount Zhayolm)\nSummary:\n Zurtermor has dropped his\n precious pickaxe into a crevasse...'},[21]={'Beginnings','Client: Raubahn\n(???, Aht Urhgan Whitegate)\nSummary:\n An unavoidable decision...\n If you would seek even greater\n power, meet with the Immortals\n stationed at the Azouph Isle,\n Dvucca Isle, Mamool Ja, Halvung,\n and Ilrusi staging points.'},[22]={'Omens','Client: Raubahn\n(???, ???)\nSummary:\n The only choice you have left is to\n forge ahead in the quest for power,\n or face your own destruction...\n If ambition still fuels your soul,\n head to the Navukgo Execution\n Chamber and obliterate the\n monstrous flan!'},[23]={'Transformations','Client: Raubahn\n(???, Imperial Ward)\nSummary:\n A juvenile soulflayer has been\n discovered in the Alzadaal Undersea\n Ruins. Make your way to the ruins\n and eliminate this threat.'},[24]={'Equipped for All Occasions','Client: Qultada (Arrapago Reef)\nSummary:\n In order to become an official\n Seagull Phratrie crew member, you\n need a proper weapon. According to\n the crew, you may be able to find\n one in an old cave...'},[25]={'Navigating the Unfriendly Seas','Client: Zweeha (Arrapago Reef)\nSummary:\n The seas around Arrapago Reef\n cannot be navigated without a\n hydrogauge, and it is your job to\n find one. Ships from the Kingdom\n of Ephramad all had one, but that\n was long ago...'},[26]={'Against All Odds','Client: Zweeha (Shararat Teahouse,\n Aht Urhgan Whitegate)\nSummary:\n Qultada has been captured by the\n Empire. Head to Arrapago with the\n Seagull Phratrie crew and save\n your captain!'},[27]={'The Wayward Automaton','Client: Iruki-Waraki (Way of the\n Devout, Aht Urhgan Whitegate)\nSummary:\n Iruki-Waraki\'s automaton has been\n stolen! Go to Nashmau and see if\n you can find some information on\n its whereabouts.'},[28]={'Operation Teatime','Client: Iruki-Waraki (Way of the\n Devout, Aht Urhgan Whitegate)\nSummary:\n Iruki-Waraki wants you to\n cooperate with his plan to take\n back his automaton.'},[29]={'Puppetmaster Blues','Client: Iruki-Waraki (Way of the\n Devout, Aht Urhgan Whitegate)\nSummary:\n Iruki-Waraki has lost all faith in\n himself. Meet with his teacher and\n try to find a way to get Elisabeth\n to come around.'},[30]={'Moment of Truth','Client: Mishhar (Serpentking Square,\n Aht Urhgan Whitegate)\nSummary:\n Mishhar wants you to explain to\n Minfram the facts about what\n happened between Isween and the\n beastmen.'},[31]={'Three Men and a Closet','Client: Kubhe Ijyuhla (Serpentking\n Square, Aht Urhgan Whitegate)\nSummary:\n The three volunteer soldiers Foudeel,\n Wahboud, and Bashraf have been\n acting strange lately. To help Kubhe\n find out what is really going on, you\n first must travel to the Wajaom\n Woodlands and train with Foudeel.'},[32]={'Five Seconds of Fame','Client: Balakaf (Port Ephramad,\n Aht Urhgan Whitegate)\nSummary:\n You are to scour the city for\n various intriguing events and\n record them on Balakaf\'s new\n photopticator.'},[33]={'ATクエスト00','依頼者：\n　'},[34]={'ATクエスト00','依頼者：\n　'},[35]={'ATクエスト00','依頼者：\n　'},[36]={'ATクエスト00','依頼者：\n　'},[37]={'ATクエスト00','依頼者：\n　'},[38]={'ATクエスト00','依頼者：\n　'},[39]={'ATクエスト00','依頼者：\n　'},[40]={'The Beast Within','Client: Raubahn\n(???, ???)\nSummary:\n No questions. No refusals.\n Obtain a "blue mage\'s testimony"\n and present yourself at the\n Imperial Whitegate.'},[41]={'Breaking the Bonds of Fate','Client: Qultada (Arrapago Reef)\nSummary:\n Qultada is waiting on Arrapago\n Reef for you to bring him a\n corsair\'s testimony. The reasons\n for his request are shrouded in\n mystery...'},[42]={'ATクエスト00','依頼者：\n　'},[43]={'Saga of the Skyserpent','Client: Biyaada (Shararat Teahouse,\n Aht Urhgan Whitegate)\nSummary:\n Venture into Halvung to search for\n the Skyserpent General\'s stolen\n keepsake.'},[44]={'Ode to the Serpents','Client: Fari-Wari (Shararat\n Teahouse, Aht Urhgan Whitegate)\nSummary:\n Fari-Wari is working on the sequel\n to his masterpiece and has asked\n you to interview the adjutants to\n the Serpents Generals in Al Zahbi.'},[45]={'When the Bow Breaks','Client: Gaweesh (Al Zahbi)\nSummary:\n Find the Galeserpent General in the\n Wajaom Woodlands, where she\n spends her spare time gazing on\n some object from her past...'},[46]={'Fist of the People','Client: Talhaal (Al Zahbi)\nSummary:\n Talhaal has agreed to tell you\n about the Stoneserpent General\'s\n deeds. Wait for him at the Shararat\n Teahouse.'},[47]={'Soothing Waters','Client: Fari-Wari (Shararat\n Teahouse, Aht Urhgan Whitegate)\nSummary:\n Fari-Wari is under pressure from\n moneylenders to repay his loan,\n but it seems he\'s found a new\n theme for his next bestseller...'},[48]={'Embers of His Past','Client: Fari-Wari (Shararat Teahouse,\n Aht Urhgan Whitegate)\nSummary:\n Fari-Wari is seeking inspiration for\n his latest masterpiece, but things get\n messy when his would-be protagonist\n is put on trial for a bizarre crime...'},[49]={'ATクエスト00','依頼者：\n　'},[50]={'ATクエスト00','依頼者：\n　'},[51]={'ATクエスト00','依頼者：\n　'},[52]={'ATクエスト00','依頼者：\n　'},[53]={'ATクエスト00','依頼者：\n　'},[54]={'ATクエスト00','依頼者：\n　'},[55]={'ATクエスト00','依頼者：\n　'},[56]={'ATクエスト00','依頼者：\n　'},[57]={'ATクエスト00','依頼者：\n　'},[58]={'ATクエスト00','依頼者：\n　'},[59]={'ATクエスト00','依頼者：\n　'},[60]={'The Prankster','Client: Ahaadah (Philosopher\'s Alley,\n Aht Urhgan Whitegate)\nSummary:\n Alcander and Ahaadah want you\n to help Tinga-Matonga become a\n respectable citizen.'},[61]={'Delivering the Goods','Client: Fochacha (Serpentking\n Square, Aht Urhgan Whitegate)\nSummary:\n Fochacha\'s cooking supplies have\n been stolen! Her son has gone to\n retrieve them, but how is he faring?\n You might try looking for him at\n the Shararat Teahouse, where\n gourmet aficionados are known to\n reside...'},[62]={'Vanishing Act','Client: Ulamaal, Qutiba (Shararat\n Teahouse, Aht Urhgan Whitegate)\nSummary:\n The leader of the "Epicureans" has\n been missing ever since saying he\n was going to the port.\n Where could he have gone...?'},[63]={'Striking a Balance','Client: Wazyih (Stoneserpent Square,\n Aht Urhgan Whitegate)\nSummary:\n Wazyih\'s failure to deliver a\n package has resulted in a rift\n between him and Saliyahf.\n The self-proclaimed "Defenders\n of Aht Urhgan" need your help!'},[64]={'Not Meant to Be','Client: Wadayra (Northern Gate,\n Nashmau)\nSummary:\n Wadayra wants you to look for her\n precious son, Ahgdeen, who has run\n away from home. He must be sorely\n missing his dear mother by now.\n Apparently he was last sighted in\n the northern part of Caedarva Mire.'},[65]={'Led Astray','Client: Galiwao (Way of the\n Devout, Aht Urhgan Whitegate)\nSummary:\n Help Galiwao and his colleagues\n locate their employer before their\n worst fears are realized.'},[66]={'Rat Race','Client: Kakkaroon (Port, Nashmau)\nSummary:\n Young Rapipi adores the Qiqirn\n and wants to make friends with\n all the furry beastmen in Nashmau.\n However, therein lies the dilemma\n for poor Kakkaroon, who is deathly\n afraid of children. Perhaps "Nadee"\n can provide some advice on how to\n bring the two together.'},[67]={'The Prince and the Hopper','Client: Maudaal (Victory Arch,\n Aht Urhgan Whitegate)\nSummary:\n You have been hired by Professor\n Clavauert B Chanoix to accompany\n him and his guinea toad, Salwa-\n Molwa, to Mamook where they will\n conduct research on the elusive\n Poroggo.'},[68]={'VW Op. #050: Aht Urhgan Assault','Client: Camille (Postern,\n Wajaom Woodlands)\nSummary:\n The Empire may refuse to recognize\n their existence, but planar rifts have\n indeed appeared in Arrapago Reef,\n Mount Zhayolm, Mamook, and\n Caedarva Mire. Eradicate each of the\n Voidwalker threats to save the realm!'},[69]={'VW Op. #068: Subterranean Skirmish','Client: Camille (Postern,\n Wajaom Woodlands)\nSummary:\n The Immortals have hinted at\n planar rift appearances in\n Aydeewa Subterrane. Venture\n underground to bore through this\n latest Voidwalker threat!'},[70]={'An Imperial Heist','Client: Ovjang\n (Salaheem\'s Sentinels,\n Aht Urhgan Whitegate)\nSummary:\n Locate and retrieve the ancient\n weapons stolen from the Imperial\n Treasury. Quartz transmitters planted\n on the weapons indicate that they lay\n somewhere in the deepest ruins of\n Nyzul Isle...'},[71]={'Duties, Tasks, and Deeds','Client: Paparoon\n (Nashmau)\nSummary:\n Honorary officer Paparoon has been\n brought on to see that you carry out\n your imperial orders. Alexandrite,\n Wyrmseeker Areuhat, assault memoires,\n holy relics... A multitude of paths lay\n open before you.'},[72]={'Forging a New Myth','Client: Nashmeira\n (Throne Room, Imperial Ward)\nSummary:\n Driven by ambition, yet still\n haunted by the dismebodied whispers\n that come at the weapon\'s touch, you\n have been ordered by Nashmeira in\n the name of the Empire to harness\n the seemingly unconquerable power\n of the mythic weapons.'},[73]={'Coming Full Circle','Client: Balrahn\n (Nyzul Isle)\nSummary:\n "You must call upon the cemetery\nin Caedarva Mire while bearing your\nmythic weapon. Seek out the great\npowers at rest there..."\n But exactly to what end does the\ngreat Balrahn intend to send you...?'},[74]={'Waking the Colossus','Client: Nashmeira\n (Throne Room, Imperial Ward)\nSummary:\n Curious readings from the chamber\n where the iron colossus sleeps have\n Imperial researchers ill at ease. At Her\n Majesty\'s behest, seek the support of\n the four nations for a plan to repair\n the colossus and free the Empire from\n its shadow once and for all.'},[75]={'+Divine Interference','Client: Nashmeira\n (Throne Room, Imperial Ward)\nSummary:\n The avatar of Alexander once again\n threatens to force its way through the\n spatial distortion in Nyzul. Procure a\n replacement power source from the\n Moblin Megomak and reactivate the\n colossus to send the extradimensional\n intruder back whence it came.'},[76]={'The Rider Cometh','Client: Nashmeira\n (Throne Room, Imperial Ward)\nSummary:\n Ominous rumors circulating among the\n mercenary ranks speak of Dark Rider\n sightings deep within the Hazhalm\n Testing Grounds. Could this\n occurrence bear any connection to\n the unsealed spatial distortion? It\n falls to you to investigate.'},[77]={'+Unwavering Resolve','Client: Nashmeira\n (Throne Room, Imperial Ward)\nSummary:\n Ghatsad aims to seal the distortion\n that is the Dark Rider\'s portal into\n this world. You must procure another\n key and return to Hazhalm to collect\n the data he seeks. Meanwhile, Ovjang\n and Mnejing would ask of you a favor\n of their own...'},[78]={'+A Stygian Pact','Client: Nashmeira\n (Throne Room, Imperial Ward)\nSummary:\n To reclaim the soul of Prince Luzaf,\n you have have entered an unholy\n covenant with the Dark Divinity. What\n trials await you as Odin\'s knight?\n Shrink not from the shadows, and be\n strong in your convictions, that you\n might emerge unscathed!'},[79]={'ATクエスト00','依頼者：\n　'},[80]={'ATクエスト00','依頼者：\n　'},[81]={'ATクエスト00','依頼者：\n　'},[82]={'ATクエスト00','依頼者：\n　'},[83]={'ATクエスト00','依頼者：\n　'},[84]={'ATクエスト00','依頼者：\n　'},[85]={'ATクエスト00','依頼者：\n　'},[86]={'ATクエスト00','依頼者：\n　'},[87]={'ATクエスト00','依頼者：\n　'},[88]={'ATクエスト00','依頼者：\n　'},[89]={'ATクエスト00','依頼者：\n　'},[90]={'Promotion: Private First Class','Client: Naja Salaheem (Salaheem\'s\n Sentinels, Aht Urhgan Whitegate)\nSummary:\n President Naja wants you to bring\n her an imp wing.'},[91]={'Promotion: Superior Private','Client: Naja Salaheem (Salaheem\'s\n Sentinels, Aht Urhgan Whitegate)\nSummary:\n Your task is to find some hard\n evidence that the "Dark Rider" has\n truly appeared out of legend and is\n terrorizing the Empire.'},[92]={'Promotion: Lance Corporal','Client: Naja Salaheem (Salaheem\'s\n Sentinels, Aht Urhgan Whitegate)\nSummary:\n Falzum, your fellow mercenary, has\n been given the task of creating a\n batch of mythralline liquid. As his\n superior, it is your job to teach\n him how a mercenary carries out\n his duty.'},[93]={'Promotion: Corporal','Client: Naja Salaheem (Salaheem\'s\n Sentinels, Aht Urhgan Whitegate)\nSummary:\n To track the movements of the\n Dark Rider, you have been given a\n quartz transmitter to place in his\n warhorse\'s hoofprints.'},[94]={'Promotion: Sergeant','Client: Naja Salaheem (Salaheem\'s\n Sentinels)\nSummary:\n The perfumier Liliroon has come to\n Salaheem\'s Sentinels in search of\n help, believing it to be a famous\n detective agency. President Naja\n wants you to help collect her\n lucrative reward.'},[95]={'Promotion: Sergeant Major','Client: Naja Salaheem (Salaheem\'s\n Sentinels)\nSummary:\n You must fulfill your duty\n as a sergeant by training up\n your subordinates into proper\n mercenaries.'},[96]={'Promotion: Chief Sergeant','Client: Abquhbah (Salaheem\'s\n Sentinels)\nSummary:\n Abquhbah has asked you to visit the\n weapon shop in his stead. His heavy\n sighs have you slightly worried...'},[97]={'Promotion: Second Lieutenant','Client: Naja Salaheem (Salaheem\'s\n Sentinels)\nSummary:\n To earn your position in the upper\n ranks of Salaheem\'s Sentinels, you\n have enrolled in the Salaheem\n Officer Academy.\n Be the best that you can be!'},[98]={'Promotion: First Lieutenant','Client: Naja Salaheem (Salaheem\'s\n Sentinels)\nSummary:\n Your final term at the Salaheem\n Officer Academy has begun.\n Will all the cadets survive until\n graduation...?'},[99]={'Promotion: Captain','Client: Abquhbah (Salaheem\'s\n Sentinels)\nSummary:\n Give President Naja a massage\n using the technique Abquhbah has\n shown you. Who knows? It may\n just tip the scales in your favor...'},[100]={'ATクエスト00','依頼者：\n　'},[101]={'+Scouting the Ashu Talif','Client: Halshaob (Port, Nashmau)\nSummary:\n According to a report, the pirate\n ship Ashu Talif\'s crew is armed and\n dangerous. The Maelstrom Company\n is to board the ship and judge the\n severity of the threat, and if\n possible, eliminate it.'},[102]={'+Royal Painter Escort','Client: Halshaob (Port, Nashmau)\nSummary:\n The Empress has sent her royal\n painter Faluuya to the Ashu Talif\n to sketch diagrams of the ship.\n The Maelstrom Company is to\n protect her as she completes her\n work.'},[103]={'+Targeting the Captain','Client: Halshaob (Port, Nashmau)\nSummary:\n The Imperial Army has decided that\n the only way to rid the Empire of\n the Ashu Talif is to dispose of its\n captain. The Maelstrom Company is\n to board the Ashu Talif with a small\n force and end the threat for good.'},[104]={'ATクエスト00','依頼者：\n　'},[105]={'ATクエスト00','依頼者：\n　'},[106]={'ATクエスト00','依頼者：\n　'},[107]={'ATクエスト00','依頼者：\n　'},[108]={'ATクエスト00','依頼者：\n　'},[109]={'ATクエスト00','依頼者：\n　'},[110]={'ATクエスト00','依頼者：\n　'},[111]={'ATクエスト00','依頼者：\n　'},[112]={'ATクエスト00','依頼者：\n　'},[113]={'ATクエスト00','依頼者：\n　'},[114]={'ATクエスト00','依頼者：\n　'},[115]={'ATクエスト00','依頼者：\n　'},[116]={'ATクエスト00','依頼者：\n　'},[117]={'ATクエスト00','依頼者：\n　'},[118]={'ATクエスト00','依頼者：\n　'},[119]={'ATクエスト00','依頼者：\n　'},[120]={'ATクエスト00','依頼者：\n　'},[121]={'ATクエスト00','依頼者：\n　'},[122]={'ATクエスト00','依頼者：\n　'},[123]={'ATクエスト00','依頼者：\n　'},[124]={'ATクエスト00','依頼者：\n　'},[125]={'ATクエスト00','依頼者：\n　'},[126]={'ATクエスト00','依頼者：\n　'},[127]={'ATクエスト00','依頼者：\n　'}},
  wog={name='Crystal War',[0]={'Lost in Translocation','Client: Thorben (Entrance to\n Eldieme Necropolis, Batallia Downs)\nSummary:\n Thorben has dropped his squad\'s\n map of Grauberg somewhere in the\n Eldieme Necropolis.\n Find the map and return it to him.'},[1]={'Message on the Wind','Client: Romualdo (Cannon Battery\n Batallia Downs)\nSummary:\n Romualdo believes he has heard\n the voice of his deceased father\n in Grauberg. He\'d like to head there\n again to find out for sure, but is\n unable to leave his post...'},[2]={'The Weekly Adventurer','Client: Naiko-Paneiko (Crawlers\'\n Nest)\nSummary:\n Battlefield journalist Naiko-Paneiko\n has received intriguing leads\n concerning the appearance of a\n monster in the Rolanberry Fields.\n Go nab the scoop!'},[3]={'Healing Herbs','Client: Maju-Naju \n (Rhinostery, Windurst Waters)\nSummary:\n Maju-Naju\'s research has ground to\n a halt. He needs research materials\n that are hard to find in this day\n and age...'},[4]={'Redeeming Rocks','Client: Kocco Ehllek (Windurst\n Waters)\nSummary:\n It seems young Kocco is always\n upsetting her mother with her\n mischievous pranks...'},[5]={'The Dawn of Delectability','Client: Ranpi-Monpi (Windurst\n Waters)\nSummary:\n The outbreak of war has\n done away with any semblance of\n motivation aspiring chef\n Ranpi-Monpi may have had. If only\n he could experience the unique and\n extraordinarily new delectable dish\n that he dreams of...'},[6]={'A Little Knowledge','Client: Erlene & Ulbrecht (Eldieme\n Necropolis, Batallia Downs)\nSummary:\n You have been given the chance\n to study the grimoire used by the\n famous Schultz School of Martial\n Theory.\n Your first task is to bring Erlene\n twelve sheets of vellum.'},[7]={'The Fighting Fourth','Client: Adelbrecht (Freidrich\n Battery, Bastok Markets)\nSummary:\n Deliver rations to the Eduard\n Watchtower in North Gustaberg.'},[8]={'Snake on the Plains','Client: Miah Riyuh\n (Cobra Command, Windurst Waters)\nSummary:\n Take a jar of Zonpa-Zippa\'s\n All-Purpose Putty to the stone\n towers in West Sarutabaruta, and\n repair any cracks you find in the\n doors.'},[9]={'Steamed Rams','Client: Mainchelite (Victory Square,\n Southern San d\'Oria)\nSummary:\n Recent sightings of an unidentified\n flying object have the Royal\n Knights perplexed. Venture out into\n East Ronfaure and collect three\n pieces of evidence that may assist\n the Kingdom in its investigation.'},[10]={'Seeing Spots','Client: Wyatt (Lion Square,\n Southern San d\'Oria)\nSummary:\n To assist in the war effort, or so he\n claims, Wyatt requires a number of\n ladybug wings to turn out some\n new armor. Gather some and bring\n them back to him for a reward.'},[11]={'The Flipside of Things','Client: Rarcasmeault (Garlaige\n Citadel)\nSummary:\n Rarcasmeault has mistakenly placed\n a firepower case in the Firesand\n Storeroom. Retrieve it and bring it\n back to him.'},[12]={'Better Part of Valor','Client: Wolfram (North Gustaberg,\n Bastok Markets Gate)\nSummary:\n Deliver the clump of animal hair to\n a man named Engelhart.'},[13]={'Fires of Discontent','Client: Engelhart (Harmodios\'s Music\n Shop, Bastok Markets)\nSummary:\n Chairman Pale Eagle is planning to\n fan the growing fire of Galkan\n anger into a full-scale uprising.\n Gather as much information you\n can.'},[14]={'Hammering Hearts','Client: Scarred Shark (Portside,\n Bastok Markets)\nSummary:\n A new type of Quadav armor has\n been causing tension in the\n military. Ghemp wants a heavy\n Quadav chestplate and heavy\n Quadav backplate for analysis.\n Obtain and deliver the items to\n Scarred Shark for a reward.'},[15]={'Gifts of the Griffon','Client: Excenmille (Watchdog Alley,\n Southern San d\'Oria)\nSummary:\n The Young Griffons have made good\n luck charms for their elders.\n Deliver the charms as your first\n duty to the order.'},[16]={'Claws of the Griffon','Client: Altennia (Watchdog Alley,\n Southern San d\'Oria)\nSummary:\n Altennia has asked you to watch\n over the Young Griffons as they\n devise a reckless plan to eliminate\n the Orcish threat...'},[17]={'The Tigress Stirs','Client: Dhea Prandoleh\n (Cobra Command, Windurst Waters)\nSummary:\n Volunteer mercenaries have arrived\n from Olzhirya just as Ajido-Marujido\n delivers news of a possible attack\n by an unseen breed of Yagudo.\n Bring Ajido the starfruit he buried\n somewhere in West Sarutabaruta.'},[18]={'The Tigress Strikes','Client: Dhea Prandoleh\n (Cobra Command, Windurst Waters)\nSummary:\n The Mithra Mercenaries have set\n out towards Fort Karugo-Narugo to\n hunt down the Yagudo. You find\n yourself headed to the same\n destination in search of the\n impetuous young Ajido-Marujido...'},[19]={'Light in the Darkness','Client: Gentle Tiger (Entrance to \n Metalworks, Bastok Markets)\nSummary:\n Gentle Tiger has been tirelessly\n watching the entrance to the\n Metalworks.\n How did Pagdako manage to sneak\n past him...?'},[20]={'Burden of Suspicion','Client: Gentle Tiger (Entrance to \n Metalworks, Bastok Markets)\nSummary:\n It appears Senator Werner had a\n secret mercenary force in his employ.\n What other clandestine plans will be\n uncovered as the investigation\n continues...?'},[21]={'Evil at the Inlet','Client: Rodeupansat\n (Crawlers\' Nest)\nSummary:\n Take Rodeupansat\'s evil warding\n seal and attach it to the\n southwestern tower at Vunkerl\n Inlet in order to cleanse the\n area of evil.'},[22]={'The Fumbling Friar','Client: Fondactiont\n (Garlaige Citadel)\nSummary:\n Fondactiont wants you to find and\n bring back an important package\n that he "dropped" into the\n river in Grauberg.'},[23]={'Requiem for the Departed','Client: Heptachiond\n (The Eldieme Necropolis)\nSummary:\n Heptachiond is running low on the\n incense he lights in prayer as an\n offering to the departed.\n Apparently, the incense is made\n by a friend who is now at Fort\n Karugo-Narugo.'},[24]={'Boy and the Beast','Client: Excenmille\n (Vunkerl Inlet)\nSummary:\n Klythios the Gigas has hurt his\n leg during an epic fish-off with\n Excenmille. Make haste and go\n gather the correct healing herb\n to treat the injury.'},[25]={'Wrath of the Griffon','Client: Rahal (Watchdog Alley,\n Southern San d\'Oria)\nSummary:\n Squire Altennia has been captured\n by Orcs, and is being held at\n their encampment in southern\n Jugner Forest. Rescue her before\n it\'s too late!'},[26]={'The Lost Book','Client: Yoran-Oran\n (Rhinostery, Windurst Waters)\nSummary:\n A book that Yoran-Oran borrowed\n from the Library of Magic was\n supposedly stolen and taken to\n Giddeus by the Yagudo.'},[27]={'Knot Quite There','Client: Romaa Mihgo\n (Aurastery, Windurst Waters)\nSummary:\n Koru-Moru has set off to Jeuno\n with an inexperienced Mithran\n escort.\n Romaa wants you to make sure\n they arrive safely.'},[28]={'A Manifest Problem','Client: Romaa Mihgo\n (Fort Karugo-Narugo)\nSummary:\n After deciphering the Yagudo\n message, you return to Fort\n Karugo-Narugo to find the\n Tigresses missing.\n Fetch them back from Castle\n Oztroja before it\'s too late...'},[29]={'Beans Ahoy!','Client: Thierride (Pikeman\'s Way,\n Southern San d\'Oria)\nSummary:\n Grounded fisherman Thierride is\n in search of a seasoning that\n will allow him to make the most\n mouthwatering bean dish in\n Vana\'diel.'},[30]={'Beast from the East','Client: Nichais (Lion Square,\n Southern San d\'Oria)\nSummary:\n The task of ascertaining what\n truths or falsehoods might lie behind\n the legend of the so-called Mountain\'s\n Eye has fallen to you. At the behest\n of studious Nichais, make haste to the\n wilds of Grauberg and find what\n secrets may await...'},[31]={'The Swarm','Summary:\n A vermin infestation of unprecedented\n scale has broken out within the mines,\n severely disrupting mining operations\n and causing considerable financial\n loss to the industry. The Silvermines\n Pest Control Committee is urgently\n recruiting dauntless individuals to\n aid in their extermination. Items\n found within the premises can be\n utilized at your discretion.'},[32]={'On Sabbatical','Client: Erlene & Ulbrecht (Eldieme\n Necropolis, Batallia Downs)\nSummary:\n Prof. Schultz, founder of the seminal\n Schultz School of Martial Theory, has\n vanished. Set out and find the missing\n professor to set Erlene\'s mind at ease,\n and to deliver Ulbrecht\'s message.'},[33]={'Downward Helix','Client: Erlene (Eldieme Necropolis,\n Batallia Downs)\nSummary:\n Magicians in the service of the Allied\n Forces have been disappearing with\n unsettling regularity. To solve the\n mystery of their whereabouts, first\n journey to San d\'Oria to participate in\n the emergency council being held\n there.'},[34]={'Seeing Blood-red','Client: Erlene (Eldieme Necropolis,\n Batallia Downs)\nSummary:\n Ulbrecht\'s maniacal machinations have\n been made clear, and only one person\n holds the key to tracking him down.\n Find Professor Schultz!'},[35]={'Storm on the Horizon','Client: Klara (Entrance to \n Metalworks, Bastok Markets)\nSummary:\n Senator Karst has left\n unescorted for a meeting with\n Chairman Pale Eagle. You are to\n accompany Mythril Musketeer\n Volker to the rendezvous point\n and bear witness to the exchange\n between the two leaders.'},[36]={'Fire in the Hole','Client: Klara (Entrance to \n Metalworks, Bastok Markets)\nSummary:\n Assist the Mythril Musketeers in\n their operation to destroy the\n siege turrets hidden inside the\n Ruhotz Silvermines.'},[37]={'Perils of the Griffon','Client: Rahal (Watchdog Alley,\n Southern San d\'Oria)\nSummary:\n As if the threat of disbandment was\n not enough, the Young Griffons must\n also fend off a determined Captain\n Rongelouts from confiscating their\n Orcish warmachine. Assist them in\n the desperate defense of their\n base!'},[38]={'In a Haze of Glory','Client: Diordinne\n (Garlaige Citadel)\nSummary:\n Despite heightened security, the\n Garlaige Citadel has been infiltrated\n by an unseen enemy who is emitting\n poisonous gas with brutal results.\n Amidst the confusion, zealous new\n captain, Rahal, has ventured off\n on his own. Find him and ensure he\n does not come to harm.'},[39]={'When One Man Is Not Enough','Client: Romaa Mihgo\n (Cobra Command, Windurst Waters)\nSummary:\n The Mithran mercenary majors are\n feuding over exclusive rights to\n Lehko Habhoka who is now presumed\n to be hiding out in Sarutabaruta.\n Find and bring back the heartthrob\n before things get out of hand.'},[40]={'A Feast for Gnats','Client: Robel-Akbel\n (Windurst Waters)\nSummary:\n The Cobra Unit and the newly\n arrived Cheetah Volunteers have\n received orders to conduct a\n joint diversionary operation in\n Sauromugue Champaign. Participants\n are to convene on-location.'},[41]={'Say It with a Handbag','Client: Hampu-Kampu\n (Windurst Waters)\nSummary:\n Kipopo has vanished with the\n handcrafted handbag her father,\n Hampu-Kampu, made for a certain\n special someone. Locate Kipopo\n and ask her to return the handbag\n to her distraught father.'},[42]={'Quelling the Storm','Client: Klara (Entrance to \n Metalworks, Bastok Markets)\nSummary:\n The notorious assassin Darksteel\n Hurricane has returned in full force\n to wreak havoc on the embattled\n Republic of Bastok. Assist the\n Mythril Musketeers to locate and\n apprehend the blood-thirsty criminal\n before more lives are lost.'},[43]={'Honor Under Fire','Client: Nicolaus (Entrance to \n Metalworks, Bastok Markets)\nSummary:\n A disconsolate Five Moons has\n departed for the Vunkerl Inlet,\n driven by the desire to attain\n closure over the death of his\n former hero and role model,\n Darksteel Hurricane. Follow your\n Mythril Musketeer comrade and offer\n him support in this time of need.'},[44]={'The Price of Valor','Client: Rahal\n (Jugner Forest)\nSummary:\n Bloodwing Horde military tactician,\n Zogbog, has made bold claims that\n he holds the key to nullifying\n Tavnazia\'s impenetrable defensive\n walls. Help the Swiftwing Griffins\n in their risk-ridden mission to\n uncover the nature of his latest plot.'},[45]={'Bonds That Never Die','Client: Cyranuce\n (Pashhow Marshlands)\nSummary:\n Determined not to let Machegue\'s\n death be in vain, Excenmille has\n disobeyed his father\'s direct orders\n and embarked on a solitary mission\n to slay the behemoth. Follow him to\n Jugner Forest and ensure his safety!'},[46]={'The Long March North','Client: Robel-Akbel\n (Windurst Waters)\nSummary:\n Battered but not beaten, the\n Windurstian army steels itself for a\n grueling march north. The first leg of\n the journey takes you to San d\'Oria,\n where you and your Cobra companions\n will learn what trouble lies brewing\n on the Valdeaunian front.'},[47]={'The Forbidden Path','Client: Lehko Habhoka\n (Windurst Waters)\nSummary:\n In his secret laboratory deep beneath\n Windurst, the genius Karaha-Baruha\n pores over ancient tomes, that he\n might once again summon the Great\n Beast in his nation\'s time of need.\n Deliver what he seeks to Velda-Galda\n by the gate to Windurst Walls!'},[48]={'A Jeweler\'s Lament','Client: Wahid (Gem Shop,\n Bastok Markets)\nSummary:\n His line of supply cut off due to the\n worsening war climate, the pompous\n gem merchant Wahid has entreated\n you to find a sunstone, an\n aquamarine, and a jadeite to\n replenish his inventory.'},[49]={'Beneath the Mask','Client: Nicolaus (Entrance to\n Metalworks, Bastok Markets)\nSummary:\n Disgraced by the actions of the\n traitorous Captain Klara, the Mythril\n Musketeers have been relegated to\n serve in penal detachments. The mood\n turns darker still with the news that\n Zeid has deserted the ranks. Travel to\n Beadeaux to learn what you can from\n his commanding officer.'},[50]={'What Price Loyalty','Client:\n Gentle Tiger (Entrance to Metalworks,\n Bastok Markets)\nSummary:\n Apprehended in Beaucedine after\n deserting his unit, Zeid awaits\n punishment in a dark cell of Benedikt\n Watchtower. Can nothing be done to\n save him from his fate? At his friend\n Gentle Tiger\'s behest, you travel to\n North Gustaberg to offer your aid.'},[51]={'Songbirds in a Snowstorm','Client: Phillieulais S Dieuffon\n (Middle Gate, Southern San d\'Oria)\nSummary:\n An immense beastman force seeks\n to strike at the sparsely manned\n rearguard of the northbound Allied\n expedition. You have been requested\n to join the Carmine Swallows on their\n mission to intercept the encroaching\n enemy host at Beaucedine.'},[52]={'Blood of Heroes','Client: Excenmille\n (Xarcabard)\nSummary:\n Count Aurchiat lies dead, felled in\n an Orcish ambush that has left the\n Cardinal Stags severely weakened\n deep in the heart of enemy\n territory. The key to survival lies\n in a joint operation with the\n Iron Rams...'},[53]={'Sins of the Mothers','Client: Lehko Habhoka\n (Cobra Command, Windurst Waters)\nSummary: A state of emergency has\n been declared as the Shadow Lord\'s\n army marches inexorably toward the\n Federation. In the midst of the\n turmoil, Lehko Habhoka has summoned\n you to Heavens Tower with a task of\n particular import...'},[54]={'Howl from the Heavens','Client: Robel-Akbel (Windurst Waters)\nSummary:\n As the battered Federation forces\n prepare to defend their city from the\n approaching hordes, the inscrutable\n Robel-Akbel schemes in his dark\n chambers. What terrible secrets lie\n behind his mask? Deliver the magicite\n he seeks, and long-sought truths\n just may be revealed...'},[55]={'+Succor to the Sidhe','Client: Callisto\n (Witchfire Glen, Grauberg)\nSummary:\n To save their ancestral home from\n a fate of destruction, the fey folk\n would entreat your aid.'},[56]={'The Young and the Threadless','Client: Ponono\n (Windurst Waters)\nSummary:\n Unable to keep up with the\n overwhelming demand for her custom\n charm bracelets, the Windurstian\n clothcrafter Ponono has entrusted\n you with procuring a fresh supply of\n enchanted thread.'},[57]={'Son and Father','Client: Exoroche (Eastgate,\n Southern San d\'Oria)\nSummary:\n A child stands crying by San d\'Oria\n Eastgate. Find his father for him.'},[58]={'The Truth Lies Hid','Client: Volker (Entrance to Metalworks,\n Bastok Markets)\nSummary:\n Klara Bester, erstwhile captain of the\n Mythril Musketeers turned fugitive,\n has ensconced herself deep in the\n heart of Castle Zvahl. You must\n infiltrate the enemy stronghold with\n your comrades and uncover the truth\n behind your ex-commander\'s treachery.'},[59]={'Bonds of Mythril','Client: Volker (Castle Zvahl Baileys)\nSummary:\n Fighting alongside ghastly demons one\n moment, risking her life to defend you\n the next... What is Captain Klara\'s\n true connection to the armies of\n shadow? Return to the site of your\n confrontation, that long sought-after\n truths may at last be revealed!'},[60]={'Chasing Shadows','Client: Rongelouts N Distaud\n (Auction House, Southern San d\'Oria)\nSummary:\n Disturbing rumors of the late Count\n Aurchiat\'s return from the grave have\n stirred disquiet among the Cardinal\n Stags. Hasten to their Xarcabard\n encampment and uncover the truth\n behind the ominous tidings.'},[61]={'Face of the Future','Client: Bostillette\n (Batallia Downs)\nSummary:\n Your latest encounter with Zogbog\n has led to you being hurled through\n time. No sooner had you awakened\n in present day Vana\'diel than Iron\n Ram Engineer Bostillette appeared\n to entreat your aid. Make your way\n to base camp in the Jugner Forest\n if you would know more.'},[62]={'Manifest Destiny','Client: Romaa Mihgo (Cobra Command,\n Windurst Waters)\nSummary:\n Having successfully turned back the \n Yagudo offensive, Lehko Habhoka\n and the Mithran mercenaries strike for\n Castle Oztroja to finish off their foe.\n The final conflict is nigh--report\n to the mercenary camp in the\n Meriphataud Mountains without delay!'},[63]={'At Journey\'s End','Client: Lehko Habhoka (Inner\n Chambers, Castle Oztroja)\nSummary:\n Lost souls scarred by the past strive\n toward their vision of a brighter\n future... When fates converge, a new\n chapter of history will unfold. Is this\n the end of their journey, or but a new\n beginning? Look to the starry heavens\n and your answer may be found...'},[64]={'Her Memories: Homecoming Queen','Mission Orders:\n Taken by nostalgia upon her return to\n present-day San d\'Oria after a long\n absence, Lilisette decides to take a\n stroll down memory lane.'},[65]={'Her Memories: Old Bean','Mission Orders:\n Rusty Anchor Pub owner Thierride bids\n you deliver his latest bean cuisine to\n old friend and Southern San d\'Oria\n resident Amaura. In return for this\n favor, Thierride promises you his full\n cooperation.'},[66]={'Her Memories: The Faux Pas','Mission Orders:\n The Elvaan gentleman you saw praying\n at the cathedral apparently seeks\n atonement for his callous treatment\n of a "red-haired maiden."\n Could there be a connection between\n him and Lilisette? The friar informs\n you that the man might be found at\n Laborman\'s Way.'},[67]={'Her Memories: Grave Resolve','Mission Orders:\n Despite no longer having memories of\n Lilisette, Halver\'s words spoken from\n his subconscious suggest that not all\n is lost. Could the Larzos of your\n reality possess knowledge that would\n aid your cause? Make haste to where\n he and you first met, at Sir Ragelise\'s\n gravestone.'},[68]={'Her Memories: Operation Cupid','Mission Orders:\n Portia and Lilisette have skipped\n dance lessons and appear to be bound\n for Jeuno...but for what purpose?'},[69]={'Her Memories: Carnelian Footfalls','Mission Orders:\n Unbeknownst to you, Lilisette had\n sought admission into the Knights of\n the Iron Ram. Follow her footsteps\n to discover whether her attempt was\n successful.'},[70]={'Her Memories: Azure Footfalls','Mission Orders:\n Unbeknownst to you, Lilisette had\n sought admission into the Seventh\n Cohors. Follow her footsteps to\n discover whether her attempt was\n successful.\n '},[71]={'Her Memories: Verdure Footfalls','Mission Orders:\n Unbeknownst to you, Lilisette had\n sought admission into the Cobra\n Mercenaries. Follow her footsteps\n to discover whether her attempt\n was successful.'},[72]={'Her Memories: Of Malign Maladies','Mission Orders:\n Lilisette had embarked on a\n frenetic journey to find a cure\n for Sir Ragelise\'s affliction.\n Has the passage of time seen\n the discovery of a remedy?'},[73]={'Champion of the Dawn','Client: Cait Sith???\n (Walk of Echoes)\nSummary:\n A familiar, enigmatic voice has asked\n you to travel to Ronfaure, Jugner\n Forest, and Beaucedine Glacier in the\n Shadowreign Era and gather latent\n energies present there.'},[74]={'+The Dawn Also Rises','Client: Cait Sith\n (Walk of Echoes)\nSummary:\n Challenging Cait Sith again requires\n another visit to either Ronfaure,\n Jugner Forest, or Beaucedine Glacier\n in the Shadowreign Era to gather a\n breath of dawn.'},[75]={'A Forbidden Reunion','Client: Cait Sith\n (Walk of Echoes)\nSummary:\n Cait Sith has implored you to find a\n way to help the struggling Lilisette, for\n a cavernous maw has opened to the\n dark future. Go forth and ensure that\n the world does not fall.'},[76]={'WGクエスト76','依頼者：\n　'},[77]={'WGクエスト77','依頼者：\n　'},[78]={'WGクエスト78','依頼者：\n　'},[79]={'WGクエスト79','依頼者：\n　'},[80]={'Guardian of the Void','Clients: Cait Sith, Kupofried\n (Pashhow Marshlands)\nSummary:\n At the behest of this enigmatic duo,\n you have sworn to protect Vana\'diel\n from the Voidwalker menace.\n Seek out comrades in the fight, that\n you might send these interdimensional\n intruders back to the darkness\n whence they came!'},[81]={'Drafted by the Duchy','Mission Orders:\n You have been received an urgent\n call to arms from Voidwatch\n headquarters in Jeuno.\n Report promptly to the palace in\n Ru\'Lude Gardens or the main gate\n in Sauromugue Champaign for a full\n briefing.'},[82]={'Battle on a New Front','Mission Orders:\n You have been cleared to\n participate in the Jeuno region\n Voidwatch operation. Go forth and\n quell the Voidwalker menace!'},[83]={'VW Op. #126: Qufim Incursion','Mission Orders:\n The Voidwalker presence grows ever\n stronger at Qufim Island, Behemoth\'s\n Dominion, and Delkfutt\'s Tower. Lure\n out and eliminate hostiles to secure\n the area.'},[84]={'A Cait Calls','Mission Orders:\n Cait Sith would speak to you about a\n matter of utmost importance. Make\n haste for the Pashhow Marshlands of\n the past and rendezvous with the\n ever-enigmatic feline.'},[85]={'The Truth Is Out There','Mission Orders:\n The existence of another planar rift\n has been confirmed in the Walk of\n Echoes. Could this one hold the\n answers needed to quell the\n Voidwalker menace once and for all?\n Be ever vigilant, soldiers of the\n Voidwatch!'},[86]={'Re-Drafted by the Duchy','Mission Orders:\n Your presence has once again been\n requested at Voidwatch headquarters\n in Jeuno. Report promptly to the\n palace in Ru\'Lude Gardens for further\n orders.'},[87]={'A New Menace','Mission Orders:\n You have been authorized to\n participate in the latest Voidwatch\n effort in the greater three nations\n region. The Voidwalkers grow more\n formidable by the day--be ever\n vigilant!'},[88]={'No Rest for the Weary','Mission Orders:\n No sooner has one threat been\n quelled than another emerges. You\n have been granted a brief respite, but\n cannot help but feel concern at the\n state of the Voidwatch effort in the\n Crystal War era...'},[89]={'A World in Flux','Mission Orders:\n Little to your surprise, the Allied\n Nations of Crystal War-era Vana\'diel\n are also at wit\'s end with the\n Voidwalker menace. Make your way to\n Vunkerl Inlet, Grauberg, and Fort\n Karugo-Narugo and dispatch any\n fiends that may emerge from the rifts.'},[90]={'Between a Rock and Rift','Mission Orders:\n Could it be that the Walk of Echoes\n holds the key to the enigma that is\n the Voidwalker menace? With no word\n from Cait Sith or the mysterious\n moogle Kupofried, you decide to\n head to the Pashhow Marshlands\n rendezvous point to investigate...'},[91]={'A Farewell to Felines','Mission Orders:\n On the verge of unraveling the\n Voidwalker enigma, Kupofried suffered\n a shocking setback...the sudden\n disappearance of his feline cohort.\n What nefarious force whisked Cait\n Sith across the dimensional\n threshold? The plot ever thickens...'},[92]={'Third Tour of Duchy','Mission Orders:\n The Duchy has requested your\n presence yet again. Wherever have\n the Voidwalkers struck this time?\n In any event, make haste to the\n palace in Ru\'Lude Gardens or the\n main gate in Sauromugue Champaign\n for further orders.'},[93]={'Glimmer of Hope','Mission Orders:\n Rumors tell of crystalline stones\n obtainable from the corpses of fallen\n Voidwalkers. Should you happen upon\n any, seek out Kupofried in the\n Pashhow Marshlands for answers.'},[94]={'Brace for the Unknown','Mission Orders:\n The first contact has been made with\n Cait Sith since she disappeared\n through a distortion in the Walk of\n Echoes, but Kupofried\'s tone hints\n that trying times lie ahead. Could the\n truth surrounding these planar rift\n appearances finally come to light!?'},[95]={'Provenance','Mission Orders:\n A place from which all radiance\n once shone brightly forth now dimly\n flickers on the brink of existence...\n It is here that the source of\n Vana\'diel\'s suffering dwells, say\n the now multifarious caits.'},[96]={'Crystal Guardian','Mission Orders:\n You have discovered that Vana\'diel\'s\n plight can be traced back to a being\n that guards the fabled stone oft\n mentioned in songs of yore. Now all\n that remains is to lay it to rest.'},[97]={'Endings and Beginnings','Mission Orders:\n As the caits tell it, Provenance is not\n the destination, but yet another point\n of departure. While the proverbial\n book may have been shut on this tale,\n it also signals the start of a new one.'},[98]={'Ad Infinitum','Mission Orders:\n Far from being the center of\n destruction, Provenance is the source\n from which worlds of possibility shine\n forth. For those who have survived\n their trials in this ancestral land, the\n true adventure has only just begun.'},[99]={'WGクエスト99','依頼者：\n　'},[100]={'WGクエスト105','依頼者：\n　'},[101]={'WGクエスト105','依頼者：\n　'},[102]={'WGクエスト105','依頼者：\n　'},[103]={'WGクエスト105','依頼者：\n　'},[104]={'WGクエスト105','依頼者：\n　'},[105]={'WGクエスト105','依頼者：\n　'},[106]={'WGクエスト106','依頼者：\n　'},[107]={'WGクエスト107','依頼者：\n　'},[108]={'WGクエスト108','依頼者：\n　'},[109]={'WGクエスト109','依頼者：\n　'},[110]={'WGクエスト110','依頼者：\n　'},[111]={'WGクエスト111','依頼者：\n　'},[112]={'WGクエスト112','依頼者：\n　'},[113]={'WGクエスト113','依頼者：\n　'},[114]={'WGクエスト114','依頼者：\n　'},[115]={'WGクエスト115','依頼者：\n　'},[116]={'WGクエスト116','依頼者：\n　'},[117]={'WGクエスト117','依頼者：\n　'},[118]={'WGクエスト118','依頼者：\n　'},[119]={'WGクエスト119','依頼者：\n　'},[120]={'WGクエスト120','依頼者：\n　'},[121]={'WGクエスト121','依頼者：\n　'},[122]={'WGクエスト122','依頼者：\n　'},[123]={'WGクエスト123','依頼者：\n　'},[124]={'WGクエスト124','依頼者：\n　'},[125]={'WGクエスト125','依頼者：\n　'},[126]={'WGクエスト126','依頼者：\n　'},[127]={'WGクエスト127','依頼者：\n　'}},
  aby={name='Abyssea',[0]={'Catering Capers','Client: Regine (Base Camp,\n Abyssea - La Theine)\nSummary:\n Regine has taken a wound and is\n unable to harvest and deliver the\n requested three plateau chestnuts\n to her sister Rugiette at the central\n encampment. You must complete the\n task in her stead, lest the people\n go without.'},[1]={'Gift of Light','Client: Amaura (Base Camp,\n Abyssea - La Theine)\nSummary:\n Amaura has exhausted her supply\n of the key ingredient required to\n concoct a vital medication. Find\n and bring her the sunbeam fragment\n she needs before the survivors fall\n to illness!'},[2]={'Fear of the Dark III','Client: Secodiand (Base Camp,\n Abyssea - La Theine)\nSummary:\n Fetch three clionid wings.'},[3]={'An Eye for Revenge','Client: Curilla (Base Camp,\n Abyssea - La Theine)\nSummary:\n As retribution, Curilla demands the\n eyeball of Lugarhoo, the vile gnole\n that took her left eye in a vicious\n attack.'},[4]={'Unbreak His Heart','Client: Joulet (Central Encampment,\n Abyssea - La Theine)\nSummary:\n A fishing rod lies broken. You must\n repair and deliver it to Gallijaux at\n the southeastern encampment lest\n the survivors go hungry.'},[5]={'Explosive Endeavors','Client: Fontoumant (Central Encampment,\n Abyssea - La Theine)\nSummary:\n Swarms of monsters have been\n observed emerging from ominous\n crevices in the valley floor.\n Neutralize them with experimental\n anti-Abyssean grenades.'},[6]={'The Angling Armorer','Client: Exoroche (Central Encampment,\n Abyssea - La Theine)\nSummary:\n With no end in sight in the fight\n against the Abyssean hordes, keeping\n soldiers outfitted in battle-worthy\n gear has become a grave concern.\n Could the ponds of La Theine yield\n old but usable equipment?'},[7]={'Water of Life','Client: Miageau (Southeastern\n Encampment, Abyssea - La Theine)\nSummary:\n La Theine\'s water sources have been\n found to be contaminated! Miageau\n has entrusted you with vials of\n purification agent to cleanse each\n of the plateau\'s four ponds.'},[8]={'Out of Touch','Client: Glenne (Southeastern\n Encampment, Abyssea - La Theine)\nSummary:\n Glenne has lost the means to\n contact her husband who is out\n on patrol. Find her husband afield\n and deliver a new linkpearl to him.'},[9]={'Lost Memories','Client: Halver (Southeastern\n Encampment, Abyssea - La Theine)\nSummary:\n In order to brew a medicine that will\n restore Curilla\'s memory, Halver\n requires that you procure two\n lambent scales.'},[10]={'Hope Blooms on the Battlefield','Client: Ayame (Central Command,\n Abyssea - Konschtat)\nSummary:\n The searing ward that serves as the\n last line of defense against the fell\n hordes of the highlands has suffered\n critical damage in an attack. Procure\n repair materials from throughout the\n base and deliver them to the engineer\n Raibaht before the fiends return!'},[11]={'Of Malnourished Martellos','Client: Raibaht (Central Command,\n Abyssea - Konschtat)\nSummary:\n The engineer overseeing martello\n maintenance has tasked you with\n replenishing the energy store of one\n of these curious magical structures.\n Acquire a supply of fuel, deposit it in\n the camp\'s martello, and report back\n when the operation is complete.'},[12]={'Rose on the Heath','Client: Ayame (Central Command,\n Abyssea - Konschtat)\nSummary: The latest incursion of\n Abyssean fiends has left shattered\n linkshells in its wake, severing\n precious lines of communication\n between Captain Ayame and her\n comrades afield. Deliver three\n linkpearls, one each to Captains\n Rashid, Argus, and Helga, before an ill\n fate befalls these brave warriors of\n the resistance!'},[13]={'+Full-of-Himself Alchemist','Client: Julio (Camp Courage,\n Abyssea - Konschtat)\nSummary: Self-serving and abrasive\n though he may be, the alchemist\n Julio\'s estimable potion-brewing skills\n are serving the embattled resistance\n well. Supply him with three purple\n polypores, that he may prepare a new\n batch of his prized product for the\n wounded troops.'},[14]={'+The Walking Wounded','Client: Rashid (Camp Courage,\n Abyssea - Konschtat)\nSummary:\n Five of Captain Rashid\'s best soldiers\n are battling bravely despite grievous\n wounds. Provide each of them with a\n soothing potion to restore them to\n fighting trim.'},[15]={'+Shady Business Redux','Client: Talib (Camp Hope,\n Abyssea - Konschtat)\nSummary:\n The boss of the storehouse traders\n has made you a business proposition\n you couldn\'t refuse. Bring him four\n limule pincers to receive a handsome\n reward.'},[16]={'Addled Mind, Undying Dreams','Client: Silver Owl (Camp Hope,\n Abyssea - Konschtat)\nSummary:\n A guardsman of the former Republic,\n now scarred in mind and body, seeks\n your aid in carrying out a scheme he\n believes key to the survival of the\n resistance. Scour the bleak highlands\n in search of supplies lost during the\n raid of Bastok.'},[17]={'+The Soul of the Matter','Client: Cleades (Camp Vigilance,\n Abyssea - Konschtat)\nSummary:\n A reconnaissance expert has taken\n you under his wing to tutor you in the\n arcane art of soulgauging. Venture\n afield with your Soulgauger SGR-1\n and collect intelligence on the\n notorious fiends aprowl in the vicinity.'},[18]={'Secret Agent Man','Client: Helga (Camp Vigilance,\n Abyssea - Konschtat)\nSummary: Captain Helga fears for the\n safety of fellow officer and covert\n ops specialist Naji, who has not\n returned from his latest mission. The\n loss of this elite operative would be a\n near-fatal blow to the resistance. You\n must track him down with all haste!'},[19]={'+Playing Paparazzi','Client: Naji (Afield,\n Abyssea - Konschtat)\nSummary:\n Naji has grudgingly accepted you as\n his assistant, and entrusted you with\n continuing his work while his wounds\n keep him out of commission. Only\n close range shots of the most\n formidable foes to terrorize the\n highlands will suffice!'},[20]={'His Box, His Beloved','Client: Apururu (Central Encampment,\n Abyssea - Tahrongi)\nSummary:\n Apururu lacks for the starfruit needed\n to construct Cardians to protect her\n embattled countrymen. Travel to the\n northwestern encampment and procure\n one from the supply of the eccentric\n Kopuro-Popuro.'},[21]={'+Weapons, Not Worries','Client: Peshi Yohnts (Western\n Encampment, Abyssea - Tahrongi)\nSummary:\n A down-in-the-dumps artisan,\n seemingly too disheartened to take\n action herself, needs you to retrieve\n supplies for weaponcrafting. The\n hardened bone harvestable in the area\n should serve to raise her spirits.'},[22]={'Cleansing the Canyon','Client: Kupipi (Central Encampment,\n Abyssea - Tahrongi)\nSummary:\n Fearsome fiends prowl the path to\n the western encampment, cutting off\n valuable supply routes and placing the\n survivors\' well-being in peril. At\n Kupipi\'s behest, thin the ranks of\n these foes and return with three\n sanguinets as proof of the deed.'},[23]={'+Savory Salvation','Client: Piketo-Puketo (Western\n Encampment, Abyssea - Tahrongi)\nSummary:\n A culinarian with serious delusions of\n grandeur sees himself as the savior of\n his nation\'s people. Employ the\n fertilizer he\'s given you on a suitable\n tree and bring back anything edible\n that may grow.'},[24]={'Bringing Down the Mountain','Client: Diegai (North of Central\n Encampment, Abyssea - Tahrongi)\nSummary:\n A young Galkan child fears for the\n safety and sanity of his friend and\n guardian. Seek out Baladanzo, who\n claims to have heard voices coming\n from the far side of an impassable\n rockslide...'},[25]={'+A Sterling Specimen','Client: Ohbiru-Dohbiru (Central\n Encampment, Abyssea - Tahrongi)\nSummary:\n Having redirected his efforts to the\n study of the Abyssean ecosystem, a\n researcher from the Rhinostery seeks\n a live sample of a mutant strain of\n mandragora for hands-on examination.\n Speak with Kenapa-Keppa outside and\n make your contribution to science!'},[26]={'+For Love of a Daughter','Client: Baha Mannohl (Northern\n Encampment, Abyssea - Tahrongi)\nSummary:\n A distraught Mithran mother seeks\n your help in finding a cure for her\n fever-stricken daughter. The\n substance she requires is a rare liquid\n said to be exuded by cacti of the\n canyon, but only after dark...'},[27]={'+Sisters in Crime','Client: Cha Lebagta and Bopa Greso\n (Mountain Path, Abyssea - Tahrongi)\nSummary:\n Holding out hope that their\n disreputable band may yet be reunited,\n the two lackeys of the Cat Burglar\n have co-opted you to spread the\n news of their survival. Affix the\n ridiculous posters they\'ve given you\n to the signposts in the canyon.'},[28]={'+When Good Cardians Go Bad','Client: Apururu (Central Encampment,\n Abyssea - Tahrongi)\nSummary:\n Apururu\'s Cardians now guard each\n encampment, but word has it that\n not all of them are functioning\n optimally. Speak to the Cardians at\n each location and report back on any\n glitches you may have detected.'},[29]={'Tangling with Tongue-twisters','Client: Kupipi (Central Encampment,\n Abyssea - Tahrongi)\nSummary:\n Cuelebre. Adze. Minhocao. Chukwa.\n Mictlantecuhtli. No, this isn\'t the\n Federation spelling bee--these are the\n names of the five most formidable\n enemies plaguing the canyon. Slay\n one and bring back proof of your\n triumph.'},[30]={'+A Ward to End All Wards','Client: Belgidiveau (Base Camp,\n Abyssea - Vunkerl)\nSummary: \n The searing ward maintained by the\n brilliant Belgidiveau could not\n possibly be malfunctioning!\n Nevertheless, he requires your aid to\n perform a routine test. Deliver a body\n part of an Abyssean fiend to your\n client, and confirm that his remarkable\n creation is still performing optimally.'},[31]={'+The Boxwatcher\'s Behest','Client: Deraquien (Central Encampment,\n Abyssea - Vunkerl)\nSummary:\n Supplies must be delivered on foot to\n the newly constructed outpost, and\n the sluggardly Deraquien is clearly not\n up to the task. Go in his stead and\n deliver the goods to Captain\n Elmemague.'},[32]={'+His Bridge, His Beloved','Client: Cheupirudaux (Western\n Encampment, Abyssea - Vunkerl)\nSummary:\n The bridges across the inlet are in a\n state of dire disrepair. Go repair\n them, that a sensitive woodworker\'s\n heart may again rest easy.'},[33]={'+Bad Communication','Client: Ferdechiond (Outpost,\n Abyssea - Vunkerl)\nSummary:\n The linkpearls planted afield to gather\n intelligence on the Abyssean hordes\n are not functioning as intended, and\n Ferdechiond is displeased. Investigate\n the situation with all speed!'},[34]={'Family Ties','Client: Teigero-Bangero (Western\n Encampment, Abyssea - Vunkerl)\nSummary:\n A devoted Tarutaru father was\n separated from wife and child in their\n flight from Jeuno. Deliver his letter,\n that this loving family may be\n reunited once more.'},[35]={'Aqua Pura','Client: High Bear (Outpost,\n Abyssea - Vunkerl)\nSummary:\n An enthusiastic researcher is on the\n verge of a discovery that might\n restore potable water to the inlet.\n Retrieve plant samples from the\n vicinity of the ponds, that his labors\n might at long last bear fruit.'},[36]={'+Aqua Puraga','Client: High Bear (Outpost,\n Abyssea - Vunkerl)\nSummary:\n An enthusiastic researcher is on the\n verge of a discovery that might\n restore potable water to the inlet...\n for certain this time! Retrieve plant\n samples from the vicinity of the\n ponds, that his labors might at long\n last bear fruit.'},[37]={'Whither the Whisker','Client: Rahal (Central Encampment,\n Abyssea - Vunkerl)\nSummary:\n A savage pack of fiends terrorizes\n Vunkerl, their whisker of power and\n omniscience confounding the bravest\n attempts of a celebrated San d\'Orian\n hero to secure the safety of his men.\n It falls to you to sever and retrieve\n this Samsonian strand!'},[38]={'+Scattered Shells, Scattered Mind','Client: Aladoverre (Western\n Encampment, Abyssea - Vunkerl)\nSummary:\n The resistance\'s supply of linkshells\n has dwindled to dangerously\n low levels. Retrieve three from the\n field before your addle-minded client\n forgets just what exactly he asked\n you for.'},[39]={'Wayward Wares','Client: Chapi Galepilai (Base Camp,\n Abyssea - Attohwa)\nSummary:\n A shipment of essential supplies\n intended for the Resistance outpost\n has been intercepted. Recover the\n scattered materials and deliver them\n to their intended destination.'},[40]={'+Looking for Lookouts','Client: Colti (Field Encampment,\n Abyssea - Attohwa)\nSummary:\n A regiment of scouts has gone astray\n while on a mission to survey\n Parradamo Tor. Deliver linkpearls and\n emergency rations to the hapless crew\n and restore communication between\n them and their flustered commanding\n officer.'},[41]={'+Flown the Coop','Client: Brutus (Field Encampment,\n Abyssea - Attohwa)\nSummary:\n One of the precious few chocobos\n who survived the flight from Jeuno\n has escaped from the stables. Track\n the bird, lure it out with gysahl\n greens, and capture it to return to\n safe captivity.'},[42]={'+Threadbare Tribulations','Client: Ponono (Field Encampment,\n Abyssea - Attohwa)\nSummary:\n A tailor seeks to raise morale by\n mending the garments of the soldiers,\n but lacks for the thread she needs to\n perform the task. Bring her the three\n amoeban pseudopods that she insists\n will serve as an ideal substitute.'},[43]={'+An Offer You Can\'t Refuse','Client: Garnev (Resistance Outpost,\n Abyssea - Attohwa)\nSummary:\n Your client has a deal for you:\n procure a piece of malachite from one\n of the sturdy pyxides, and he\'ll make\n it worth your while. What does he\n need it for? You\'re better off not\n knowing.'},[44]={'Something in the Air','Client: Yoran-Oran (Base Camp,\n Abyssea - Attohwa)\nSummary:\n The Professor is concerned about\n the air quality, and has hypothesized\n that the source of the pollution\n lies to the west. Go investigate,\n and bring back the tangible evidence\n that your client needs to formulate a\n solution to the crisis.'},[45]={'+An Acrididaen Anodyne','Client: Yoran-Oran (Base Camp,\n Abyssea - Attohwa)\nSummary:\n Yoran-Oran has figured out a method\n that will stop the gasponia from\n giving off its noxious fumes, but he\n requires an elusive insect known as a\n rockhopper to prepare the formula.'},[46]={'Hazy Prospects','Client: Harith (Base Camp,\n Abyssea - Attohwa)\nSummary:\n An astute alchemist has concluded\n that the miasmas seeping up through\n fissures in the ground are contributing\n to the tainted air. Follow the recipe\n he entrusted to you to synthesize the\n counteragent, test it on a miasma,\n then report back with your findings.'},[47]={'For Want of a Pot','Client: Naruru (Base Camp,\n Abyssea - Attohwa)\nSummary:\n You must retrieve Naruru\'s favorite\n stewpot from the airship wreckage so\n that she can cook up a batch of\n piping hot stew from...no, for\n her fellow survivors!'},[48]={'Missing in Action','Client: Iron Eater (Base Camp,\n Abyssea - Misareaux)\nSummary:\n A fierce attack by the Abyssean\n hordes has left some members of\n Iron Eater\'s regiment stranded afield.\n Without the means to regain contact\n nor the manpower to dispatch a search\n party, a lone hero must strike out into\n the wilderness and find them. That\n hero is you.'},[49]={'I Dream of Flowers','Client: Goraow (Second Encampment,\n Abyssea - Misareaux)\nSummary:\n Perpetual pessimist Goraow wishes he\n had flowers to offer to the grave of\n his fallen brethren...'},[50]={'Destiny Odyssey','Client: Goraow (Second Encampment,\n Abyssea - Misareaux)\nSummary:\n There can be no doubt. You are the\n hero destined to end Gukumatz\'s reign\n of terror. Slay this maniacal fiend and\n claim a body part as a trophy, that\n the souls of Goraow\'s fallen brethren\n may know true peace.'},[51]={'+Unidentified Research Object','Client: Yurim (Base Camp,\n Abyssea - Misareaux)\nSummary:\n Yurim requires a certain object in\n order to continue her research on\n Abyssean lifeforms, but is experiencing\n difficulties remembering its name...'},[52]={'+Cookbook of Hope Restoring','Client: Jonette (First Encampment,\n Abyssea - Misareaux)\nSummary:\n Jonette\'s dream is to restore hope to\n the community of survivors by serving\n them an array of scrumptious dishes.\n However, she dropped the cookbook\n needed to fulfill that dream when\n fleeing from monsters. Be a dear and\n find it for her.'},[53]={'+Smoke over the Coast','Client: Hungry Wolf (First Encampment,\n Abyssea - Misareaux)\nSummary:\n Hungry Wolf hungers for meat! Hurry,\n before he transforms into a scrawny\n Hume before your very eyes!'},[54]={'+Soil and Green','Client: Sieglinde (Base Camp,\n Abyssea - Misareaux)\nSummary:\n Sieglinde the alchemist is investigating\n soil quality along the coast, and has\n custom-designed a contraption for\n that purpose. Take the aptly named\n "mineral gauge for dummies," and\n thrust it into a likely spot of earth\n by a tree.'},[55]={'+Dropping the Bomb','Client: Veit (Second Encampment,\n Abyssea - Misareaux)\nSummary:\n Caskets containing gunpowder intended\n for a critical blasting operation have\n been lost in transit. With his soldiers\n apparently a bunch of hopeless\n cravens, Veit requires that you\n retrieve the caskets, which were last\n seen being dumped into the river.'},[56]={'+Wanted: Medical Supplies','Client: Yasuji (First Encampment,\n Abyssea - Misareaux)\nSummary:\n The struggle against the Abyssean\n invaders grows ever fierce. To do\n your part, you must bring Yasuji any\n medical supplies you find within\n sturdy pyxides. For make benefit\n the great resistance effort, let us\n together!'},[57]={'Voices from Beyond','Client: Rukususu (Second Encampment,\n Abyssea - Grauberg)\nSummary:\n Rumors abound of ghosts haunting the\n mountains to the northwest. Rukususu\n requires that you bring irrefutable\n proof to substantiate this disturbing\n tale.'},[58]={'+Benevolence Lost','Client: Rukususu (Second Encampment,\n Abyssea - Grauberg)\nSummary:\n Water contamination has caused the\n pixies of Witchfire Glen to turn\n malevolent. By proliferating certain\n components in the water, however,\n it should be possible to restore the\n noble creatures to their former\n benevolent selves.'},[59]={'+Brugaire\'s Ambition','Client: Brugaire\n (Abyssea - Grauberg)\nSummary:\n At Brugaire\'s behest, you must\n confront and defeat the notorious\n Teekesselchen with the aid of\n prismatic elixir, the newly invented\n wonder draught.'},[60]={'+Chocobo Panic','Client: Kuoh Rhel\n (Abyssea - Grauberg)\nSummary:\n Kuoh Rhel\'s pack chocobo refuses to\n eat anything she feeds it, and grows\n more sickly by the day. Is there\n nothing under this accursed red sky\n that would entice the creature?'},[61]={'+The Egg Enthusiast','Client: Ranpi-Monpi (Third Encampment,\n Abyssea - Grauberg)\nSummary:\n Ranpi-Monpi, culinarian extraordinaire,\n requires that you bring a fresh wivre\n egg from within the nesting grounds.\n Take extra care that the fragile egg\n is not damaged during transportation.'},[62]={'+Getting Lucky','Client: Kurou-Morou \n(Abyssea - Grauberg)\nSummary:\n Take your specified lucky item to\n the designated lucky spot, and good\n fortune will surely visit you...if\n Kurou-Morou the Magnificentaru\n speaks true.'},[63]={'+Her Father\'s Legacy','Client: Cornelia (First Encampment,\n Abyssea - Grauberg)\nSummary:\n For the survival of all those who call\n Grauberg home, Cornelia has assigned\n you the task of vanquishing the dread\n wyverns invariably seen in the company\n of the hydra Alfard.'},[64]={'The Mysterious Head Patrol','Client: Eight of Hearts\n (Abyssea - Grauberg)\nSummary:\n Who is the mystery person who\n patrols the head of Eight of Hearts?\n Find a vertically challenged individual\n attired in yellow who possesses a\n silver pocket watch, and you will find\n the answer.'},[65]={'Master Missing, Master Missed','Client: Eight of Clubs \n (Abyssea - Grauberg)\nSummary:\n Eight of Clubs is gravely concerned\n for his master, whose return is long\n overdue. Travel to the location where\n the man was headed, that you might\n glean knowledge to set the Cardian\'s\n mind at rest.'},[66]={'The Perils of Kororo','Client: Kororo \n (Abyssea - Grauberg)\nSummary:\n Caring young Kororo cannot help but\n worry about Eight of Clubs\' state of\n mind. Be a dear and check up on the\n Cardian in her stead.'},[67]={'+Let There Be Light','Client: Zauko (First Outpost,\n Abyssea - Uleguerand)\nSummary:\n Brother Zauko has entrusted you with\n a delivery of coal for the\n encampments, that the Divine Light\n of the Torch shall illuminate the\n realm now and forever.'},[68]={'+Look Out Below','Client: Baldric (Second Outpost,\n Abyssea - Uleguerand)\nSummary:\n Baldric seeks to put an end to the\n avalanches that plague the survivors\n by triggering small explosions to\n disperse accumulated snow. Assist him\n in an experiment to determine the\n optimal quantity of firesand for the\n task.'},[69]={'Home, Home on the Range','Client: Moogle (Third Outpost,\n Abyssea - Uleguerand)\nSummary:\n Bereft of hearth and home but not\n heart and hope, a beleaguered moogle\n has asked you to help him rebuild a\n small piece of his glory days.'},[70]={'Imperial Espionage','Client: Tyamah (Third Outpost,\n Abyssea - Uleguerand)\nSummary:\n A curious stranger from a distant land\n has tasked you with gathering\n information on the current state of\n the four nations of Altana.'},[71]={'Imperial Espionage II','Client: Tyamah (Third Outpost,\n Abyssea - Uleguerand)\nSummary:\n Stranded far from home and looking\n considerably worse for the wear,\n Tyamah has called upon your services\n again. Your mission, if you choose to\n accept it: use a soulgauger to gather\n intel on unfamiliar Abyssean fiends.'},[72]={'+Boreal Blossoms','Client: Oruga (First Outpost,\n Abyssea - Uleguerand)\nSummary:\n Having run out of a vital salve, Oruga\n has sent you in search of a rare\n flower that blooms in wintry climes.\n Three blossoms are required to\n extract a sufficient quantity of the\n reagent.'},[73]={'Brothers in Arms','Client: Zazarg (Third Outpost,\n Abyssea - Uleguerand)\nSummary:\n A vital linkpearl purloined by the vile\n Blanga, Zazarg lacks the means to\n contact his comrades. Retrieve the\n pearl, that he might confirm the\n safety of his countrymen.'},[74]={'+Scouts Astray','Client: Rondipur (Base Camp,\n Abyssea - Uleguerand)\nSummary:\n Rondipur\'s incompetent underlings\n have managed to get themselves lost\n on a routine scouting mission. Find\n them before they meet an untimely\n end.'},[75]={'+Frozen Flame Redux','Client: Guilboire (Third Outpost,\n Abyssea - Uleguerand)\nSummary:\n Following in the footsteps of his\n Crystal War veteran father, the\n enterprising Guilboire seeks to\n harness the power of snolls to strike\n back at the hordes. Travel to the test\n site and assist with data collection.'},[76]={'+Slip Slidin\' Away','Client: Michilca (Base Camp,\n Abyssea - Uleguerand)\nSummary:\n The Resistance seeks to send a strike\n team into the bowels of Thousandfall\n Ridge, a confirmed breeding pit for\n the hordes. Help keep Michilca\'s men\n on course as they execute their\n hazardous approach.'},[77]={'+Classrooms Without Borders','Client: Moreno-Toeno (Base Camp,\n Abyssea - Altepa)\nSummary:\n His classroom may be lost, but\n Moreno-Toeno is determined to\n educate the next generation here in\n the wastelands. Bring him three\n manigordo fangs so he can conduct\n a science class for his pupils.'},[78]={'+The Secret Ingredient','Client: Nogelle (Base Camp,\n Abyssea - Altepa)\nSummary:\n Bean chef extraordinaire Nogelle lost\n her entire supply of Lufet lake salt in\n her escape from San d\'Oria. Seek out\n a substitute ingredient, that she might\n put fire in the bellies of her fellow\n survivors with a piping pot of bean\n stew.'},[79]={'+Help Not Wanted','Client: Ken (Second Outpost,\n Abyssea - Altepa)\nSummary:\n A sniveling brat with an inferiority\n complex about never having graduated\n from military academy is too prideful\n to admit that he can\'t complete his\n mission on his own. Procure soul\n prints of the fiercest Abysseans for\n the ungrateful whelp.'},[80]={'The Titus Touch','Client: Titus (Third Outpost,\n Abyssea - Altepa)\n Summary: Alchemical genius Titus is\n at it again, his latest masterful\n creation being...ink. Deliver this\n practical (if not particularly exciting)\n product to medic team leader Chumimi\n at the first outpost, that she might\n complete her report.'},[81]={'+Slacking Subordinates','Client: Chumimi (First Outpost,\n Abyssea - Altepa)\nSummary:\n Chumimi\'s good-for-nothing assistants\n Chemioue, Biggorf, and Tapoh Lihzeh\n still haven\'t done their homework.\n Hunt them down and relay their\n findings to Chumimi by any means\n necessary.'},[82]={'Motherly Love','Client: Alisa (Fourth Outpost,\n Abyssea - Altepa)\nSummary:\n Alisa\'s dear husband Zacc and lovely\n daughter Enu have not returned from\n their little stroll outside the searing\n ward. Whatever could be keeping\n them...?'},[83]={'Look to the Sky','Client: Alisa (Fourth Outpost,\n Abyssea - Altepa)\nSummary:\n Finally at peace with the loss of her\n family, Alisa wishes you to bury her\n daughter Enu\'s favorite pendant in a\n spot as close to the sky as you can\n find. That\'s where the little girl\n would have wanted it...'},[84]={'The Unmarked Tomb','Client: Oiheaurese (First Outpost,\n Abyssea - Altepa)\nSummary:\n Doctor Oiheaurese, an authority on\n wyverns, has heard reports that a\n living wyvern egg lies buried beneath\n the shifting sands of Altepa. Can this\n elusive treasure be found...?'},[85]={'+Proof of the Lion','Client: Excenmille (Third Outpost,\n Abyssea - Altepa)\nSummary:\n Excenmille, hero of the Crystal War,\n is disheartened by the lack of\n fortitude shown by his fellow\n survivors. Show to him that you are\n different by slaying the dread waugyl\n and returning with proof of your\n triumph.'},[86]={'+Brygid the Stylist Strikes Back','Client: Brygid (Fourth Outpost,\n Abyssea - Altepa)\nSummary:\n Brygid, the self-professed stylist\n extraordinaire, has given you some\n fashion advice. Her pull-no-punches\n style of fashion critiques seems\n somehow familiar...'},[87]={'+Dominion Op #01 (Altepa)','Client: Dominion Sergeant\n (Abyssea - Altepa)\nSummary:\n Slay a prescribed quota of\n sand sweepers to further the\n Resistance effort in the area.\n After completing your objective,\n report back to any Dominion sergeant.'},[88]={'+Dominion Op #02 (Altepa)','Client: Dominion Sergeant\n (Abyssea - Altepa)\nSummary:\n Slay a prescribed quota of\n surveyors to further the\n Resistance effort in the area.\n After completing your objective,\n report back to any Dominion sergeant.'},[89]={'+Dominion Op #03 (Altepa)','Client: Dominion Sergeant\n (Abyssea - Altepa)\nSummary:\n Slay a prescribed quota of\n bonfires to further the\n Resistance effort in the area.\n After completing your objective,\n report back to any Dominion sergeant.'},[90]={'+Dominion Op #04 (Altepa)','Client: Dominion Sergeant\n (Abyssea - Altepa)\nSummary:\n Slay a prescribed quota of\n dune manticores to further the\n Resistance effort in the area.\n After completing your objective,\n report back to any Dominion sergeant.'},[91]={'+Dominion Op #05 (Altepa)','Client: Dominion Sergeant\n (Abyssea - Altepa)\nSummary:\n Slay a prescribed quota of\n manigordos to further the\n Resistance effort in the area.\n After completing your objective,\n report back to any Dominion sergeant.'},[92]={'+Dominion Op #06 (Altepa)','Client: Dominion Sergeant\n (Abyssea - Altepa)\nSummary:\n Slay a prescribed quota of\n camelopardalii to further the\n Resistance effort in the area.\n After completing your objective,\n report back to any Dominion sergeant.'},[93]={'+Dominion Op #07 (Altepa)','Client: Dominion Sergeant\n (Abyssea - Altepa)\nSummary:\n Slay a prescribed quota of\n desert puks to furt